-- Seed 7x10 dataset for NewsAppJS (real-source edition)
-- Source news + media: https://alikhbariah.com (WP REST + video_list pages)
-- Source video metadata: YouTube oEmbed for extracted IDs

begin;

-- =============================
-- 0) Compatibility columns
-- =============================
alter table if exists public.locations
  add column if not exists name_en text,
  add column if not exists slug text;

alter table if exists public.categories
  add column if not exists name_en text,
  add column if not exists type text not null default 'news',
  add column if not exists cover_image_url text;

alter table if exists public.news
  add column if not exists title_en text,
  add column if not exists summary text,
  add column if not exists summary_en text,
  add column if not exists content_en text,
  add column if not exists image_url text,
  add column if not exists category_id bigint,
  add column if not exists location_id bigint,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists is_hidden boolean not null default false,
  add column if not exists is_featured boolean not null default false,
  add column if not exists sent_notification boolean not null default true,
  add column if not exists view_count integer not null default 0;

alter table if exists public.breaking_news
  add column if not exists title text,
  add column if not exists title_en text,
  add column if not exists content text,
  add column if not exists content_en text,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists start_time timestamptz,
  add column if not exists end_time timestamptz,
  add column if not exists send_notification boolean not null default true,
  add column if not exists is_active boolean not null default true,
  add column if not exists view_count integer not null default 0;

alter table if exists public.videos
  add column if not exists title text,
  add column if not exists title_en text,
  add column if not exists youtube_url text,
  add column if not exists category_id bigint,
  add column if not exists thumbnail_url text,
  add column if not exists order_index integer not null default 0,
  add column if not exists published_at timestamptz,
  add column if not exists created_at timestamptz not null default now(),
  add column if not exists is_hidden boolean not null default false;

-- Accept program type in categories
do $$
begin
  if exists (
    select 1 from pg_constraint
    where conname = 'categories_type_check'
      and conrelid = 'public.categories'::regclass
  ) then
    alter table public.categories drop constraint categories_type_check;
  end if;

  alter table public.categories
    add constraint categories_type_check
    check (type in ('news', 'video', 'program'));
exception when duplicate_object then
  null;
end $$;

-- =============================
-- 1) Clear existing rows
-- =============================
truncate table public.ticker_news restart identity cascade;
truncate table public.breaking_news restart identity cascade;
truncate table public.news restart identity cascade;
truncate table public.videos restart identity cascade;
truncate table public.locations restart identity cascade;
delete from public.categories where coalesce(type, 'news') in ('news', 'video', 'program');

-- =============================
-- 2) Locations (Syrian governorates)
-- =============================
insert into public.locations (name, name_en, slug)
values
  ('Damascus', 'Damascus', 'damascus'),
  ('Rif Dimashq', 'Rif Dimashq', 'rif-dimashq'),
  ('Aleppo', 'Aleppo', 'aleppo'),
  ('Homs', 'Homs', 'homs'),
  ('Hama', 'Hama', 'hama'),
  ('Latakia', 'Latakia', 'latakia'),
  ('Tartus', 'Tartus', 'tartus'),
  ('Idlib', 'Idlib', 'idlib'),
  ('Raqqa', 'Raqqa', 'raqqa'),
  ('Deir ez-Zor', 'Deir ez-Zor', 'deir-ez-zor'),
  ('Al-Hasakah', 'Al-Hasakah', 'al-hasakah'),
  ('Daraa', 'Daraa', 'daraa'),
  ('As-Suwayda', 'As-Suwayda', 'as-suwayda'),
  ('Quneitra', 'Quneitra', 'quneitra')
on conflict (slug) do update
set name = excluded.name, name_en = excluded.name_en;

-- =============================
-- 3) News categories (7)
-- =============================
insert into public.categories (name, name_en, slug, order_index, type)
values
  ('سياسي', 'Politics', 'news-politics', 1, 'news'),
  ('اقتصاد', 'Economy', 'news-economy', 2, 'news'),
  ('محلي', 'Local', 'news-local', 3, 'news'),
  ('عربي ودولي', 'Arab and International', 'news-arab-international', 4, 'news'),
  ('رياضة', 'Sports', 'news-sports', 5, 'news'),
  ('ثقافة', 'Culture', 'news-culture', 6, 'news'),
  ('صحة', 'Health', 'news-health', 7, 'news')
on conflict (slug) do update
set name = excluded.name, name_en = excluded.name_en, order_index = excluded.order_index, type = excluded.type;

-- =============================
-- 4) 70 real news items (7 x 10)
-- =============================
insert into public.news (
  title, title_en, summary, summary_en, content, content_en,
  image_url, category_id, location_id, created_at,
  is_hidden, is_featured, sent_notification, view_count
)
values
  ('تنديد عربي ودولي بمشروع قانون إعدام الأسرى الفلسطينيين', 'Arab and international condemnation of the draft law on executing Palestinian prisoners', 'أعربت دول عربية وأجنبية عن رفضها للخطوة الإسرائيلية بإقرار لجنة الأمن القومي بالكنيست (البرلمان) مشروع قانون إعدام الأسرى الفلسطينيين. وذكرت وزارة الخارجية المصرية في بيان لها نشرته يوم الثلاثاء 31 آذار الفائت، إن إقدام إسرائيل على إقرار قانون إعدام الأسرى الفلسطينيين، “خطوة تمثل تصعيدًا خطيرًا وغيرَ مسبوقٍ يكرس نهجًا تمييزيًا ويعزز نظام الفصل العنصري”. وطالبت […]', 'Arab and foreign countries expressed their rejection of the Israeli move to have the Knesset (Parliament) National Security Committee approve a draft law on the execution of Palestinian prisoners. The Egyptian Ministry of Foreign Affairs stated in a statement published on Tuesday, March 31, that Egdam Israel approved the death penalty law for Palestinian prisoners, “a step that represents a dangerous and unprecedented escalation that establishes a discriminatory approach and strengthens the apartheid regime.” She demanded […]', 'أعربت دول عربية وأجنبية عن رفضها للخطوة الإسرائيلية بإقرار لجنة الأمن القومي بالكنيست (البرلمان) مشروع قانون إعدام الأسرى الفلسطينيين. وذكرت وزارة الخارجية المصرية في بيان لها نشرته يوم الثلاثاء 31 آذار الفائت، إن إقدام إسرائيل على إقرار قانون إعدام الأسرى الفلسطينيين، “خطوة تمثل تصعيدًا خطيرًا وغيرَ مسبوقٍ يكرس نهجًا تمييزيًا ويعزز نظام الفصل العنصري”. وطالبت مصر المجتمع الدولي بالاضطلاع بمسؤولياته القانونية والأخلاقية واتخاذ مواقف حازمة وفورية لوقف هذه “الانتهاكات السافرة وضمان حماية الشعب الفلسطيني وفقًا لقرارات الشرعية الدولية”. وأدانت وزارة الخارجية العراقية، في بيانٍ أيضًا، تصديق الكنيست على قانون إعدام الأسرى الفلسطينيين، واعتبرته “تصعيدًا خطيرًا وخرقًا جسيمًا”. كما أدانت الكويت، خلال كلمة مندوبها الدائم لدى الأمم المتحدة السفير ناصر الهين أمام المجلس الأممي، “بأشد العبارات، إقرار برلمان الاحتلال الإسرائيلي قانون إعدام الأسرى الفلس Source: https://alikhbariah.com/%d8%aa%d9%86%d8%af%d9%8a%d8%af-%d8%b9%d8%b1%d8%a8%d9%8a-%d9%88%d8%af%d9%88%d9%84%d9%8a-%d8%a8%d9%85%d8%b4%d8%b1%d9%88%d8%b9-%d9%82%d8%a7%d9%86%d9%88%d9%86-%d8%a5%d8%b9%d8%af%d8%a7%d9%85-%d8%a7%d9%84/', 'Arab and foreign countries expressed their rejection of the Israeli move to have the Knesset (Parliament) National Security Committee approve a draft law on the execution of Palestinian prisoners. The Egyptian Ministry of Foreign Affairs stated in a statement published on Tuesday, March 31, that Egdam Israel approved the death penalty law for Palestinian prisoners, “a step that represents a dangerous and unprecedented escalation that establishes a discriminatory approach and strengthens the apartheid regime.” Egypt called on the international community to fulfill its legal and moral responsibilities and take positions Firm and immediate to stop these “flagrant violations and ensure the protection of the Palestinian people in accordance with the resolutions of international legitimacy.” The Iraqi Ministry of Foreign Affairs also condemned, in a statement, the Knesset’s ratification of the Palestinian prisoners’ death penalty law, and considered it “an escalation.” During the speech of its Permanent Representative to the United Nations, Ambassador Nasser Al-Hein, before the UN Council, Kuwait also condemned, “in the strongest terms, the Israeli occupation parliament’s approval of the law to execute Palestinian prisoners.” Source: https://alikhbariah.com/%d8%aa%d9%86%d8%af%d9%8a%d8%af-%d8%b9%d8%b1%d8%a8%d9%8a-%d9%88%d8%af%d9%88%d9%84%d9%8a -%d8%a8%d9%85%d8%b4%d8%b1%d9%88%d8%b9-%d9%82%d8%a7%d9%86%d9%88%d9%86-%d8%a5%d8%b9%d8%af%d8%a7%d9%85-%d8%a7%d9% 84/', 'https://alikhbariah.com/wp-content/uploads/2026/04/thumbs_b_c_a4ba17fcc7f6ed18d1e83298d01731a9_edit_42569953968759.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 0 limit 1), '2026-04-01T00:35:44+03:00'::timestamptz, false, true, false, 190),
  ('الرئيس الشرع يؤكد دور الجالية في بريطانيا في دعم القضايا الوطنية', 'President Al-Sharaa emphasizes the role of the community in Britain in supporting national issues', 'التقى السيد الرئيس أحمد الشرع والوفد المرافق، وفداً من أبناء الجالية السورية في لندن، وذلك على هامش زيارته الرسمية إلى المملكة المتحدة. وأكد السيد الرئيس خلال اللقاء على أهمية دور الجالية في نقل الصورة الحقيقية عن بلدهم ودعم قضاياه العادلة، مشيرا إلى الجهود الوطنية التي يبذلها السوريون في الخارج، بحسب ما نشرت رئاسة الجمهوري عبر […]', 'Mr. President Ahmed Al-Sharaa and the accompanying delegation met with a delegation from the Syrian community in London, on the sidelines of his official visit to the United Kingdom. During the meeting, Mr. President stressed the importance of the community’s role in conveying the true image of their country And support his just causes, pointing to the national efforts made by Syrians abroad, according to what the Republican Presidency published via […]', 'التقى السيد الرئيس أحمد الشرع والوفد المرافق، وفداً من أبناء الجالية السورية في لندن، وذلك على هامش زيارته الرسمية إلى المملكة المتحدة. وأكد السيد الرئيس خلال اللقاء على أهمية دور الجالية في نقل الصورة الحقيقية عن بلدهم ودعم قضاياه العادلة، مشيرا إلى الجهود الوطنية التي يبذلها السوريون في الخارج، بحسب ما نشرت رئاسة الجمهوري عبر معرفاتها الرسمية 1 نيسان. كما استمع الرئيس الشرع إلى مداخلات ومقترحات الحضور، مؤكداً حرصه على تعزيز الحوار والتواصل مع الجالية السورية في مختلف الدول. وسبق ذلك، لقاء جمع السيد الرئيس في لندن مع ممثلين عن كبرى الشركات البريطانية ورجال الأعمال البريطانيين والسوريين. وقال السيد الرئيس أحمد الشرع خلال اللقاء ، إن “سوريا تشكل فرصة مهمة للجميع، وهي من أفضل الفرص الاستثمارية في العالم”، وفق ما نقلت وكالة سانا. وأضاف السيد الرئيس، “نحن في صراع حقيقي في معركة إعادة إعمار بلدنا المدمر”. وخلال الاجتماع جرى بحث سبل تعزيز التعا Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%a4%d9%83%d8%af-%d8%af%d9%88%d8%b1-%d8%a7%d9%84%d8%ac%d8%a7%d9%84%d9%8a%d8%a9-%d9%81%d9%8a-%d8%a8%d8%b1%d9%8a%d8%b7%d8%a7/', 'Mr. President Ahmed Al-Sharaa and the accompanying delegation met with a delegation from the Syrian community in London, on the sidelines of his official visit to the United Kingdom. During the meeting, Mr. President stressed the importance of the community’s role in conveying the true image of their country He supported his just causes, pointing to the national efforts made by Syrians abroad, according to what the Presidency of the Republic published through its official accounts on April 1. President Al-Sharaa also listened to the attendees’ interventions and suggestions, stressing his keenness to enhance dialogue And communication with the Syrian community in various countries. This was preceded by a meeting that brought together Mr. President in London with representatives of major British companies and British and Syrian businessmen. Mr. President Ahmed Al-Sharaa said during the meeting, “Syria is forming An important opportunity for everyone, and it is one of the best investment opportunities in the world,” according to what SANA reported. Mr. President added, “We are in a real conflict in the battle to rebuild our destroyed country.” During the meeting, ways to enhance cooperation were discussed. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%a4%d9%83 %d8%af-%d8%af%d9%88%d8%b1-%d8%a7%d9%84%d8%ac%d8%a7%d9%84%d9%8a%d8%a9-%d9%81%d9%8a-%d8%a8%d8%b1%d9%8a%d8%b7%d8% a7/', 'https://alikhbariah.com/wp-content/uploads/2026/04/IMG_20260401_025850_538_edit_41015243938519.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 1 limit 1), '2026-04-01T00:03:10+03:00'::timestamptz, false, true, false, 189),
  ('الشرع: حصر السلاح بيد الدولة والأولوية للعدالة الانتقالية', 'Al-Sharaa: Limiting weapons to the state and giving priority to transitional justice', 'أكد السيد الرئيس أحمد الشرع، أن الدولة السورية عملت منذ وصولها إلى دمشق على حصر السلاح بيدها وفرض سيادة القانون، مشدداً على أنه لا يمكن أن تكون في سوريا فصائل أو جماعات مسلحة، وأن العدالة الانتقالية تمثل أولوية لضمان محاسبة مرتكبي الجرائم. جاء ذلك خلال مشاركته في جلسة حوارية في المعهد الملكي للشؤون الدولية “تشاتام […]', 'Mr. President Ahmed Al-Sharaa confirmed that the Syrian state has worked since its arrival in Damascus to control weapons and impose the rule of law, stressing that there cannot be factions or armed groups in Syria, and that transitional justice represents a priority to ensure Holding perpetrators of crimes accountable. This came during his participation in a dialogue session at the Royal Institute of International Affairs “Chatham […]', 'أكد السيد الرئيس أحمد الشرع، أن الدولة السورية عملت منذ وصولها إلى دمشق على حصر السلاح بيدها وفرض سيادة القانون، مشدداً على أنه لا يمكن أن تكون في سوريا فصائل أو جماعات مسلحة، وأن العدالة الانتقالية تمثل أولوية لضمان محاسبة مرتكبي الجرائم. جاء ذلك خلال مشاركته في جلسة حوارية في المعهد الملكي للشؤون الدولية “تشاتام هاوس” في العاصمة البريطانية لندن. وأشار السيد الرئيس إلى أن بريطانيا ساهمت في دعم سوريا ورفع العقوبات عن الشعب السوري، مبيناً أن اللقاءات التي أجريت اليوم كانت مثمرة وستعزز العلاقات بين البلدين، بحسب ما أوردت وكالة سانا الثلاثاء 31 آذار . وأوضح الشرع، أن الحكومة أجرت حواراً وطنياً نتجت عنه توصيات والإعلان الدستوري، إضافة إلى إجراء انتخابات مجلس الشعب، لافتاً إلى أن المجلس سيعقد جلسته الأولى الشهر المقبل، تمهيداً للوصول إلى انتخابات حرة مع نهاية المرحلة الانتقالية. وعن ملف قسد، قال السيد الرئيس، إن اتفاق دمج “قسد” في مؤسسات الدول Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d8%ad%d8%b5%d8%b1-%d8%a7%d9%84%d8%b3%d9%84%d8%a7%d8%ad-%d8%a8%d9%8a%d8%af-%d8%a7%d9%84%d8%af%d9%88%d9%84%d8%a9-%d9%88%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%88%d9%8a%d8%a9/', 'Mr. President Ahmed Al-Sharaa confirmed that the Syrian state has worked since its arrival in Damascus to control weapons and impose the rule of law, stressing that there cannot be factions or armed groups in Syria, and that transitional justice represents a priority to ensure Holding perpetrators of crimes accountable. This came during his participation in a dialogue session at the Royal Institute of International Affairs “Chatham House” in the British capital, London. Mr. President pointed out that Britain contributed to supporting Syria and lifting sanctions on the Syrian people. Pointing out that the meetings held today were fruitful and will strengthen relations between the two countries, according to what SANA reported on Tuesday, March 31. Al-Sharaa explained that the government conducted a national dialogue that resulted in recommendations and the constitutional declaration, in addition to a measure People''s Assembly elections, pointing out that the Council will hold its first session next month, in preparation for reaching free elections at the end of the transitional phase. Regarding the SDF file, Mr. President said that the agreement to integrate “SDF” into state institutions Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d8%ad%d8%b5%d8%b1-%d8%a7%d9%84%d8%b3%d9%84%d8%a7%d8%ad -%d8%a8%d9%8a%d8%af-%d8%a7%d9%84%d8%af%d9%88%d9%84%d8%a9-%d9%88%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%88%d9%8a%d8%a 9/', 'https://alikhbariah.com/wp-content/uploads/2026/03/President-Ahmed-Al-Sharaa-11.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 2 limit 1), '2026-03-31T19:44:09+03:00'::timestamptz, false, false, false, 188),
  ('محافظ الرقة يبحث مع مفوضية اللاجئين خطة الاستجابة الإنسانية للعائدين من لبنان', 'The Governor of Raqqa discusses with the UNHCR the humanitarian response plan for those returning from Lebanon', 'ناقش محافظ الرقة، الثلاثاء 31 آذار، مع وفد من المفوضية السامية للأمم المتحدة لشؤون اللاجئين، خطة الاستجابة الإنسانية للعائدين من لبنان إلى المحافظة، إلى جانب أوضاع المخيمات واحتياجاتها. وأكد الجانبان خلال اللقاء، حسب ما نشرت محافظة الرقة عبر معرفاتها الرسمية، ضرورة تعزيز التنسيق بما يسهم في تحسين مستوى الخدمات المقدمة خلال المرحلة المقبلة. وجاءت الزيارة […]', 'On Tuesday, March 31, the governor of Raqqa discussed with a delegation from the United Nations High Commissioner for Refugees the humanitarian response plan for those returning from Lebanon to the governorate, in addition to the conditions and needs of the camps. The two sides confirmed during the meeting, according to Ma Raqqa Governorate published, through its official accounts, the need to strengthen coordination in a way that contributes to improving the level of services provided during the next stage. The visit came [...]', 'ناقش محافظ الرقة، الثلاثاء 31 آذار، مع وفد من المفوضية السامية للأمم المتحدة لشؤون اللاجئين، خطة الاستجابة الإنسانية للعائدين من لبنان إلى المحافظة، إلى جانب أوضاع المخيمات واحتياجاتها. وأكد الجانبان خلال اللقاء، حسب ما نشرت محافظة الرقة عبر معرفاتها الرسمية، ضرورة تعزيز التنسيق بما يسهم في تحسين مستوى الخدمات المقدمة خلال المرحلة المقبلة. وجاءت الزيارة التي أجراها الوفد بتنسيق من إدارة التعاون الدولي، وضمّ كلاً من مدير مكتب القامشلي أوليفر، ومسؤولة الحماية فلونة. وكانت المتحدثة باسم مفوضية الأمم المتحدة لشؤون اللاجئين في سوريا سيلين شميت، قد قالت في 9 آذار الجاري إن أكثر من 80 ألف سوري عبروا الحدود من لبنان إلى سوريا منذ الثاني من آذار الجاري. وأشارت إلى أن المفوضية تعمل بشكل وثيق مع الحكومة السورية على المستويين المركزي والمحلي لتقديم الدعم اللازم للوافدين، بحسب ما نقلته وكالة “سانا”. وتشهد المنافذ الحدودية بين سوريا ولبنان حركة عودة كث Source: https://alikhbariah.com/%d9%85%d8%ad%d8%a7%d9%81%d8%b8-%d8%a7%d9%84%d8%b1%d9%82%d8%a9-%d9%8a%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d9%85%d9%81%d9%88%d8%b6%d9%8a%d8%a9-%d8%a7%d9%84%d9%84%d8%a7%d8%ac%d8%a6%d9%8a%d9%86-%d8%ae%d8%b7/', 'On Tuesday, March 31, the governor of Raqqa discussed with a delegation from the United Nations High Commissioner for Refugees the humanitarian response plan for those returning from Lebanon to the governorate, in addition to the conditions and needs of the camps. The two sides confirmed during the meeting, according to Ma Raqqa Governorate published, through its official accounts, the need to strengthen coordination in a way that contributes to improving the level of services provided during the next stage. The visit conducted by the delegation was coordinated by the Department of International Cooperation, and included the director of the Qamishli office Oliver, and Protection Officer Flona. The spokeswoman for the United Nations High Commissioner for Refugees in Syria, Celine Schmidt, said on March 9 that more than 80,000 Syrians have crossed the border from Lebanon into Syria since March 2. She indicated that the Commission is working closely with the Syrian government at the central and local levels to provide the necessary support to the arrivals, according to what was reported by SANA. The border crossings between Syria and Lebanon are witnessing heavy return movement. Source: https://alikhbariah.com/%d9%85%d8%ad%d8%a7%d9%81%d8%b8-%d8%a7%d9%84%d8%b1%d9%82%d8%a9-%d9%8a%d8%a8%d8%ad%d8%ab -%d9%85%d8%b9-%d9%85%d9%81%d9%88%d8%b6%d9%8a%d8%a9-%d8%a7%d9%84%d9%84%d8%a7%d8%ac%d8%a6%d9%8a%d9%86-%d8%ae%d8% b7/', 'https://alikhbariah.com/wp-content/uploads/2026/03/A-delegation-from-the-commission-in-Raqqa.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 3 limit 1), '2026-03-31T17:50:38+03:00'::timestamptz, false, false, false, 187),
  ('هيئة المنافذ تبحث مع بعثة الاتحاد الأوروبي تطوير أداء المنافذ الحدودية', 'The Ports Authority discusses with the European Union delegation the development of the performance of border crossings', 'بحث رئيس الهيئة العامة للمنافذ والجمارك قتيبة بدوي، مع القائم بأعمال بعثة الاتحاد الأوروبي لدى سوريا ميخائيل أونماخت، والوفد المرافق له، آفاق التعاون المشترك بين الجانبين في المجالات المرتبطة بعمل المنافذ الحدودية. وخلال الاجتماع الذي عقد في مقر الهيئة بدمشق، الثلاثاء 31 آذار، استعرض رئيس الهيئة طبيعة عمل الهيئة، وآخر الإنجازات والإجراءات المتخذة لتطوير أداء […]', 'The head of the General Authority of Ports and Customs, Qutaiba Badawi, discussed with the Chargé d''Affaires of the European Union delegation to Syria, Michael Unmacht, and his accompanying delegation, the prospects for joint cooperation between the two sides in areas related to the work of border crossings. During the meeting held at the Authority’s headquarters in Damascus, Tuesday, March 31, the Chairman of the Authority reviewed the nature of the Authority’s work, the latest achievements and the measures taken to develop the performance […]', 'بحث رئيس الهيئة العامة للمنافذ والجمارك قتيبة بدوي، مع القائم بأعمال بعثة الاتحاد الأوروبي لدى سوريا ميخائيل أونماخت، والوفد المرافق له، آفاق التعاون المشترك بين الجانبين في المجالات المرتبطة بعمل المنافذ الحدودية. وخلال الاجتماع الذي عقد في مقر الهيئة بدمشق، الثلاثاء 31 آذار، استعرض رئيس الهيئة طبيعة عمل الهيئة، وآخر الإنجازات والإجراءات المتخذة لتطوير أداء المنافذ الحدودية ورفع كفاءتها. في المقابل، أعرب الوفد الأوروبي عن اهتمامه بتعزيز التعاون في المجالات المرتبطة بعمل المنافذ الحدودية، ولا سيما ما يتعلق بتطوير الإجراءات ورفع كفاءة الأداء. وأكد الوفد خلال اللقاء أيضاً على أهمية استمرار التنسيق والتواصل بما يخدم المصالح المشتركة ويدعم جهود التعافي وإعادة الإعمار. وفي 14 كانون الثاني الماضي، بحث رئيس الهيئة مع القائم بأعمال السفارة الفرنسية في دمشق جان باتيست فايفر، سبل تطوير التعاون والدعم التقني، وآفاق الشراكة الثنائية بين الجانبين. ونا Source: https://alikhbariah.com/%d9%87%d9%8a%d8%a6%d8%a9-%d8%a7%d9%84%d9%85%d9%86%d8%a7%d9%81%d8%b0-%d8%aa%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d8%a8%d8%b9%d8%ab%d8%a9-%d8%a7%d9%84%d8%a7%d8%aa%d8%ad%d8%a7%d8%af-%d8%a7%d9%84%d8%a3%d9%88/', 'The head of the General Authority of Ports and Customs, Qutaiba Badawi, discussed with the Chargé d''Affaires of the European Union delegation to Syria, Michael Unmacht, and his accompanying delegation, the prospects for joint cooperation between the two sides in areas related to the work of border crossings. During the meeting held at the authority’s headquarters in Damascus, Tuesday, March 31, the head of the authority reviewed the nature of the authority’s work, the latest achievements and the measures taken to develop the performance of the border crossings and raise their efficiency. On the other hand, the European delegation expressed its interest By enhancing cooperation in areas related to the work of border crossings, especially with regard to developing procedures and raising performance efficiency. During the meeting, the delegation also stressed the importance of continuing coordination and communication to serve common interests and support efforts Recovery and reconstruction. Last January 14, the head of the authority discussed with the Chargé d''Affaires of the French Embassy in Damascus, Jean-Baptiste Pfeiffer, ways to develop cooperation and technical support, and the prospects for bilateral partnership between the two sides. Source: https://alikhbariah.com/%d9%87%d9%8a%d8%a6%d8%a9-%d8%a7%d9%84%d9%85%d9%86%d8%a7%d9%81%d8%b0-%d8%aa%d8%a8%d8%ad %d8%ab-%d9%85%d8%b9-%d8%a8%d8%b9%d8%ab%d8%a9-%d8%a7%d9%84%d8%a7%d8%aa%d8%ad%d8%a7%d8%af-%d8%a7%d9%84%d8%a3%d9% 88/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Qutaiba-Badawi.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 4 limit 1), '2026-03-31T17:20:05+03:00'::timestamptz, false, false, false, 186),
  ('الرئيس الشرع يبحث مع وزيرة الداخلية البريطانية آليات التعاون والتنسيق المشتركة', 'President Al-Shara discusses with the British Home Secretary joint cooperation and coordination mechanisms', 'اجتمع السيد الرئيس أحمد الشرع، الثلاثاء 31 آذار، بوزيرة الداخلية البريطانية شبانة محمود، بحضور وزير الخارجية والمغتربين أسعد الشيباني ورئيس جهاز الاستخبارات العامة حسين السلامة، حيث جرى بحث سبل تطوير التعاون بين الجانبين. وأكد الطرفان خلال اللقاء، حسب ما نشرت رئاسة الجمهورية العربية السورية عبر معرفاتها الرسمية، أهمية تعزيز التنسيق وتبادل الخبرات، بما يسهم في […]', 'On Tuesday, March 31, Mr. President Ahmed Al-Sharaa met with the British Minister of the Interior, Shabana Mahmoud, in the presence of the Minister of Foreign Affairs and Expatriates, Asaad Al-Shaibani, and the head of the General Intelligence Service, Hussein Al-Salama, where they discussed ways to develop cooperation between... sides. During the meeting, the two parties stressed, according to what was published by the Presidency of the Syrian Arab Republic through its official accounts, the importance of strengthening coordination and exchanging experiences, which contributes to [...]', 'اجتمع السيد الرئيس أحمد الشرع، الثلاثاء 31 آذار، بوزيرة الداخلية البريطانية شبانة محمود، بحضور وزير الخارجية والمغتربين أسعد الشيباني ورئيس جهاز الاستخبارات العامة حسين السلامة، حيث جرى بحث سبل تطوير التعاون بين الجانبين. وأكد الطرفان خلال اللقاء، حسب ما نشرت رئاسة الجمهورية العربية السورية عبر معرفاتها الرسمية، أهمية تعزيز التنسيق وتبادل الخبرات، بما يسهم في تعزيز الاستقرار ومواجهة التحديات المشتركة. وكان الرئيس الشرع قد التقى في وقت سابق من اليوم خلال زيارته الرسمية إلى المملكة المتحدة، رئيس الوزراء البريطاني كير ستارمر، بحضور وزير الخارجية والمغتربين أسعد الشيباني ووزير الاقتصاد نضال الشعار، وفقاً لما نشرته رئاسة الجمهورية. وبحسب رئاسة الجمهورية، فإن الجانبين بحثا سبل تعزيز العلاقات الثنائية بما يحقق المصالح المشتركة للبلدين، مؤكدين أهمية تطوير التعاون في مجالات التنمية والاستثمار، كما تطرّقا إلى مستجدات القضايا الإقليمية والدولية. ووص Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d9%88%d8%b2%d9%8a%d8%b1%d8%a9-%d8%a7%d9%84%d8%af%d8%a7%d8%ae%d9%84%d9%8a%d8%a9-%d8%a7%d9%84/', 'On Tuesday, March 31, Mr. President Ahmed Al-Sharaa met with the British Minister of the Interior, Shabana Mahmoud, in the presence of the Minister of Foreign Affairs and Expatriates, Asaad Al-Shaibani, and the head of the General Intelligence Service, Hussein Al-Salama, where they discussed ways to develop cooperation between... sides. During the meeting, the two parties stressed, according to what was published by the Presidency of the Syrian Arab Republic through its official accounts, the importance of enhancing coordination and exchanging experiences, which contributes to enhancing stability and confronting common challenges. President Al-Sharaa had met Earlier today, during his official visit to the United Kingdom, British Prime Minister Keir Starmer, in the presence of the Minister of Foreign Affairs and Emigrants, Asaad Al-Shaibani, and the Minister of Economy, Nidal Al-Shaar, according to what was published by the Presidency of the Republic. According to the presidency Republic, the two sides discussed ways to enhance bilateral relations in a way that achieves the common interests of the two countries, stressing the importance of developing cooperation in the fields of development and investment, and they also touched on the latest developments in regional and international issues. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%a8%d8%ad %d8%ab-%d9%85%d8%b9-%d9%88%d8%b2%d9%8a%d8%b1%d8%a9-%d8%a7%d9%84%d8%af%d8%a7%d8%ae%d9%84%d9%8a%d8%a9-%d8%a7%d9% 84/', 'https://alikhbariah.com/wp-content/uploads/2026/03/President-Sharia-5.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 5 limit 1), '2026-03-31T16:26:05+03:00'::timestamptz, false, false, false, 185),
  ('المجلس السوري البريطاني يرحب بزيارة الرئيس الشرع إلى لندن ويدعو لتعزيز التعاون', 'The Syrian-British Council welcomes President Al-Sharaa''s visit to London and calls for strengthening cooperation', 'رحب المجلس السوري البريطاني (SBC) بزيارة الرئيس أحمد الشرع إلى المملكة المتحدة، الثلاثاء 31 آذار، واصفاً إياها بالخطوة المهمة نحو فتح صفحة جديدة في العلاقات السورية-البريطانية. وأكد المجلس أن هذه الزيارة تمثل فرصة جوهرية لإعادة ضبط التعاون الثنائي على أسس بناءة وتطلعية، ترتكز على المصالح المشتركة والاحترام المتبادل، وخاصة في ظل المرحلة الدقيقة التي تمر […]', 'The Syrian-British Council (SBC) welcomed the visit of President Ahmed al-Sharaa to the United Kingdom, Tuesday, March 31, describing it as an important step towards opening a new page in Syrian-British relations. The Council stressed that this visit represents an opportunity Essential for resetting bilateral cooperation on constructive and forward-looking foundations, based on common interests and mutual respect, especially in light of the delicate stage that […]', 'رحب المجلس السوري البريطاني (SBC) بزيارة الرئيس أحمد الشرع إلى المملكة المتحدة، الثلاثاء 31 آذار، واصفاً إياها بالخطوة المهمة نحو فتح صفحة جديدة في العلاقات السورية-البريطانية. وأكد المجلس أن هذه الزيارة تمثل فرصة جوهرية لإعادة ضبط التعاون الثنائي على أسس بناءة وتطلعية، ترتكز على المصالح المشتركة والاحترام المتبادل، وخاصة في ظل المرحلة الدقيقة التي تمر بها سوريا بعد سقوط النظام البائد، وبروز فرصة حقيقية لإعادة بناء البلاد على هذه المبادئ، على الرغم من التحديات المستمرة الموروثة عن النظام البائد، وفقاً لما نشره عبر صفحته في منصة “فيسبوك” . وأعرب المجلس عن أمله في أن تسهم الزيارة، واللقاء المقرر بين الرئيس الشرع وأفراد الجالية السورية في المملكة المتحدة، في تعزيز قنوات التواصل ونقل تطلعات المغتربين مباشرة، ولا سيما فيما يتعلق بقضايا رئيسية كالعدالة الانتقالية. وحول تمتع المغتربين السوريين بموقع فريد يتيح لهم المساهمة بشكل هادف في نهضة سوريا Source: https://alikhbariah.com/%d8%a7%d9%84%d9%85%d8%ac%d9%84%d8%b3-%d8%a7%d9%84%d8%b3%d9%88%d8%b1%d9%8a-%d8%a7%d9%84%d8%a8%d8%b1%d9%8a%d8%b7%d8%a7%d9%86%d9%8a-%d9%8a%d8%b1%d8%ad%d8%a8-%d8%a8%d8%b2%d9%8a%d8%a7%d8%b1%d8%a9-%d8%a7/', 'The Syrian-British Council (SBC) welcomed the visit of President Ahmed al-Sharaa to the United Kingdom, Tuesday, March 31, describing it as an important step towards opening a new page in Syrian-British relations. The Council stressed that this visit represents an opportunity Essential for resetting bilateral cooperation on constructive and forward-looking foundations, based on common interests and mutual respect, especially in light of the delicate stage that Syria is going through after the fall of the former regime, and the emergence of a real opportunity to rebuild the country on this basis. principles, despite the ongoing challenges inherited from the former regime, according to what he published on his page on the “Facebook” platform. The Council expressed its hope that the visit and the scheduled meeting between President Al-Sharaa and members of the Syrian community in the Kingdom would contribute United Nations, in strengthening communication channels and conveying the aspirations of expatriates directly, especially with regard to key issues such as transitional justice. And about the Syrian expatriates enjoying a unique position that allows them to contribute meaningfully to the renaissance of Syria. Source: https://alikhbariah.com/%d8%a7%d9%84%d9%85%d8%ac%d9%84%d8%b3-%d8%a7%d9%84%d8%b3%d9%88%d8%b1%d9%8a-%d8%a7%d9%84 %d8%a8%d8%b1%d9%8a%d8%b7%d8%a7%d9%86%d9%8a-%d9%8a%d8%b1%d8%ad%d8%a8-%d8%a8%d8%b2%d9%8a%d8%a7%d8%b1%d8%a9-%d8%a 7/', 'https://alikhbariah.com/wp-content/uploads/2026/03/President-Sharia-4.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 6 limit 1), '2026-03-31T15:42:26+03:00'::timestamptz, false, false, false, 184),
  ('مجلس حقوق الإنسان يعتمد القرار المعني بحقوق الإنسان في الجولان السوري المحتل', 'The Human Rights Council adopts the resolution on human rights in the occupied Syrian Golan', 'أعلن مجلس حقوق الإنسان التابع للأمم المتحدة اعتماد مشروع القرار (L.8) المعني بحقوق الإنسان في الجولان السوري المحتل، وذلك خلال أعمال الدورة الحادية والستين للمجلس. وقال المجلس عبر منصة “X”، الثلاثاء 31 آذار: ” تم اعتماد مشروع القرار A/HRC/61/L.8 المعني بحقوق الإنسان في الجولان السوري المحتل، ليصبح بذلك قراراً معتمداً رسمياً عن المجلس”. وكان مجلس حقوق […]', 'The United Nations Human Rights Council announced the adoption of draft resolution (L.8) on human rights in the occupied Syrian Golan, during the work of the sixty-first session of the Council. The Council said on the “X” platform, Tuesday, March 31: “It has been approved.” Draft resolution A/HRC/61/L.8 on human rights in the occupied Syrian Golan, thus becoming an officially adopted resolution by the Council.” The Human Rights Council […]', 'أعلن مجلس حقوق الإنسان التابع للأمم المتحدة اعتماد مشروع القرار (L.8) المعني بحقوق الإنسان في الجولان السوري المحتل، وذلك خلال أعمال الدورة الحادية والستين للمجلس. وقال المجلس عبر منصة “X”، الثلاثاء 31 آذار: ” تم اعتماد مشروع القرار A/HRC/61/L.8 المعني بحقوق الإنسان في الجولان السوري المحتل، ليصبح بذلك قراراً معتمداً رسمياً عن المجلس”. وكان مجلس حقوق الإنسان اعتمد في وقت سابق، قراراً يدين فيه السياسات الاستيطانية للاحتلال الإسرائيلي في الجولان السوري المحتل ومحاولات تغيير الوضع القانوني والطابع الديمغرافي والعمراني فيه كما طالب “إسرائيل” بوقفها على الفور. Source: https://alikhbariah.com/%d9%85%d8%ac%d9%84%d8%b3-%d8%ad%d9%82%d9%88%d9%82-%d8%a7%d9%84%d8%a5%d9%86%d8%b3%d8%a7%d9%86-%d9%8a%d8%b9%d8%aa%d9%85%d8%af-%d8%a7%d9%84%d9%82%d8%b1%d8%a7%d8%b1-%d8%a7%d9%84%d9%85%d8%b9%d9%86%d9%8a/', 'The United Nations Human Rights Council announced the adoption of draft resolution (L.8) on human rights in the occupied Syrian Golan, during the work of the sixty-first session of the Council. The Council said on the “X” platform, Tuesday, March 31: “It has been approved.” Draft resolution A/HRC/61/L.8 on human rights in the occupied Syrian Golan, thus becoming an officially approved resolution by the Council.” The Human Rights Council had previously adopted a resolution condemning the settlement policies of the Israeli occupation in The occupied Syrian Golan and attempts to change the legal status and demographic and urban character therein. He also called on “Israel” to stop them immediately. Source: https://alikhbariah.com/%d9%85%d8%ac%d9%84%d8%b3-%d8%ad%d9%82%d9%88%d9%82-%d8%a7%d9%84%d8%a5%d9%86%d8%b3%d8%a7 %d9%86-%d9%8a%d8%b9%d8%aa%d9%85%d8%af-%d8%a7%d9%84%d9%82%d8%b1%d8%a7%d8%b1-%d8%a7%d9%84%d9%85%d8%b9%d9%86%d9%8 a/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Human-Rights-Council.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 7 limit 1), '2026-03-31T12:30:37+03:00'::timestamptz, false, false, false, 183),
  ('أبناء الجالية السورية في بريطانيا يتجمعون أمام البرلمان ترحيباً بالرئيس الشرع', 'Members of the Syrian community in Britain gather in front of Parliament to welcome President Al-Sharaa', 'تجمع أبناء الجالية السورية في المملكة المتحدة البريطانية أمام مقر البرلمان، الثلاثاء 31 آذار، ترحيباً بالسيد الرئيس أحمد الشرع خلال زيارته الرسمية إلى لندن، وفقاً لما نقلته وكالة سانا. وأعرب أبناء الجالية السورية عن سعادتهم بهذه الزيارة، مؤكدين دعمهم لجهود الحكومة في تعزيز العلاقات الثنائية وتطوير التعاون بين سوريا والمملكة المتحدة في مختلف المجالات. وكان […]', 'Members of the Syrian community in the United Kingdom gathered in front of Parliament, on Tuesday, March 31, to welcome President Ahmed Al-Sharaa during his official visit to London, according to SANA. Members of the Syrian community expressed They were pleased with this visit, stressing their support for the government’s efforts to strengthen bilateral relations and develop cooperation between Syria and the United Kingdom in various fields. And it was […]', 'تجمع أبناء الجالية السورية في المملكة المتحدة البريطانية أمام مقر البرلمان، الثلاثاء 31 آذار، ترحيباً بالسيد الرئيس أحمد الشرع خلال زيارته الرسمية إلى لندن، وفقاً لما نقلته وكالة سانا. وأعرب أبناء الجالية السورية عن سعادتهم بهذه الزيارة، مؤكدين دعمهم لجهود الحكومة في تعزيز العلاقات الثنائية وتطوير التعاون بين سوريا والمملكة المتحدة في مختلف المجالات. وكان السيد الرئيس وصل إلى العاصمة البريطانية لندن، في وقت سابق من اليوم، للقاء كبار المسؤولين البريطانيين وبحث سبل تطوير العلاقات الثنائية. وفي إطار الزيارة الرسمية إلى المملكة المتحدة، التقى الرئيس الشرع رئيس الوزراء البريطاني كير ستارمر، بحضور وزير الخارجية والمغتربين أسعد الشيباني ووزير الاقتصاد نضال الشعار، وفقاً لما نشرته رئاسة الجمهورية. وبحث الجانبان سبل تعزيز العلاقات الثنائية بما يحقق المصالح المشتركة للبلدين، مؤكدين أهمية تطوير التعاون في مجالات التنمية والاستثمار، كما تطرّقا إلى مس Source: https://alikhbariah.com/%d8%a3%d8%a8%d9%86%d8%a7%d8%a1-%d8%a7%d9%84%d8%ac%d8%a7%d9%84%d9%8a%d8%a9-%d8%a7%d9%84%d8%b3%d9%88%d8%b1%d9%8a%d8%a9-%d9%81%d9%8a-%d8%a8%d8%b1%d9%8a%d8%b7%d8%a7%d9%86%d9%8a%d8%a7-%d9%8a%d8%aa%d8%ac/', 'Members of the Syrian community in the United Kingdom gathered in front of Parliament, on Tuesday, March 31, to welcome President Ahmed Al-Sharaa during his official visit to London, according to SANA. Members of the Syrian community expressed They were pleased with this visit, stressing their support for the government’s efforts to strengthen bilateral relations and develop cooperation between Syria and the United Kingdom in various fields. Mr. President arrived in the British capital, London, earlier today, for a meeting Senior British officials discussed ways to develop bilateral relations. As part of the official visit to the United Kingdom, President Al-Sharaa met with British Prime Minister Keir Starmer, in the presence of the Minister of Foreign Affairs and Emigrants, Asaad Al-Shaibani, and the Minister of Foreign Affairs. Economy Nidal Al-Shaar, according to what was published by the Presidency of the Republic. The two sides discussed ways to enhance bilateral relations in a way that achieves the common interests of the two countries, stressing the importance of developing cooperation in the fields of development and investment. They also touched on the issue of Source: https://alikhbariah.com/%d8%a3%d8%a8%d9%86%d8%a7%d8%a1-%d8%a7%d9%84%d8%ac%d8%a7%d9%84%d9%8a%d8%a9-%d8%a7%d9%84 %d8%b3%d9%88%d8%b1%d9%8a%d8%a9-%d9%81%d9%8a-%d8%a8%d8%b1%d9%8a%d8%b7%d8%a7%d9%86%d9%8a%d8%a7-%d9%8a%d8%aa%d8%a c/', 'https://alikhbariah.com/wp-content/uploads/2026/03/The-Syrian-community-in-Britain.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 8 limit 1), '2026-03-31T11:14:38+03:00'::timestamptz, false, false, false, 182),
  ('الرئيس الشرع يبحث مع رئيس الوزراء البريطاني العلاقات الثنائية ومجالات التنمية والاستثمار', 'President Al-Shara discusses with the British Prime Minister bilateral relations and areas of development and investment', 'التقى السيد الرئيس أحمد الشرع، الثلاثاء 31 آذار، خلال زيارته الرسمية إلى المملكة المتحدة رئيس الوزراء البريطاني كير ستارمر، بحضور وزير الخارجية والمغتربين أسعد الشيباني ووزير الاقتصاد نضال الشعار، وفقاً لما نشرته رئاسة الجمهورية. وبحسب رئاسة الجمهورية عبر معرفاتها الرسمية فأن الجانبين بحثا سبل تعزيز العلاقات الثنائية بما يحقق المصالح المشتركة للبلدين، مؤكدين أهمية تطوير […]', 'On Tuesday, March 31, during his official visit to the United Kingdom, President Ahmed Al-Sharaa met with British Prime Minister Keir Starmer, in the presence of the Minister of Foreign Affairs and Emigrants, Asaad Al-Shaibani, and the Minister of Economy, Nidal Al-Shaar, according to what was published by the presidency. Republic. According to the Presidency of the Republic, through its official sources, the two sides discussed ways to strengthen bilateral relations in a way that achieves the common interests of the two countries, stressing the importance of developing […]', 'التقى السيد الرئيس أحمد الشرع، الثلاثاء 31 آذار، خلال زيارته الرسمية إلى المملكة المتحدة رئيس الوزراء البريطاني كير ستارمر، بحضور وزير الخارجية والمغتربين أسعد الشيباني ووزير الاقتصاد نضال الشعار، وفقاً لما نشرته رئاسة الجمهورية. وبحسب رئاسة الجمهورية عبر معرفاتها الرسمية فأن الجانبين بحثا سبل تعزيز العلاقات الثنائية بما يحقق المصالح المشتركة للبلدين، مؤكدين أهمية تطوير التعاون في مجالات التنمية والاستثمار، كما تطرّقا إلى مستجدات القضايا الإقليمية والدولية. ووصل الرئيس الشرع إلى العاصمة البريطانية اليوم للقاء كبار المسؤولين البريطانيين وبحث سبل تطوير العلاقات الثنائية بين البلدين. وجاءت زيارة الرئيس برفقة وفد وزاري في إطار الجهود الحكومية الرامية إلى تعزيز التعاون في مختلف المجالات، بحسب وكالة “سانا”. وقبل ذلك، توجّه الرئيس الشرع، في 29 آذار الجاري، إلى العاصمة الألمانية برلين برفقة وفد وزاري، في أول زيارة رسمية له إلى ألمانيا عقب سقوط ال Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d9%88%d8%b2%d8%b1%d8%a7%d8%a1-%d8%a7%d9%84%d8%a8%d8%b1/', 'On Tuesday, March 31, during his official visit to the United Kingdom, President Ahmed Al-Sharaa met with British Prime Minister Keir Starmer, in the presence of the Minister of Foreign Affairs and Emigrants, Asaad Al-Shaibani, and the Minister of Economy, Nidal Al-Shaar, according to what was published by the presidency. Republic. According to the Presidency of the Republic, through its official information, the two sides discussed ways to enhance bilateral relations in a way that achieves the common interests of the two countries, stressing the importance of developing cooperation in the fields of development and investment, and they also discussed developments. Regional and international issues. President Al-Sharaa arrived in the British capital today to meet with senior British officials and discuss ways to develop bilateral relations between the two countries. The president''s visit, accompanied by a ministerial delegation, came as part of government efforts Aiming to enhance cooperation in various fields, according to SANA. Before that, on March 29, President Al-Sharaa headed to the German capital, Berlin, accompanied by a ministerial delegation, on his first official visit to Germany following the fall of the Syrian regime. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%a8%d8%ad %d8%ab-%d9%85%d8%b9-%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d9%88%d8%b2%d8%b1%d8%a7%d8%a1-%d8%a7%d9%84%d8%a8%d8% b1/', 'https://alikhbariah.com/wp-content/uploads/2026/03/President-Shara-and-Keir-Starmes.jpg', (select id from public.categories where slug = 'news-politics' and type = 'news' limit 1), (select id from public.locations order by id offset 9 limit 1), '2026-03-31T10:48:22+03:00'::timestamptz, false, false, false, 181),
  ('الحرب الأمريكية – الإيرانية تضغط على اقتصادات دول المنطقة والعالم', 'The American-Iranian war is putting pressure on the economies of countries in the region and the world', 'تسبّب تعطل الملاحة في مضيق هرمز، الذي يمر به نحو 20% من الإمدادات العالمية من النفط والغاز، في ارتفاع أسعار الطاقة، وبالتالي تضخم عام في الأسعار في كثير من دول العالم. وجاء إغلاق المضيق نتيجة الحرب المندلعة في الشرق الأوسط بين إسرائيل والولايات المتحدة من جهة، وإيران من جهة أخرى منذ 28 شباط الماضي. وبحسب […]', 'The disruption of navigation in the Strait of Hormuz, through which about 20% of global supplies of oil and gas pass, has caused energy prices to rise, and thus a general inflation in prices in many countries of the world. The closure of the strait came as a result of the war raging in the east The Middle East conflict between Israel and the United States on the one hand, and Iran on the other hand, has been ongoing since February 28. According to […]', 'تسبّب تعطل الملاحة في مضيق هرمز، الذي يمر به نحو 20% من الإمدادات العالمية من النفط والغاز، في ارتفاع أسعار الطاقة، وبالتالي تضخم عام في الأسعار في كثير من دول العالم. وجاء إغلاق المضيق نتيجة الحرب المندلعة في الشرق الأوسط بين إسرائيل والولايات المتحدة من جهة، وإيران من جهة أخرى منذ 28 شباط الماضي. وبحسب تقرير لقناة الجزيرة صدر في 30 آذار الماضي، قفز سعر النفط من خام برنت بنسبة 53% منذ 27 شباط الفائت، وبلغت العقود الآجلة لخام برنت 112.57 دولاراً للبرميل الجمعة الماضية، مع تراجع الآمال بنهاية سريعة للحرب، فيما ارتفع سعر الغاز الطبيعي في الأسواق الأوروبية بأكثر من 50% ليصل إلى ما بين 55 و62 يورو للميغاواط/ساعة. ويلفت التقرير الانتباه إلى أن الحكومات حول العالم لجأت إلى اتخاذ مجموعة من الإجراءات لمواجهة القفزة في أسعار الطاقة ودعم مواطنيها للتخفيف من آثارها، فضلاً عن إجراءات حكومية للحد من النفقات. وفي العراق، على سبيل المثال، أفاد مسؤولون ل Source: https://alikhbariah.com/%d8%a7%d9%84%d8%ad%d8%b1%d8%a8-%d8%a7%d9%84%d8%a3%d9%85%d8%b1%d9%8a%d9%83%d9%8a%d8%a9-%d8%a7%d9%84%d8%a5%d9%8a%d8%b1%d8%a7%d9%86%d9%8a%d8%a9-%d8%aa%d8%b6%d8%ba%d8%b7-%d8%b9%d9%84%d9%89/', 'The disruption of navigation in the Strait of Hormuz, through which about 20% of global supplies of oil and gas pass, has caused energy prices to rise, and thus a general inflation in prices in many countries of the world. The closure of the strait came as a result of the war raging in the east The Middle East conflict between Israel and the United States on the one hand, and Iran on the other hand, has been ongoing since February 28. According to a report by Al Jazeera issued on March 30, the price of Brent crude oil has jumped by 53% since February 27, and Brent crude futures contracts reached... $112.57 per barrel last Friday, with hopes for a quick end to the war declining, while the price of natural gas in European markets rose by more than 50% to reach between 55 and 62 euros per megawatt-hour. The report draws attention to that Governments around the world have resorted to taking a set of measures to confront the jump in energy prices and support their citizens to mitigate its effects, as well as government measures to reduce expenses. In Iraq, for example, officials reported to Source: https://alikhbariah.com/%d8%a7%d9%84%d8%ad%d8%b1%d8%a8-%d8%a7%d9%84%d8%a3%d9%85%d8%b1%d9%8a%d9%83%d9%8a% d8%a9-%d8%a7%d9%84%d8%a5%d9%8a%d8%b1%d8%a7%d9%86%d9%8a%d8%a9-%d8%aa%d8%b6%d8%ba%d8%b7-%d8%b9%d9%84%d9%89/', 'https://alikhbariah.com/wp-content/uploads/2026/04/The-American-Iranian-war.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 10 limit 1), '2026-04-01T09:20:41+03:00'::timestamptz, false, true, false, 180),
  ('المالية تعلن بدء التسجيل الإلكتروني لإعادة صرف المعاشات التقاعدية المتوقفة', 'Finance announces the start of electronic registration to repay suspended pensions', 'أعلنت وزارة المالية، الأربعاء 1 نيسان، بدء التسجيل الإلكتروني لاستكمال عملية صرف المعاشات التقاعدية المتوقفة، وذلك في إطار جهودها لمعالجة ملفات المتقاعدين وضمان وصول المستحقات المالية إلى أصحابها. وأوضحت الوزارة عبر معرفاتها الرسمية، أن عملية التسجيل متاحة من خلال الرسائل النصية المجانية (SMS) إلى الرقم 3346، على أن يتضمن محتوى الرسالة الاسم الثلاثي والرقم الوطني […]', 'On Wednesday, April 1, the Ministry of Finance announced the start of electronic registration to complete the process of disbursing suspended pensions, as part of its efforts to address retirees’ files and ensure that financial entitlements reach their owners. The Ministry explained via According to its official IDs, the registration process is available through free text messages (SMS) to the number 3346, provided that the content of the message includes the full name and the national number […]', 'أعلنت وزارة المالية، الأربعاء 1 نيسان، بدء التسجيل الإلكتروني لاستكمال عملية صرف المعاشات التقاعدية المتوقفة، وذلك في إطار جهودها لمعالجة ملفات المتقاعدين وضمان وصول المستحقات المالية إلى أصحابها. وأوضحت الوزارة عبر معرفاتها الرسمية، أن عملية التسجيل متاحة من خلال الرسائل النصية المجانية (SMS) إلى الرقم 3346، على أن يتضمن محتوى الرسالة الاسم الثلاثي والرقم الوطني والصفة واسم الأم، مؤكدةً أن صاحب العلاقة يتحمل مسؤولية صحة البيانات المقدمة. وبيّنت أن الطلبات تقبل من صاحب العلاقة حصراً دون الوكلاء، داعيةً إلى التأكد من صحة رقم الهاتف المرسل منه الطلب كونه وسيلة التواصل المعتمدة، حيث ستجري عملية تدقيق الطلبات واستكمال الإجراءات اللازمة لاحقاً. وأشارت وزارة المالية إلى أن هذه الخطوة تندرج ضمن خطة تنظيم بيانات المتقاعدين وتسريع إجراءات إعادة صرف المعاشات التقاعدية المتوقفة وفق الآليات المعتمدة. وأكد وزير المالية محمد يسر برنية، في 28 آذار، أن ا Source: https://alikhbariah.com/%d8%a7%d9%84%d9%85%d8%a7%d9%84%d9%8a%d8%a9-%d8%aa%d8%b9%d9%84%d9%86-%d8%a8%d8%af%d8%a1-%d8%a7%d9%84%d8%aa%d8%b3%d8%ac%d9%8a%d9%84-%d8%a7%d9%84%d8%a5%d9%84%d9%83%d8%aa%d8%b1%d9%88%d9%86%d9%8a-%d9%84/', 'On Wednesday, April 1, the Ministry of Finance announced the start of electronic registration to complete the process of disbursing suspended pensions, as part of its efforts to address retirees’ files and ensure that financial entitlements reach their owners. The Ministry explained via According to its official IDs, the registration process is available through free text messages (SMS) to the number 3346, provided that the content of the message includes the full name, national number, title, and mother’s name, stressing that the person concerned bears responsibility for the accuracy of the data. the introduction. She indicated that applications are accepted exclusively from the person concerned, not agents, calling for ensuring that the phone number from which the request is sent is correct, as it is the approved means of communication, as the process of verifying the applications and completing the necessary procedures will take place later. The Ministry of Finance indicated that this step falls within the plan to organize retirees’ data and accelerate the procedures for repaying suspended pensions according to the approved mechanisms. On March 28, Finance Minister Muhammad Yusser Barneyah confirmed that... https://alikhbariah.com/%d8%a7%d9%84%d9%85%d8%a7%d9%84%d9%8a%d8%a9-%d8%aa%d8%b9%d9%84%d9%86-%d8%a8%d8%af%d8%a1 -%d8%a7%d9%84%d8%aa%d8%b3%d8%ac%d9%8a%d9%84-%d8%a7%d9%84%d8%a5%d9%84%d9%83%d8%aa%d8%b1%d9%88%d9%86%d9%8a-%d9%8 4/', 'https://alikhbariah.com/wp-content/uploads/2026/04/Ministry-of-Finance.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 11 limit 1), '2026-04-01T09:15:25+03:00'::timestamptz, false, true, false, 179),
  ('“السورية للبترول” تعلن وصول أولى قوافل “الفيول” العراقي إلى مصب بانياس', '“Syrian Petroleum” announces the arrival of the first Iraqi “fuel” convoys to the Baniyas estuary', 'أعلن مدير إدارة الاتصال المؤسساتي في الشركة السورية للبترول (SPC) صفوان شيخ أحمد بدء وصول أولى قوافل زيت الوقود العراقي (Fuel Oil) القادمة من جمهورية العراق الشقيقة عبر منفذ التنف باتجاه مصب بانياس النفطي، حيث تضم القافلة الأولى 176 صهريجاً من المقرر أن تصل اليوم الأربعاء 1 نيسان. وبيّن شيخ أحمد في منشور له على […]', 'The Director of the Institutional Communication Department at the Syrian Petroleum Company (SPC), Safwan Sheikh Ahmed, announced the start of the arrival of the first Iraqi fuel oil convoys coming from the sisterly Republic of Iraq through the Al-Tanf port towards the Baniyas oil terminal, which includes... The first convoy of 176 tankers is scheduled to arrive today, Wednesday, April 1. Sheikh Ahmed stated in his post on […]', 'أعلن مدير إدارة الاتصال المؤسساتي في الشركة السورية للبترول (SPC) صفوان شيخ أحمد بدء وصول أولى قوافل زيت الوقود العراقي (Fuel Oil) القادمة من جمهورية العراق الشقيقة عبر منفذ التنف باتجاه مصب بانياس النفطي، حيث تضم القافلة الأولى 176 صهريجاً من المقرر أن تصل اليوم الأربعاء 1 نيسان. وبيّن شيخ أحمد في منشور له على “ فيسبوك ” أن الفرق الفنية في الشركة ستباشر عمليات التفريغ في المكان المخصص فور وصول القوافل، تمهيداً لتحميل الفيول على النواقل البحرية المخصصة للتصدير إلى وجهتها النهائية، ضمن مسار يثبت كفاءة كوادرها في إدارة عمليات العبور وفق أعلى المعايير الدولية. وأكد أن هذه الخطوة تعكس استعادة سوريا لدورها الحيوي كممر إقليمي للطاقة وتعزيز حضورها في معادلة الأمن الطاقي، إذ إن تدفق هذه الكميات الكبيرة يساهم بشكل مباشر في تنمية الاقتصاد الوطني عبر تنشيط حركة الترانزيت ورفد خزينة الدولة بإيرادات مجزية تدفع بعجلة النمو نحو آفاق أوسع. كما يؤكد وصول  Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b3%d9%88%d8%b1%d9%8a%d8%a9-%d9%84%d9%84%d8%a8%d8%aa%d8%b1%d9%88%d9%84-%d8%aa%d8%b9%d9%84%d9%86-%d9%88%d8%b5%d9%88%d9%84-%d8%a3%d9%88%d9%84%d9%89-%d9%82%d9%88%d8%a7%d9%81%d9%84/', 'The Director of the Institutional Communication Department at the Syrian Petroleum Company (SPC), Safwan Sheikh Ahmed, announced the start of the arrival of the first Iraqi fuel oil convoys coming from the sisterly Republic of Iraq through the Al-Tanf port towards the Baniyas oil terminal, which includes... The first convoy of 176 tankers is scheduled to arrive today, Wednesday, April 1. Sheikh Ahmed stated in a post on “Facebook” that the company’s technical teams will begin unloading operations in the designated place upon the arrival of the convoys, in preparation for loading the fuel onto the vehicle. Marine tankers designated for export to their final destination, within a path that proves the efficiency of their staff in managing transit operations in accordance with the highest international standards. He stressed that this step reflects Syria''s restoration of its vital role as a regional energy corridor and the strengthening of its presence in... The energy security equation, as the flow of these large quantities contributes directly to the development of the national economy by stimulating transit traffic and supplying the state treasury with lucrative revenues that push the wheel of growth towards broader horizons. It also confirms the arrival of Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b3%d9%88%d8%b1%d9%8a%d8%a9-%d9%84%d9%84%d8%a8%d8%aa%d8%b1%d9%88%d9%8 4-%d8%aa%d8%b9%d9%84%d9%86-%d9%88%d8%b5%d9%88%d9%84-%d8%a3%d9%88%d9%84%d9%89-%d9%82%d9%88%d8%a7%d9%81%d9%84/', 'https://alikhbariah.com/wp-content/uploads/2026/04/oil-tankers.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 12 limit 1), '2026-04-01T07:57:15+03:00'::timestamptz, false, false, false, 178),
  ('الشرع: سوريا من أفضل الفرص الاستثمارية في العالم', 'Al-Sharaa: Syria is one of the best investment opportunities in the world', 'قال السيد الرئيس أحمد الشرع، إن “سوريا تشكل فرصة مهمة للجميع، وهي من أفضل الفرص الاستثمارية في العالم”، وفق ما نقلت وكالة سانا. وأضاف السيد الرئيس، “نحن في صراع حقيقي في معركة إعادة إعمار بلدنا المدمر”. جاء ذلك خلال لقائه في لندن مع ممثلين عن كبرى الشركات البريطانية ورجال الأعمال البريطانيين والسوريين، الثلاثاء 31 آذار. […]', 'President Ahmed Al-Sharaa said, “Syria represents an important opportunity for everyone, and it is one of the best investment opportunities in the world,” according to what SANA reported. Mr. President added, “We are in a real struggle in the battle to rebuild our destroyed country.” This came through His meeting in London with representatives of major British companies and British and Syrian businessmen, Tuesday, March 31. […]', 'قال السيد الرئيس أحمد الشرع، إن “سوريا تشكل فرصة مهمة للجميع، وهي من أفضل الفرص الاستثمارية في العالم”، وفق ما نقلت وكالة سانا. وأضاف السيد الرئيس، “نحن في صراع حقيقي في معركة إعادة إعمار بلدنا المدمر”. جاء ذلك خلال لقائه في لندن مع ممثلين عن كبرى الشركات البريطانية ورجال الأعمال البريطانيين والسوريين، الثلاثاء 31 آذار. وخلال الاجتماع جرى بحث سبل تعزيز التعاون الاقتصادي والاستثماري بين البلدين، وتعزيز بيئة الأعمال وفرص الاستثمار بما يخدم المصالح المشتركة، بحسب ما نشرت رئاسة الجمهورية عبر معرفاتها الرسمية. وكان السيد الرئيس أحمد الشرع قد وصل إلى العاصمة البريطانية لندن، الثلاثاء 31 آذار، للقاء كبار المسؤولين البريطانيين وبحث سبل تطوير العلاقات الثنائية. وتأتي زيارة الرئيس الشرع برفقة وفد وزاري ضمن جهود الدولة السورية الرامية إلى تعزيز التعاون بين البلدين في مختلف المجالات. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d9%85%d9%86-%d8%a3%d9%81%d8%b6%d9%84-%d8%a7%d9%84%d9%81%d8%b1%d8%b5-%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d8%ab%d9%85%d8%a7%d8%b1%d9%8a%d8%a9/', 'President Ahmed Al-Sharaa said, “Syria represents an important opportunity for everyone, and it is one of the best investment opportunities in the world,” according to what SANA reported. Mr. President added, “We are in a real struggle in the battle to rebuild our destroyed country.” This came through His meeting in London with representatives of major British companies and British and Syrian businessmen, Tuesday, March 31. During the meeting, ways to enhance economic and investment cooperation between the two countries and enhance the business environment and investment opportunities were discussed In a way that serves common interests, according to what the Presidency of the Republic published through its official accounts. President Ahmed Al-Sharaa arrived in the British capital, London, on Tuesday, March 31, to meet with senior British officials and discuss ways to develop relations. Duality. President Al-Sharaa''s visit, accompanied by a ministerial delegation, comes as part of the Syrian state''s efforts aimed at strengthening cooperation between the two countries in various fields. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d9%85%d9%86-%d8%a3%d9%8 1%d8%b6%d9%84-%d8%a7%d9%84%d9%81%d8%b1%d8%b5-%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d8%ab%d9%85%d8%a7%d8%b1%d9%8a%d8%a 9/', 'https://alikhbariah.com/wp-content/uploads/2026/04/President-Ahmed-Al-Sharaa-17.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 13 limit 1), '2026-03-31T22:10:53+03:00'::timestamptz, false, false, false, 177),
  ('مباحثات سورية _ أممية لتعزيز التعاون في مواجهة تحديات قطاع الإسكان وسبل معالجتها', 'Syrian-UN discussions to enhance cooperation in facing the challenges of the housing sector and ways to address them', 'استقبل وزير الأشغال العامة والإسكان مصطفى عبد الرزاق، الثلاثاء 31 آذار، مساعد الأمين العام للأمم المتحدة والمدير الإقليمي لبرنامج الأمم المتحدة الإنمائي عبد الله الدردري، والوفد المرافق له، في إطار بحث سبل تعزيز التعاون المشترك بين الجانبين. وتناول اللقاء آفاق تطوير التعاون، حيث جرى استعراض عدد من التجارب الناجحة في مجال إعادة الإعمار، ولا سيما […]', 'The Minister of Public Works and Housing, Mustafa Abdel Razzaq, received, on Tuesday, March 31, the Assistant Secretary-General of the United Nations and the Regional Director of the United Nations Development Programme, Abdullah Al-Dardari, and his accompanying delegation, within the framework of discussing ways to enhance cooperation. Commonality between the two sides. The meeting discussed prospects for developing cooperation, where a number of successful experiences in the field of reconstruction were reviewed, especially […]', 'استقبل وزير الأشغال العامة والإسكان مصطفى عبد الرزاق، الثلاثاء 31 آذار، مساعد الأمين العام للأمم المتحدة والمدير الإقليمي لبرنامج الأمم المتحدة الإنمائي عبد الله الدردري، والوفد المرافق له، في إطار بحث سبل تعزيز التعاون المشترك بين الجانبين. وتناول اللقاء آفاق تطوير التعاون، حيث جرى استعراض عدد من التجارب الناجحة في مجال إعادة الإعمار، ولا سيما ما يتعلق بإدارة التمويل وآليات تنفيذ المشاريع، بما يدعم جهود التعافي في قطاع الإسكان، بحسب ما نشرت وزارة الأشغال العامة والإسكان عبر معرفاتها الرسمية. كما ناقش الجانبان أبرز التحديات التي تواجه قطاع الإسكان في سوريا، وسبل معالجتها، بما يسهم في تسريع عمليات إعادة التأهيل. وفي ختام اللقاء، تم الاتفاق على عقد اجتماعات فنية مشتركة مع الجهات المختصة، لبحث محاور التعاون المستقبلية، والتي تشمل الدعم المؤسساتي للوزارة، وتعزيز مراكز التدريب المهني وتطوير مناهجها، إلى جانب التعاون في مجالات التخطيط العمراني، Source: https://alikhbariah.com/%d9%85%d8%a8%d8%a7%d8%ad%d8%ab%d8%a7%d8%aa-%d8%b3%d9%88%d8%b1%d9%8a%d8%a9-_-%d8%a3%d9%85%d9%85%d9%8a%d8%a9-%d9%84%d8%aa%d8%b9%d8%b2%d9%8a%d8%b2-%d8%a7%d9%84%d8%aa%d8%b9%d8%a7%d9%88%d9%86-%d9%81%d9%8a/', 'The Minister of Public Works and Housing, Mustafa Abdel Razzaq, received, on Tuesday, March 31, the Assistant Secretary-General of the United Nations and the Regional Director of the United Nations Development Programme, Abdullah Al-Dardari, and his accompanying delegation, within the framework of discussing ways to enhance cooperation. Commonality between the two sides. The meeting discussed prospects for developing cooperation, where a number of successful experiences in the field of reconstruction were reviewed, especially with regard to financing management and project implementation mechanisms, in a way that supports recovery efforts in the housing sector, according to What the Ministry of Public Works and Housing published through its official accounts. The two sides also discussed the most prominent challenges facing the housing sector in Syria, and ways to address them, in a way that contributes to accelerating rehabilitation processes. At the conclusion of the meeting, a contract was agreed upon Joint technical meetings with the competent authorities, to discuss future areas of cooperation, which include institutional support for the Ministry, strengthening vocational training centers and developing their curricula, in addition to cooperation in the areas of urban planning, Source: https://alikhbariah.com/%d9%85%d8%a8%d8%a7%d8%ad%d8%ab%d8%a7%d8%aa-%d8%b3%d9%88%d8%b1%d9%8a%d8%a9-_-%d8%a3%d9% 85%d9%85%d9%8a%d8%a9-%d9%84%d8%aa%d8%b9%d8%b2%d9%8a%d8%b2-%d8%a7%d9%84%d8%aa%d8%b9%d8%a7%d9%88%d9%86-%d9%81%d9 %8a/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Public-Works-1.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 0 limit 1), '2026-03-31T19:10:54+03:00'::timestamptz, false, false, false, 176),
  ('وفد اقتصادي يبحث فرص الاستثمار مع رجال أعمال سوريين في ألمانيا', 'An economic delegation discusses investment opportunities with Syrian businessmen in Germany', 'بحث وزير الاقتصاد والصناعة نضال الشعار، مع رجال الأعمال السوريين في ألمانيا والدول المجاورة، فرص وآفاق الاستثمار في سوريا، وذلك على هامش زيارة الرئيس أحمد الشرع والوفد المرافق له إلى ألمانيا. وتناول الاجتماع أبرز المشاريع الاقتصادية في مختلف القطاعات، مع التركيز على تعزيز الشراكات بين المستثمرين والقطاعين العام والخاص، واستعراض التسهيلات والإجراءات الحكومية الداعمة للنشاط […]', 'The Minister of Economy and Industry, Nidal Al-Shaar, discussed with Syrian businessmen in Germany and neighboring countries investment opportunities and prospects in Syria, on the sidelines of the visit of President Ahmed Al-Sharaa and his accompanying delegation to Germany. The meeting discussed highlights Economic projects in various sectors, with a focus on strengthening partnerships between investors and the public and private sectors, and reviewing government facilities and procedures supporting […]', 'بحث وزير الاقتصاد والصناعة نضال الشعار، مع رجال الأعمال السوريين في ألمانيا والدول المجاورة، فرص وآفاق الاستثمار في سوريا، وذلك على هامش زيارة الرئيس أحمد الشرع والوفد المرافق له إلى ألمانيا. وتناول الاجتماع أبرز المشاريع الاقتصادية في مختلف القطاعات، مع التركيز على تعزيز الشراكات بين المستثمرين والقطاعين العام والخاص، واستعراض التسهيلات والإجراءات الحكومية الداعمة للنشاط الاستثماري، بحسب ما نشرت وزارة الاقتصاد والصناعة عبر معرفاتها الرسمية الإثنين 30 آذار. وأشار الوزير الشعار إلى أهمية توحيد الجهود لتوسيع قاعدة الاستثمارات السورية في الخارج بما يسهم في تعزيز الاقتصاد الوطني، مؤكداً استمرار الوزارة في تشجيع الاستثمارات وتنمية علاقات التعاون مع الجاليات السورية حول العالم. وفي لقاء للوزير الشعار الإثنين مع الإخبارية، أكد أن الخطوات التي تعمل عليها الحكومة تهدف إلى إعادة تموضع سوريا ضمن النظام الاقتصادي العالمي، وإعادة اندماجها في هذا النظا Source: https://alikhbariah.com/%d9%88%d9%81%d8%af-%d8%a7%d9%82%d8%aa%d8%b5%d8%a7%d8%af%d9%8a-%d9%8a%d8%a8%d8%ad%d8%ab-%d9%81%d8%b1%d8%b5-%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d8%ab%d9%85%d8%a7%d8%b1-%d9%85%d8%b9-%d8%b1%d8%ac%d8%a7%d9%84/', 'The Minister of Economy and Industry, Nidal Al-Shaar, discussed with Syrian businessmen in Germany and neighboring countries investment opportunities and prospects in Syria, on the sidelines of the visit of President Ahmed Al-Sharaa and his accompanying delegation to Germany. The meeting discussed highlights Economic projects in various sectors, with a focus on strengthening partnerships between investors and the public and private sectors, and reviewing government facilities and procedures supporting investment activity, according to what the Ministry of Economy and Industry published via Its official IDs are Monday, March 30. Minister Al-Shaar pointed to the importance of unifying efforts to expand the base of Syrian investments abroad in a way that contributes to strengthening the national economy, stressing that the Ministry will continue to encourage investments and develop relations. Cooperation with Syrian communities around the world. In a meeting between Minister Al-Shaar on Monday with Al-Ikhbariya, he stressed that the steps the government is working on aim to reposition Syria within the global economic system and reintegrate it into this system. Source: https://alikhbariah.com/%d9%88%d9%81%d8%af-%d8%a7%d9%82%d8%aa%d8%b5%d8%a7%d8%af%d9%8a-%d9%8a%d8%a8%d8%ad%d8%ab -%d9%81%d8%b1%d8%b5-%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d8%ab%d9%85%d8%a7%d8%b1-%d9%85%d8%b9-%d8%b1%d8%ac%d8%a7%d9% 84/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Economy-4.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 1 limit 1), '2026-03-30T21:32:58+03:00'::timestamptz, false, false, false, 175),
  ('وزير الاقتصاد للإخبارية: نتائج زيارتنا لألمانيا فاقت التوقعات', 'Minister of Economy to Al-Ikhbariya: The results of our visit to Germany exceeded expectations', 'أكد وزير الاقتصاد والصناعة نضال الشعار أن الخطوات التي تعمل عليها الحكومة تهدف إلى إعادة تموضع سوريا ضمن النظام الاقتصادي العالمي، وإعادة اندماجها في هذا النظام بعد عقود من العزلة امتدت لأربعين إلى خمسين عاماً. وأشار الشعار، في مقابلة مع الإخبارية، الإثنين 30 آذار، إلى أن الهدف يتمثل في استعادة موقع الدولة الطبيعي وبناء علاقات […]', 'Minister of Economy and Industry, Nidal Al-Shaar, confirmed that the steps the government is working on aim to reposition Syria within the global economic system, and reintegrate it into this system after decades of isolation that extended for forty to fifty years. He pointed out Al-Shaar, in an interview with Al-Ekhbariya, Monday, March 30, indicated that the goal is to restore the state’s natural position and build relations […]', 'أكد وزير الاقتصاد والصناعة نضال الشعار أن الخطوات التي تعمل عليها الحكومة تهدف إلى إعادة تموضع سوريا ضمن النظام الاقتصادي العالمي، وإعادة اندماجها في هذا النظام بعد عقود من العزلة امتدت لأربعين إلى خمسين عاماً. وأشار الشعار، في مقابلة مع الإخبارية، الإثنين 30 آذار، إلى أن الهدف يتمثل في استعادة موقع الدولة الطبيعي وبناء علاقات اقتصادية طبيعية مع دول العالم. وأوضح أن الحكومة تسعى إلى تقديم صورة واضحة عن الدولة الجديدة وتركيبتها الاقتصادية وهيكليتها بما يتيح للدول الأخرى التعرف إلى الفرص الاستثمارية المتاحة والتحديات القائمة، لافتاً إلى أن الزيارة الأخيرة إلى ألمانيا تمثل خطوة مهمة في هذا المسار. وبين أن نتائج الزيارة إلى ألمانيا جاءت أفضل بكثير مما كان متوقعاً، حيث ساد تجاوب إيجابي واسع في مختلف المجالات وعلى جميع المستويات، سواء الاقتصادية أو الاجتماعية أو الثقافية أو التعليمية. وأضاف أن النقاشات التي جرت تناولت قضايا اللاجئين والمغتربين، Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%a7%d9%82%d8%aa%d8%b5%d8%a7%d8%af-%d9%84%d9%84%d8%a5%d8%ae%d8%a8%d8%a7%d8%b1%d9%8a%d8%a9-%d9%86%d8%aa%d8%a7%d8%a6%d8%ac-%d8%b2%d9%8a%d8%a7%d8%b1%d8%aa%d9%86/', 'Minister of Economy and Industry, Nidal Al-Shaar, confirmed that the steps the government is working on aim to reposition Syria within the global economic system, and reintegrate it into this system after decades of isolation that extended for forty to fifty years. He pointed out Al-Shaar, in an interview with Al-Ekhbariya, Monday, March 30, indicated that the goal is to restore the country’s natural position and build normal economic relations with the countries of the world. He explained that the government seeks to present a clear picture of the new state and its composition The economy and its structure allow other countries to learn about the available investment opportunities and existing challenges, pointing out that the recent visit to Germany represents an important step in this path. He stated that the results of the visit to Germany were better Much more than expected, as there was a wide positive response in various fields and at all levels, whether economic, social, cultural or educational. He added that the discussions that took place dealt with the issues of refugees and expatriates. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%a7%d9%82%d8%aa%d8%b5%d8%a7%d8%af-%d9%84%d9%84 %d8%a5%d8%ae%d8%a8%d8%a7%d8%b1%d9%8a%d8%a9-%d9%86%d8%aa%d8%a7%d8%a6%d8%ac-%d8%b2%d9%8a%d8%a7%d8%b1%d8%aa%d9%86 /', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Economy-3.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 2 limit 1), '2026-03-30T19:30:53+03:00'::timestamptz, false, false, false, 174),
  ('وزير الطاقة من برلين: سنوقع مذكرات تعاون مع شركتي “سيمنس” و”كناوف”', 'The Minister of Energy from Berlin: We will sign memorandums of cooperation with “Siemens” and “Knauf” companies', 'كشف وزير الطاقة محمد البشير أن الوزارة ستوقع مذكرتين مع شركة “سيمنس” من أجل التعاون والعمل على بناء نظام قيادة وتشغيل للشبكة السورية، إضافة إلى توقيع مذكرة مع شركة “كناوف” لصناعة ألواح الجبس، وكذلك للتعاون في مجالات المياه والطاقة. وقال وزير الطاقة محمد البشير، في كلمة ألقاها خلال منتدى الأعمال الألماني – السوري، الإثنين 30 […]', 'The Minister of Energy, Muhammad al-Bashir, revealed that the ministry will sign two memorandums with the “Siemens” company in order to cooperate and work on building a command and operation system for the Syrian network, in addition to signing a memorandum with the “Knauf” company for the manufacture of gypsum boards, as well as for cooperation in the fields of Water and energy. Energy Minister Mohamed Al-Bashir said, in a speech he delivered during the German-Syrian Business Forum, Monday, 30 […]', 'كشف وزير الطاقة محمد البشير أن الوزارة ستوقع مذكرتين مع شركة “سيمنس” من أجل التعاون والعمل على بناء نظام قيادة وتشغيل للشبكة السورية، إضافة إلى توقيع مذكرة مع شركة “كناوف” لصناعة ألواح الجبس، وكذلك للتعاون في مجالات المياه والطاقة. وقال وزير الطاقة محمد البشير، في كلمة ألقاها خلال منتدى الأعمال الألماني – السوري، الإثنين 30 آذار: “عندما اتجه العالم نحو الطاقات المتجددة والنظيفة كانت سوريا تعيش أياماً صعبة على جميع الأصعدة نتيجة ما خلّفته الحرب التي تسبب بها النظام البائد”، وفقاً لما نقلته وكالة سانا . و وصل الرئيس الشرع، في وقت سابق من اليوم، إلى مبنى وزارة الخارجية الألمانية لحضور لقاء الطاولة المستديرة الذي يضم وزراء سوريين وألمان ومختصين اقتصاديين، وذلك لبحث سبل تعزيز التعاون الاقتصادي بين البلدين. وأفاد المتحدث باسم وزارة الخارجية الألمانية أن الرئيس الشرع سيشارك أثناء وجوده في برلين في منتدى سياسي وتجاري يستكشف آفاق التعافي الاقتصادي Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%b7%d8%a7%d9%82%d8%a9-%d9%85%d9%86-%d8%a8%d8%b1%d9%84%d9%8a%d9%86-%d8%b3%d9%86%d9%88%d9%82%d8%b9-%d9%85%d8%b0%d9%83%d8%b1%d8%aa%d9%8a-%d8%aa%d8%b9%d8%a7%d9%88/', 'The Minister of Energy, Muhammad al-Bashir, revealed that the ministry will sign two memorandums with the “Siemens” company in order to cooperate and work on building a command and operation system for the Syrian network, in addition to signing a memorandum with the “Knauf” company for the manufacture of gypsum boards, as well as for cooperation in the fields of Water and energy. Energy Minister Muhammad al-Bashir said, in a speech he delivered during the German-Syrian Business Forum, Monday, March 30: “When the world turned towards renewable and clean energies, Syria was experiencing difficult days at all levels as a result of what He was left behind by the war caused by the former regime,” according to SANA. President Al-Sharaa arrived, earlier today, at the German Foreign Ministry building to attend a round-table meeting that includes Syrian and German ministers and specialists. Economists, to discuss ways to enhance economic cooperation between the two countries. The German Foreign Ministry spokesman stated that President Al-Sharaa will participate during his stay in Berlin in a political and trade forum that explores prospects for economic recovery. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%b7%d8%a7%d9%82%d8%a9-%d9%85%d9%86-%d8%a8%d8%b 1%d9%84%d9%8a%d9%86-%d8%b3%d9%86%d9%88%d9%82%d8%b9-%d9%85%d8%b0%d9%83%d8%b1%d8%aa%d9%8a-%d8%aa%d8%b9%d8%a7%d9% 88/', 'https://alikhbariah.com/wp-content/uploads/2026/01/Minister-of-Energy.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 3 limit 1), '2026-03-30T09:32:52+03:00'::timestamptz, false, false, false, 173),
  ('وزير الاقتصاد: سوريا وألمانيا جمعتهما محطات من التعاون المتبادل والعلاقات التاريخية', 'Minister of Economy: Syria and Germany brought together stations of mutual cooperation and historical relations', 'أكد وزير الاقتصاد والصناعة محمد نضال الشعار، الإثنين 30 آذار، أن سوريا وألمانيا جمعتهما عبر التاريخ محطات من التعاون المتبادل والعلاقات التاريخية. وقال الشعار في كلمة ألقاها خلال منتدى الأعمال الألماني – السوري: “نقوم اليوم بإعادة التواصل مع العالم بما يخدم مصالح شعوبنا ويعزز علاقاتنا مع الدول الأخرى”، بحسب مانقلت وكالة سانا. ونوّه الشعار بالجسر […]', 'The Minister of Economy and Industry, Muhammad Nidal Al-Shaar, confirmed on Monday, March 30, that Syria and Germany have been united throughout history by points of mutual cooperation and historical relations. Al-Shaar said in a speech he delivered during the German-Syrian Business Forum: “We will Today, we will reconnect with the world in a way that serves the interests of our peoples and strengthens our relations with other countries,” according to what SANA reported. The slogan noted the bridge […]', 'أكد وزير الاقتصاد والصناعة محمد نضال الشعار، الإثنين 30 آذار، أن سوريا وألمانيا جمعتهما عبر التاريخ محطات من التعاون المتبادل والعلاقات التاريخية. وقال الشعار في كلمة ألقاها خلال منتدى الأعمال الألماني – السوري: “نقوم اليوم بإعادة التواصل مع العالم بما يخدم مصالح شعوبنا ويعزز علاقاتنا مع الدول الأخرى”، بحسب مانقلت وكالة سانا. ونوّه الشعار بالجسر الإنساني – الاقتصادي الذي تشكّل بين البلدين والمتمثل بالجالية السورية في ألمانيا، مضيفاً: “نحن لا ننظر إليهم كجسر مؤقت، بل جسر يوحد العلاقات بين البلدين”. و وصل الرئيس الشرع، في وقت سابق من اليوم، إلى مبنى وزارة الخارجية الألمانية لحضور لقاء الطاولة المستديرة الذي يضم وزراء سوريين وألمان ومختصين اقتصاديين، وذلك لبحث سبل تعزيز التعاون الاقتصادي بين البلدين. وأفاد المتحدث باسم وزارة الخارجية الألمانية أن الرئيس الشرع سيشارك أثناء وجوده في برلين في منتدى سياسي وتجاري يستكشف آفاق التعافي الاقتصادي وإع Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%a7%d9%82%d8%aa%d8%b5%d8%a7%d8%af-%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d9%88%d8%a3%d9%84%d9%85%d8%a7%d9%86%d9%8a%d8%a7-%d8%ac%d9%85%d8%b9%d8%aa%d9%87%d9%85%d8%a7/', 'The Minister of Economy and Industry, Muhammad Nidal Al-Shaar, confirmed on Monday, March 30, that Syria and Germany have been united throughout history by points of mutual cooperation and historical relations. Al-Shaar said in a speech he delivered during the German-Syrian Business Forum: “We will Today, by reconnecting with the world in a way that serves the interests of our peoples and strengthens our relations with other countries,” according to what was reported by SANA, Al-Shaar praised the humanitarian-economic bridge that was formed between the two countries, represented by the Syrian community in Germany, adding: “We do not view them as a temporary bridge, but rather a bridge that unites relations between the two countries.” Earlier today, President Al-Sharaa arrived at the German Foreign Ministry building to attend a round-table meeting that includes Syrian and German ministers and economic specialists. This is to discuss ways to enhance economic cooperation between the two countries. The German Foreign Ministry spokesman stated that President Al-Sharaa will participate during his stay in Berlin in a political and trade forum that explores the prospects for economic recovery and information. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%a7%d9%82%d8%aa%d8%b5%d8%a7%d8%af-%d8%b3%d9%88 %d8%b1%d9%8a%d8%a7-%d9%88%d8%a3%d9%84%d9%85%d8%a7%d9%86%d9%8a%d8%a7-%d8%ac%d9%85%d8%b9%d8%aa%d9%87%d9%85%d8%a7 /', 'https://alikhbariah.com/wp-content/uploads/2026/02/Minister-of-Economy-1.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 4 limit 1), '2026-03-30T09:22:33+03:00'::timestamptz, false, false, false, 172),
  ('وزير المالية يوضح آلية السلفة الضريبية على الاستيراد', 'The Minister of Finance explains the mechanism of tax advance on imports', 'قال وزير المالية محمد يسر برنية، الأحد 29 آذار، إن السلفة الضريبية على فاتورة الاستيراد سيتم استيفاؤها بالليرة السورية، من خلال البنوك السورية، وبحسب سعر صرف مصرف سورية المركزي، وذلك في إطار تعزيز الشفافية والاستجابة لمطالب قطاع الأعمال والصناعيين. وكشف الوزير، في منشوره على فيس بوك في إجابة على بعض الاستفسارات، أن نسبة السلفة المحددة […]', 'Finance Minister Muhammad Yusser Barneyah said on Sunday, March 29, that the tax advance on the import bill will be collected in Syrian pounds, through Syrian banks, and according to the exchange rate of the Central Bank of Syria, within the framework of enhancing transparency and responsiveness. To the demands of the business sector and industrialists. The Minister revealed, in his Facebook post in response to some inquiries, that the specified advance percentage [...]', 'قال وزير المالية محمد يسر برنية، الأحد 29 آذار، إن السلفة الضريبية على فاتورة الاستيراد سيتم استيفاؤها بالليرة السورية، من خلال البنوك السورية، وبحسب سعر صرف مصرف سورية المركزي، وذلك في إطار تعزيز الشفافية والاستجابة لمطالب قطاع الأعمال والصناعيين. وكشف الوزير، في منشوره على فيس بوك في إجابة على بعض الاستفسارات، أن نسبة السلفة المحددة بـ 2% ستخضع لإعادة النظر بعد صدور المرسوم الجديد الخاص بضريبة الدخل الموحد، استجابة لملاحظات الصناعيين الذين اعتبروا النسبة مرتفعة مقارنة ب 1% في السابق. وأشار برنية إلى أن الوزارة ستصدر تعميم في القريب يقضي بإعفاء مستوردات الأصول الرأسمالية، كالتجهيزات والآلات، من السلفة الضريبية عند استيرادها من قبل المنشآت الصناعية. وفيما يتعلق بتراكم الملفات الضريبية، بين الوزير أن تعليمات ستصدر بهذا الخصوص لتسريع الإنجاز ودراسة الملفات بعناية، حيث سيكون هناك فترة زمنية لا يمكن لمديريات المالية تجاوزها لإنجاز تدقيق البيا Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d9%85%d8%a7%d9%84%d9%8a%d8%a9-%d9%8a%d9%88%d8%b6%d8%ad-%d8%a2%d9%84%d9%8a%d8%a9-%d8%a7%d9%84%d8%b3%d9%84%d9%81%d8%a9-%d8%a7%d9%84%d8%b6%d8%b1%d9%8a%d8%a8%d9%8a/', 'Finance Minister Muhammad Yusser Barneyah said on Sunday, March 29, that the tax advance on the import bill will be collected in Syrian pounds, through Syrian banks, and according to the exchange rate of the Central Bank of Syria, within the framework of enhancing transparency and responsiveness. To the demands of the business sector and industrialists. The Minister revealed, in his Facebook post in response to some inquiries, that the advance rate set at 2% will be subject to reconsideration after the issuance of the new decree on the unified income tax, in response to comments. Industrialists who considered the percentage high compared to 1% previously. Bernieh indicated that the Ministry will issue a circular in the near future to exempt imports of capital assets, such as equipment and machinery, from the tax advance when imported by establishments. Industrial. Regarding the accumulation of tax files, the Minister stated that instructions will be issued in this regard to speed up completion and study the files carefully, as there will be a period of time that the Finance Directorates cannot exceed to complete the data audit. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d9%85%d8%a7%d9%84%d9%8a%d8%a9-%d9%8a%d9%88%d8%b6 %d8%ad-%d8%a2%d9%84%d9%8a%d8%a9-%d8%a7%d9%84%d8%b3%d9%84%d9%81%d8%a9-%d8%a7%d9%84%d8%b6%d8%b1%d9%8a%d8%a8%d9%8 a/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Finance-Minister-Yasser-Barneh-2-1.jpg', (select id from public.categories where slug = 'news-economy' and type = 'news' limit 1), (select id from public.locations order by id offset 5 limit 1), '2026-03-29T19:18:15+03:00'::timestamptz, false, false, false, 171),
  ('حلب.. الأمن الداخلي يلقي القبض على متطوع سابق في الأمن العسكري', 'Aleppo.. Internal Security arrests a former military security volunteer', 'أعلنت قوى الأمن الداخلي، الأربعاء 1 نيسان، إلقاء القبض على المدعو محمود إبراهيم خضور المتطوع سابقاً في فرع الأمن العسكري (290) بمدينة حلب خلال فترة حكم النظام البائد. وأوضحت وزارة الداخلية عبر معرفاتها الرسمية أن العملية جاءت استناداً إلى ورود بلاغات متعددة من الأهالي تثبت تورطه في ارتكاب انتهاكات جسيمة وجرائم خلال خدمته في صفوف […]', 'On Wednesday, April 1, the Internal Security Forces announced the arrest of Mahmoud Ibrahim Khadour, a former volunteer in the Military Security Branch (290) in the city of Aleppo during the period of the former regime’s rule. The Ministry of Interior explained through its official accounts that The operation was based on the receipt of multiple reports from families proving his involvement in committing serious violations and crimes during his service in the ranks […]', 'أعلنت قوى الأمن الداخلي، الأربعاء 1 نيسان، إلقاء القبض على المدعو محمود إبراهيم خضور المتطوع سابقاً في فرع الأمن العسكري (290) بمدينة حلب خلال فترة حكم النظام البائد. وأوضحت وزارة الداخلية عبر معرفاتها الرسمية أن العملية جاءت استناداً إلى ورود بلاغات متعددة من الأهالي تثبت تورطه في ارتكاب انتهاكات جسيمة وجرائم خلال خدمته في صفوف النظام المخلوع. وبيّنت التحقيقات الأولية أن المذكور تطوّع عام 2013 في فرع الأمن العسكري بحلب قبل أن ينقل لاحقاً إلى حماة، حيث عمل على حاجز يعرف باسم “البطاطا” الواقع على طريق السلمية – حماة. وأشارت التحقيقات إلى تورطه في سرقة أموال وممتلكات المدنيين والاعتداء على عدد منهم أثناء مرورهم عبر الحاجز. وأكد الأمن الداخلي أنه تم تحويل المقبوض عليه إلى إدارة مكافحة الإرهاب لاستكمال التحقيقات واتخاذ الإجراءات القانونية اللازمة بحقه. وتأتي هذه العملية ضمن خطة وزارة الداخلية لإعادة الأمن ومحاسبة المجرمين والمتورّطين خلال فتر Source: https://alikhbariah.com/%d8%ad%d9%84%d8%a8-%d8%a7%d9%84%d8%a3%d9%85%d9%86-%d8%a7%d9%84%d8%af%d8%a7%d8%ae%d9%84%d9%8a-%d9%8a%d9%84%d9%82%d9%8a-%d8%a7%d9%84%d9%82%d8%a8%d8%b6-%d8%b9%d9%84%d9%89-%d9%85%d8%aa%d8%b7%d9%88%d8%b9/', 'On Wednesday, April 1, the Internal Security Forces announced the arrest of Mahmoud Ibrahim Khadour, a former volunteer in the Military Security Branch (290) in the city of Aleppo during the period of the former regime’s rule. The Ministry of Interior explained through its official accounts that The operation was based on multiple reports from residents proving his involvement in committing serious violations and crimes during his service in the ranks of the ousted regime. Preliminary investigations showed that the aforementioned volunteered in 2013 in the Military Security Branch in Aleppo before that He was later transferred to Hama, where he worked at a checkpoint known as “Al-Batata” located on the Salamiyah-Hama road. Investigations indicated his involvement in stealing money and property from civilians and assaulting a number of them as they passed through the checkpoint. Internal security confirmed The arrested person was transferred to the Counter-Terrorism Department to complete investigations and take the necessary legal measures against him. This operation comes within the Ministry of Interior’s plan to restore security and hold criminals and those involved accountable during the period Source: https://alikhbariah.com/%d8%ad%d9%84%d8%a8-%d8%a7%d9%84%d8%a3%d9%85%d9%86-%d8%a7%d9%84%d8%af%d8%a7%d8%ae%d9%84 %d9%8a-%d9%8a%d9%84%d9%82%d9%8a-%d8%a7%d9%84%d9%82%d8%a8%d8%b6-%d8%b9%d9%84%d9%89-%d9%85%d8%aa%d8%b7%d9%88%d8% b9/', 'https://alikhbariah.com/wp-content/uploads/2026/04/criminal.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 6 limit 1), '2026-04-01T09:30:11+03:00'::timestamptz, false, true, false, 170),
  ('أجواء ربيعية نهاراً.. ومنخفض جوي جديد يبدأ مساءً', 'Spring weather during the day... and a new depression starting in the evening', 'تشهد البلاد، اليوم الأربعاء 1 نيسان، حالة من عدم الاستقرار حيث تكون الأجواء غائمة جزئياً نهاراً لتتحول إلى غائمة ماطرة مساء اليوم، بسبب تأثرها بمنخفض جوي يستمر حتى مساء الجمعة القادمة، بحسب النشرة الصادرة عن المديرية العامة للأرصاد الجوية التابعة لوزارة الطوارئ وإدارة الكوارث. وكانت أجواء الليلة الماضية باردة نسبياً وخاصةً في المرتفعات الجبلية، مع […]', 'Today, Wednesday, April 1, the country is witnessing a state of instability, as the weather is partly cloudy during the day, turning to cloudy and rainy this evening, due to it being affected by an air depression that will continue until next Friday evening, according to the bulletin issued by the directorate. General Meteorology Department of the Ministry of Emergency and Disaster Management. The weather last night was relatively cold, especially in the mountain highlands, with [...]', 'تشهد البلاد، اليوم الأربعاء 1 نيسان، حالة من عدم الاستقرار حيث تكون الأجواء غائمة جزئياً نهاراً لتتحول إلى غائمة ماطرة مساء اليوم، بسبب تأثرها بمنخفض جوي يستمر حتى مساء الجمعة القادمة، بحسب النشرة الصادرة عن المديرية العامة للأرصاد الجوية التابعة لوزارة الطوارئ وإدارة الكوارث. وكانت أجواء الليلة الماضية باردة نسبياً وخاصةً في المرتفعات الجبلية، مع تسجيل حالات لتشكل الضباب في أجزاء من المنطقة الوسطى والشمالية والجزيرة خلال الليل والصباح الباكر. ويكون الطقس ، اليوم الأربعاء، ربيعياً دافئاً بين الصحو والغائم جزئياً بشكلٍ عام يتحول إلى غائم مساءً، بدءاً من المناطق الجنوبية والجنوبية الغربية والساحلية لتصبح الفرصة مهيأة لهطل الأمطار ويمتد الهطل خلال ساعات منتصف الليل وساعات الفجر إلى أغلب المناطق. وتوالي درجات الحرارة ارتفاعها في كل المناطق لتصبح قريبة من معدلاتها لمثل هذه الفترة من السنة. وتكون الرياح جنوبية إلى جنوبية شرقية بين الخفيفة والمع Source: https://alikhbariah.com/%d8%a3%d8%ac%d9%88%d8%a7%d8%a1-%d8%b1%d8%a8%d9%8a%d8%b9%d9%8a%d8%a9-%d9%86%d9%87%d8%a7%d8%b1%d8%a7%d9%8b-%d9%88%d9%85%d9%86%d8%ae%d9%81%d8%b6-%d8%ac%d9%88%d9%8a-%d8%ac%d8%af%d9%8a%d8%af-%d9%8a%d8%a8/', 'Today, Wednesday, April 1, the country is witnessing a state of instability, as the weather is partly cloudy during the day, turning to cloudy and rainy this evening, due to it being affected by an air depression that will continue until next Friday evening, according to the bulletin issued by the directorate. General Meteorology Department of the Ministry of Emergency and Disaster Management. The weather last night was relatively cold, especially in the mountain highlands, with cases of fog formation recorded in parts of the central and northern regions and the island during the night. And early morning. The weather today, Wednesday, will be spring-warm, between clear and partly cloudy in general, turning to cloudy in the evening, starting from the southern, southwestern and coastal regions, so that the opportunity will be ripe for rainfall and the rainfall will extend. During the midnight and dawn hours to most areas. Temperatures continue to rise in all regions, becoming close to their average for this period of the year. The winds will be southerly to southeasterly, between light and bright. Source: https://alikhbariah.com/%d8%a3%d8%ac%d9%88%d8%a7%d8%a1-%d8%b1%d8%a8%d9%8a%d8%b9%d9%8a%d8%a9-%d9%86%d9%87%d8%a7 %d8%b1%d8%a7%d9%8b-%d9%88%d9%85%d9%86%d8%ae%d9%81%d8%b6-%d8%ac%d9%88%d9%8a-%d8%ac%d8%af%d9%8a%d8%af-%d9%8a%d8% a8/', 'https://alikhbariah.com/wp-content/uploads/2026/04/the-weather-3.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 7 limit 1), '2026-04-01T06:39:47+03:00'::timestamptz, false, true, false, 169),
  ('بعد انقطاع 9 سنوات.. عودة الكهرباء إلى حيي الحميدية وخسارات بدير الزور', 'After a 9-year interruption, electricity returns to the Hamidiya neighborhood and losses in Deir ez-Zor', 'أعلن وزير الطاقة محمد البشير، عودة التيار الكهربائي إلى حيّي الحميدية وخسارات في محافظة دير الزور، بعد انقطاع دام 9 سنوات. وجاء ذلك في منشور له على حسابه في منصة إكس الثلاثاء 31 آذار، قال فيه: “بعد 9 سنوات من العتمة، تعود الكهرباء إلى حيّي الحميدية وخسارات في محافظة دير الزور، ليعود معها النور ويزهر […]', 'The Minister of Energy, Muhammad al-Bashir, announced the return of electricity to the Al-Hamidiyah and Khasarat neighborhoods in Deir ez-Zor Governorate, after a 9-year interruption. This came in a post on his account on the X platform on Tuesday, March 31, in which he said: “After 9 years of darkness, Electricity returns to the Al-Hamidiyah and Khassar neighborhoods in Deir ez-Zor Governorate, so that light returns and blooms […]', 'أعلن وزير الطاقة محمد البشير، عودة التيار الكهربائي إلى حيّي الحميدية وخسارات في محافظة دير الزور، بعد انقطاع دام 9 سنوات. وجاء ذلك في منشور له على حسابه في منصة إكس الثلاثاء 31 آذار، قال فيه: “بعد 9 سنوات من العتمة، تعود الكهرباء إلى حيّي الحميدية وخسارات في محافظة دير الزور، ليعود معها النور ويزهر الأمل بحياة أفضل لأبناء المنطقة”. وفي كانون الأول الفائت، نفذت منظمة ADRA بالتعاون مع الشركة العامة لكهرباء دير الزور، مشروعاً لتركيب 800 جهاز إنارة تعمل بالطاقة الشمسية في عدد من أحياء مدينة دير الزور، وذلك بدعم من المفوضية السامية للأمم المتحدة لشؤون اللاجئين. وشملت أعمال تركيب أجهزة الإنارة أحياء الحويقة والرشدية والشيخ ياسين والشارع العام وفيلات البلدية والضاحية – شارع الأربعين والجبيلة والقصور وهرابش (المطار القديم) والصناعة والعرضي، بحسب ما نشرت محافظة دير الزور عبر معرفاتها الرسمية. Source: https://alikhbariah.com/%d8%a8%d8%b9%d8%af-%d8%a7%d9%86%d9%82%d8%b7%d8%a7%d8%b9-9-%d8%b3%d9%86%d9%88%d8%a7%d8%aa-%d8%b9%d9%88%d8%af%d8%a9-%d8%a7%d9%84%d9%83%d9%87%d8%b1%d8%a8%d8%a7%d8%a1-%d8%a5%d9%84%d9%89-%d8%ad%d9%8a/', 'The Minister of Energy, Muhammad al-Bashir, announced the return of electricity to the Al-Hamidiyah and Khasarat neighborhoods in Deir ez-Zor Governorate, after a 9-year interruption. This came in a post on his account on the X platform on Tuesday, March 31, in which he said: “After 9 years of darkness, “Electricity returns to the Al-Hamidiyah and Khassar neighborhoods in Deir ez-Zor Governorate, bringing with it light and hope for a better life for the people of the region to flourish.” Last December, ADRA, in cooperation with the General Electricity Company of Deir ez-Zor, implemented a project to install 800 solar-powered lighting devices in a number of neighborhoods in Deir ez-Zor, with support from the United Nations High Commissioner for Refugees. The lighting installation work included the neighborhoods of Al-Hawaiqa, Al-Rashidiya, Sheikh Yassin, Main Street, and Villas The municipality and the suburb - Al-Arbaeen Street, Al-Jubaila, Al-Qusour, Harabesh (the old airport), Al-Sina''a, and Al-Ardi, according to what Deir ez-Zor Governorate published through its official accounts. Source: https://alikhbariah.com/%d8%a8%d8%b9%d8%af-%d8%a7%d9%86%d9%82%d8%b7%d8%a7%d8%b9-9-%d8%b3%d9%86%d9%88%d8%a7%d8 /', 'https://alikhbariah.com/wp-content/uploads/2026/03/electricity-2.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 8 limit 1), '2026-03-31T23:36:53+03:00'::timestamptz, false, false, false, 168),
  ('الدفاع المدني ينفذ أعمالاً خدمية في إدلب', 'Civil Defense carries out service work in Idlib', 'نفذت فرق الدفاع المدني، الثلاثاء 31 آذار، أعمالاً خدمية في محافظة إدلب شملت ترميم طرق وإزالة أنقاض، بهدف تحسين السلامة المرورية وتسهيل حركة المدنيين. وعملت الفرق على ترميم طريق خربة الجوز ـ الزوف، نتيجة حدوث انهدام في طبقة الزفت، ما يسهم في تحسين واقع الطريق وتسهيل تنقل الأهالي، بحسب ما نشرت مديرية الطوارئ وإدارة الكوارث […]', 'On Tuesday, March 31, civil defense teams carried out service work in Idlib Governorate, including restoring roads and removing rubble, with the aim of improving traffic safety and facilitating the movement of civilians. The teams worked to restore the Khirbet al-Jawz-Zouf road, as a result of a collapse in The asphalt layer, which contributes to improving the reality of the road and facilitating the movement of people, according to what was published by the Directorate of Emergency and Disaster Management […]', 'نفذت فرق الدفاع المدني، الثلاثاء 31 آذار، أعمالاً خدمية في محافظة إدلب شملت ترميم طرق وإزالة أنقاض، بهدف تحسين السلامة المرورية وتسهيل حركة المدنيين. وعملت الفرق على ترميم طريق خربة الجوز ـ الزوف، نتيجة حدوث انهدام في طبقة الزفت، ما يسهم في تحسين واقع الطريق وتسهيل تنقل الأهالي، بحسب ما نشرت مديرية الطوارئ وإدارة الكوارث في إدلب. وقالت المديرية، إن الفرق نفذت أيضاً أعمال إزالة أنقاض وفتح طرقات في بلدة جرجناز، ضمن مشروع إزالة الأنقاض الذي أطلقته وزارة الطوارئ وإدارة الكوارث في منطقة معرة النعمان. وأكدت أن هذه الأعمال تأتي في إطار إعادة تأهيل البنية التحتية وتحسين الخدمات الأساسية، بما ينعكس إيجاباً على حياة المدنيين ويسهم في تسهيل حركتهم اليومية. وفي منتصف شباط الفائت، أطلقت وزارة الطوارئ وإدارة الكوارث بالتعاون مع محافظة إدلب، مشروعاً لإزالة الأنقاض من الطرقات الرئيسية والفرعية في مناطق خان شيخون ومعرة النعمان وجسر الشغور وأريافها في المح Source: https://alikhbariah.com/%d8%a7%d9%84%d8%af%d9%81%d8%a7%d8%b9-%d8%a7%d9%84%d9%85%d8%af%d9%86%d9%8a-%d9%8a%d9%86%d9%81%d8%b0-%d8%a3%d8%b9%d9%85%d8%a7%d9%84-%d8%ae%d8%af%d9%85%d9%8a%d8%a9-%d9%81%d9%8a-%d8%a5%d8%af%d9%84%d8%a8/', 'On Tuesday, March 31, civil defense teams carried out service work in Idlib Governorate, including restoring roads and removing rubble, with the aim of improving traffic safety and facilitating the movement of civilians. The teams worked to restore the Khirbet al-Jawz-Zouf road, as a result of a collapse in The asphalt layer, which contributes to improving the road situation and facilitating the movement of people, according to what was published by the Directorate of Emergency and Disaster Management in Idlib. The directorate said that the teams also carried out the work of removing rubble and opening roads in the town of Jarjanaz, as part of the rubble removal project. Which was launched by the Ministry of Emergency and Disaster Management in the Maarat al-Numan region. She stressed that these works come within the framework of rehabilitating infrastructure and improving basic services, which will reflect positively on the lives of civilians and contribute to facilitating their daily movement. In mid-February, the Ministry of Emergency and Disaster Management, in cooperation with Idlib Governorate, launched a project to remove rubble from the main and secondary roads in the areas of Khan Shaykhun, Maarat al-Numan, Jisr al-Shughur, and its countryside in al-Maḥah. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%af%d9%81%d8%a7%d8%b9-%d8%a7%d9%84%d9%85%d8%af%d9%86%d9%8a-%d9%8a%d9%86 %d9%81%d8%b0-%d8%a3%d8%b9%d9%85%d8%a7%d9%84-%d8%ae%d8%af%d9%85%d9%8a%d8%a9-%d9%81%d9%8a-%d8%a5%d8%af%d9%84%d8% a8/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Civil-Defense-teams.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 9 limit 1), '2026-03-31T22:25:30+03:00'::timestamptz, false, false, false, 167),
  ('وزير الدفاع يجري جولة تفقدية إلى لواء المدرعات', 'The Minister of Defense conducts an inspection tour of the Armored Brigade', 'أجرى وزير الدفاع اللواء المهندس مرهف أبو قصرة جولة تفقدية إلى لواء المدرعات في الجيش العربي السوري،الثلاثاء 31 آذار. والتقى الوزير أبو قصرة خلال الجولة بقائد اللواء العميد عبد الباسط الجمال وعدد من الضباط العاملين فيه، بحسب ما نشرت وزارة الدفاع عبر معرفاتها الرسمية. وفي 25 آذار الجاري، استقبل وزير الدفاع، مؤسس “الجيش الحر” العميد […]', 'The Minister of Defense, Major General Engineer Murhaf Abu Qasra, conducted an inspection tour to the Armored Brigade in the Syrian Arab Army, Tuesday, March 31. During the tour, Minister Abu Qasra met with the brigade commander, Brigadier General Abdel Baset Al-Jamal, and a number of officers working in it. According to what the Ministry of Defense published through its official accounts. On March 25, the Minister of Defense, founder of the Free Army, received Brigadier General […]', 'أجرى وزير الدفاع اللواء المهندس مرهف أبو قصرة جولة تفقدية إلى لواء المدرعات في الجيش العربي السوري،الثلاثاء 31 آذار. والتقى الوزير أبو قصرة خلال الجولة بقائد اللواء العميد عبد الباسط الجمال وعدد من الضباط العاملين فيه، بحسب ما نشرت وزارة الدفاع عبر معرفاتها الرسمية. وفي 25 آذار الجاري، استقبل وزير الدفاع، مؤسس “الجيش الحر” العميد رياض الأسعد في مكتبه بدمشق، حيث جرى تبادل التهاني بمناسبة عيد الفطر المبارك، وبحث آلية عمل الهيئة الاستشارية العليا في وزارة الدفاع. وقال مدير إدارة الإعلام والاتصال في وزارة الدفاع عاصم غليون، إن اللقاء تضمن مناقشة آلية عمل الهيئة الاستشارية العليا، إضافة إلى عدد من الملفات الأخرى. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%af%d9%81%d8%a7%d8%b9-%d9%8a%d8%ac%d8%b1%d9%8a-%d8%ac%d9%88%d9%84%d8%a9-%d8%aa%d9%81%d9%82%d8%af%d9%8a%d8%a9-%d8%a5%d9%84%d9%89-%d9%84%d9%88%d8%a7%d8%a1-%d8%a7/', 'The Minister of Defense, Major General Engineer Murhaf Abu Qasra, conducted an inspection tour to the Armored Brigade in the Syrian Arab Army, Tuesday, March 31. During the tour, Minister Abu Qasra met with the brigade commander, Brigadier General Abdel Baset Al-Jamal, and a number of officers working in it. According to what the Ministry of Defense published through its official accounts. On March 25, the Minister of Defense received the founder of the Free Army, Brigadier General Riad Al-Asaad, in his office in Damascus, where they exchanged congratulations on the occasion of Eid Al-Fitr, and discussed the Authority’s work mechanism. Senior Advisory in the Ministry of Defence. Director of the Media and Communications Department at the Ministry of Defense, Assem Ghalioun, said that the meeting included a discussion of the mechanism of work of the Supreme Advisory Commission, in addition to a number of other files. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%af%d9%81%d8%a7%d8%b9-%d9%8a%d8%ac%d8%b1%d9%8a -%d8%ac%d9%88%d9%84%d8%a9-%d8%aa%d9%81%d9%82%d8%af%d9%8a%d8%a9-%d8%a5%d9%84%d9%89-%d9%84%d9%88%d8%a7%d8%a1-%d8 %a7/', 'https://alikhbariah.com/wp-content/uploads/2026/04/Ministry-of-Defense-7.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 10 limit 1), '2026-03-31T21:24:32+03:00'::timestamptz, false, false, false, 166),
  ('بعد تحويلها محلياً.. المنافذ والجمارك تعلن انطلاق باخرة لنقل المواشي من مرفأ بانياس', 'After transferring them locally, ports and customs announce the launch of a ship to transport livestock from Baniyas port', 'أعلنت الهيئة العامة للمنافذ والجمارك، الثلاثاء 31 آذار، انطلاق باخرة سورية متخصصة بنقل المواشي من مرفأ بانياس، وذلك بعد استكمال أعمال تحويلها محلياً من باخرة تجارية إلى باخرة مهيأة لهذا الغرض. ويعد هذا المشروع، الذي أنجز خلال فترة قياسية لم تتجاوز ستة أشهر، خطوة تعكس تطور القدرات الفنية المحلية في قطاع النقل البحري، حيث أصبحت […]', 'The General Authority of Ports and Customs announced, on Tuesday, March 31, the launch of a Syrian ship specialized in transporting livestock from the port of Baniyas, after completing the work of converting it locally from a commercial ship to a ship prepared for this purpose. This project, which It was completed within a record period of no more than six months, a step that reflects the development of local technical capabilities in the maritime transport sector, as it became [...]', 'أعلنت الهيئة العامة للمنافذ والجمارك، الثلاثاء 31 آذار، انطلاق باخرة سورية متخصصة بنقل المواشي من مرفأ بانياس، وذلك بعد استكمال أعمال تحويلها محلياً من باخرة تجارية إلى باخرة مهيأة لهذا الغرض. ويعد هذا المشروع، الذي أنجز خلال فترة قياسية لم تتجاوز ستة أشهر، خطوة تعكس تطور القدرات الفنية المحلية في قطاع النقل البحري، حيث أصبحت الباخرة قادرة على نقل نحو 20 ألف رأس من الأغنام، موزعة على 6 طوابق مجهزة وفق معايير السلامة المعتمدة عالمياً، بحسب ما نشرت الهيئة العامة للمنافذ والجمارك عبر معرفاتها الرسمية. ويشكل هذا الإنجاز إضافة نوعية لقطاع النقل البحري، ويعزز حضور سوريا في مجال النقل البحري الإقليمي والدولي، إلى جانب إبراز الدور الحيوي الذي يلعبه مرفأ بانياس في استقطاب الكفاءات وتطوير مهاراتها. وأكدت الهيئة أن تنفيذ المشروع بخبرات محلية يشجع الاعتماد على الكفاءات الوطنية، ويفتح المجال أمام تطوير أعمال صيانة السفن وتحويلها محلياً، بما يساهم في د Source: https://alikhbariah.com/%d8%a8%d8%b9%d8%af-%d8%aa%d8%ad%d9%88%d9%8a%d9%84%d9%87%d8%a7-%d9%85%d8%ad%d9%84%d9%8a%d8%a7%d9%8b-%d8%a7%d9%84%d9%85%d9%86%d8%a7%d9%81%d8%b0-%d9%88%d8%a7%d9%84%d8%ac%d9%85%d8%a7%d8%b1%d9%83-%d8%aa/', 'The General Authority of Ports and Customs announced, on Tuesday, March 31, the launch of a Syrian ship specialized in transporting livestock from the port of Baniyas, after completing the work of converting it locally from a commercial ship to a ship prepared for this purpose. This project, which It was completed within a record period of no more than six months, a step that reflects the development of local technical capabilities in the maritime transport sector, as the ship became capable of transporting about 20 thousand heads of sheep, distributed on 6 decks equipped in accordance with approved safety standards. Globally, according to what the General Authority of Ports and Customs published through its official accounts. This achievement constitutes a qualitative addition to the maritime transport sector, and enhances Syria’s presence in the field of regional and international maritime transport, in addition to highlighting the vital role it plays. Baniyas Port in attracting talent and developing their skills. The Authority stressed that implementing the project with local expertise encourages reliance on national competencies, and opens the way for the development of ship maintenance and conversion work locally, which contributes to the development of ships. https://alikhbariah.com/%d8%a8%d8%b9%d8%af-%d8%aa%d8%ad%d9%88%d9%8a%d9%84%d9%87%d8%a7-%d9%85%d8%ad%d9%84%d9%8a %d8%a7%d9%8b-%d8%a7%d9%84%d9%85%d9%86%d8%a7%d9%81%d8%b0-%d9%88%d8%a7%d9%84%d8%ac%d9%85%d8%a7%d8%b1%d9%83-%d8%a a/', 'https://alikhbariah.com/wp-content/uploads/2026/03/steamer.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 11 limit 1), '2026-03-31T19:04:46+03:00'::timestamptz, false, false, false, 165),
  ('وزير الأوقاف يبحث مع وزير الحج والعمرة السعودية آليات تعزيز التنسيق والتعاون المشترك', 'The Minister of Endowments discusses with the Saudi Minister of Hajj and Umrah mechanisms to enhance coordination and joint cooperation', 'بحث وزير الأوقاف محمد أبو الخير شكري، الثلاثاء 31 آذار، مع وزير الحج والعمرة في المملكة العربية السعودية توفيق الربيعة، آليات تعزيز التنسيق والتعاون المشترك بما يسهم في تقديم أفضل الخدمات للحجاج وتيسير أدائهم لمناسكهم. وجرى خلال اللقاء استعراض التحضيرات الجارية لموسم حج عام 1447هـ، وذلك على هامش زيارته السعودية للمشاركة في منتدى العمرة والزيارة […]', 'On Tuesday, March 31, the Minister of Endowments, Muhammad Abu Al-Khair Shukri, discussed with the Minister of Hajj and Umrah in the Kingdom of Saudi Arabia, Tawfiq Al-Rabiah, mechanisms for enhancing coordination and joint cooperation in a way that contributes to providing the best services to pilgrims and facilitating their performance of their rituals. During the meeting, the ongoing preparations for the Hajj season of 1447 AH were reviewed, on the sidelines of his visit to Saudi Arabia to participate in the Umrah Forum and visit […]', 'بحث وزير الأوقاف محمد أبو الخير شكري، الثلاثاء 31 آذار، مع وزير الحج والعمرة في المملكة العربية السعودية توفيق الربيعة، آليات تعزيز التنسيق والتعاون المشترك بما يسهم في تقديم أفضل الخدمات للحجاج وتيسير أدائهم لمناسكهم. وجرى خلال اللقاء استعراض التحضيرات الجارية لموسم حج عام 1447هـ، وذلك على هامش زيارته السعودية للمشاركة في منتدى العمرة والزيارة الذي تقيمه وزارة الحج والعمرة السعودية، بحسب ما نشرت وزارة الأوقاف عبر معرفاتها الرسمية. وأكد وزير الأوقاف شكري أهمية استمرار التنسيق والتعاون المشترك، معرباً عن تقديره للجهود الكبيرة التي تبذلها المملكة العربية السعودية في خدمة ضيوف الرحمن. من جانبه، أشاد وزير الحج والعمرة السعودي بمتانة العلاقات بين البلدين، مثمناً الجهود المبذولة في تنظيم شؤون الحجاج والارتقاء بمستوى الخدمات المقدمة لهم. وكانت وزارة الصحة ، قد أعلنت في 25 آذار، البدء باستقبال الحجاج في مراكز اللقاح الدولي المعتمدة في المحافظات ل Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%a3%d9%88%d9%82%d8%a7%d9%81-%d9%8a%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%ad%d8%ac-%d9%88%d8%a7%d9%84%d8%b9%d9%85%d8%b1%d8%a9/', 'On Tuesday, March 31, the Minister of Endowments, Muhammad Abu Al-Khair Shukri, discussed with the Minister of Hajj and Umrah in the Kingdom of Saudi Arabia, Tawfiq Al-Rabiah, mechanisms for enhancing coordination and joint cooperation in a way that contributes to providing the best services to pilgrims and facilitating their performance of their rituals. During the meeting, the ongoing preparations for the Hajj season of 1447 AH were reviewed, on the sidelines of his visit to Saudi Arabia to participate in the Umrah and Visitation Forum held by the Saudi Ministry of Hajj and Umrah, according to what the Ministry of Endowments published through its official accounts. Minister of Endowments Shukri stressed the importance of continuing coordination and joint cooperation, expressing his appreciation for the great efforts made by the Kingdom of Saudi Arabia in serving the guests of God. For his part, the Saudi Minister of Hajj and Umrah praised the strength of relations between... Both countries, appreciating the efforts made in organizing the affairs of pilgrims and improving the level of services provided to them. On March 25, the Ministry of Health announced the start of receiving pilgrims at accredited international vaccination centers in the governorates. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%a3%d9%88%d9%82%d8%a7%d9%81-%d9%8a%d8%a8%d8%ad %d8%ab-%d9%85%d8%b9-%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%ad%d8%ac-%d9%88%d8%a7%d9%84%d8%b9%d9%85%d8%b1%d8% a9/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Religious-Endowments-Dr.-Muhammad-Abu-al-Khair-Shukri.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 12 limit 1), '2026-03-31T18:54:09+03:00'::timestamptz, false, false, false, 164),
  ('الهيئة العامة للإذاعة والتلفزيون تطلق مرحلة جديدة من البث الرقمي الأرضي “Syriasat”', 'The General Authority for Radio and Television launches a new phase of terrestrial digital broadcasting “Syriasat”', 'أعلن المدير العام للهيئة العامة للإذاعة والتلفزيون علاء برسيلو، الثلاثاء 31 آذار، إطلاق المرحلة الأولى من خدمة البث التلفزيوني الرقمي الأرضي “Syriasat” بالتعاون مع مؤسسة “SAT” الإعلامية اللبنانية. وأوضح في تصريح صحفي أن هذا المشروع جاء بعد تحضيرات مكثفة وترميم للبنية التحتية، واستكمال التجهيزات الفنية والتقنية، وتطوير محطات الإرسال التلفزيونية التابعة للهيئة، ليصار إلى بث […]', 'The Director General of the General Authority for Radio and Television, Alaa Barsilo, announced, on Tuesday, March 31, the launch of the first phase of the terrestrial digital television broadcast service “Syriasat”, in cooperation with the Lebanese media corporation “SAT”. He explained in a press statement that This project came after extensive preparations, restoration of the infrastructure, completion of technical equipment, and development of the Authority’s television transmission stations, so that it could broadcast […]', 'أعلن المدير العام للهيئة العامة للإذاعة والتلفزيون علاء برسيلو، الثلاثاء 31 آذار، إطلاق المرحلة الأولى من خدمة البث التلفزيوني الرقمي الأرضي “Syriasat” بالتعاون مع مؤسسة “SAT” الإعلامية اللبنانية. وأوضح في تصريح صحفي أن هذا المشروع جاء بعد تحضيرات مكثفة وترميم للبنية التحتية، واستكمال التجهيزات الفنية والتقنية، وتطوير محطات الإرسال التلفزيونية التابعة للهيئة، ليصار إلى بث 16 قناة تلفزيونية على تردد أرضي واحد. وأكد برسيلو أن المشروع يمثل نقلة نوعية في البث التلفزيوني الأرضي بسوريا، لافتاً إلى أن هذه الخطوة تأتي في إطار سعي الهيئة المتواصل لتقديم خدمات إعلامية تراعي اهتمامات جميع المواطنين. وتعتمد التقنية الجديدة في البث الرقمي الأرضي على موجة “UHF” بجودة عالية للصوت والصورة HD، والتي تسمح ببث 16 قناة على تردد واحد، تشمل برامج رياضية وثقافية وتعليمية وترفيهية، بما يوفر محتوى متنوعاً للمشاهدين عبر البث الأرضي. ويقدم مشروع الهيئة العامة للمشت Source: https://alikhbariah.com/%d8%a7%d9%84%d9%87%d9%8a%d8%a6%d8%a9-%d8%a7%d9%84%d8%b9%d8%a7%d9%85%d8%a9-%d9%84%d9%84%d8%a5%d8%b0%d8%a7%d8%b9%d8%a9-%d9%88%d8%a7%d9%84%d8%aa%d9%84%d9%81%d8%b2%d9%8a%d9%88%d9%86-%d8%aa%d8%b7%d9%84-2/', 'The Director General of the General Authority for Radio and Television, Alaa Barsilo, announced, on Tuesday, March 31, the launch of the first phase of the terrestrial digital television broadcast service “Syriasat”, in cooperation with the Lebanese media corporation “SAT”. He explained in a press statement that This project came after extensive preparations, restoration of the infrastructure, completion of technical equipment, and development of the authority’s television transmission stations, allowing 16 television channels to be broadcast on one terrestrial frequency. Barcello confirmed that the project It represents a qualitative leap in terrestrial television broadcasting in Syria, pointing out that this step comes within the framework of the Commission’s continuous endeavor to provide media services that take into account the interests of all citizens. The new technology in terrestrial digital broadcasting relies on the “UHF” wave. With high HD audio and video quality, which allows 16 channels to be broadcast on one frequency, including sports, cultural, educational and entertainment programs, providing diverse content to viewers via terrestrial broadcast. The project is presented by the General Authority for Water Resources: https://alikhbariah.com/%d8%a7%d9%84%d9%87%d9%8a%d8%a6%d8%a9-%d8%a7%d9%84%d8%b9%d8%a7%d9%85%d8%a9-%d9%84%d9%84 %d8%a5%d8%b0%d8%a7%d8%b9%d8%a9-%d9%88%d8%a7%d9%84%d8%aa%d9%84%d9%81%d8%b2%d9%8a%d9%88%d9%86-%d8%aa%d8%b7%d9%84 -2/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Alaa-Barsilo.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 13 limit 1), '2026-03-31T16:40:44+03:00'::timestamptz, false, false, false, 163),
  ('المنافذ والجمارك تجري جولة تفقدية في منفذ اليعربية تمهيداً لإعادة افتتاحه', 'Ports and Customs conduct an inspection tour at the Yarubiyah port in preparation for its reopening', 'أجرى معاون رئيس الهيئة العامة للمنافذ والجمارك خالد البراد، برفقة وفد من مديري المديريات المركزية، الثلاثاء 31 آذار، جولة تفقدية إلى منفذ اليعربية الحدودي في محافظة الحسكة، في إطار متابعة أعمال التأهيل ورفع الجاهزية التشغيلية للمنفذ تمهيداً لافتتاحه. واطلع الوفد خلال الجولة على أعمال صيانة البنية التحتية التي تنفذها مديرية المنشآت والصيانة، والتي تشمل تأهيل […]', 'On Tuesday, March 31, Assistant to the President of the General Authority of Ports and Customs, Khaled Al-Barrad, accompanied by a delegation of directors of the central directorates, conducted an inspection tour to the Al-Yarubiyah border crossing in Al-Hasakah Governorate, as part of following up on rehabilitation work and raising readiness. Operating the port in preparation for its opening. During the tour, the delegation was briefed on the infrastructure maintenance work carried out by the Directorate of Facilities and Maintenance, which includes rehabilitating [...]', 'أجرى معاون رئيس الهيئة العامة للمنافذ والجمارك خالد البراد، برفقة وفد من مديري المديريات المركزية، الثلاثاء 31 آذار، جولة تفقدية إلى منفذ اليعربية الحدودي في محافظة الحسكة، في إطار متابعة أعمال التأهيل ورفع الجاهزية التشغيلية للمنفذ تمهيداً لافتتاحه. واطلع الوفد خلال الجولة على أعمال صيانة البنية التحتية التي تنفذها مديرية المنشآت والصيانة، والتي تشمل تأهيل المرافق الخدمية، وتحسين جاهزية الساحات والطرق الداخلية، وصالات المسافرين والجمارك، إضافة إلى رفع كفاءة التجهيزات الفنية واللوجستية، بما يضمن تنظيم حركة العبور بشكل آمن وفعّال، بحسب ما نشرت الهيئة العامة عبر معرفاتها الرسمية. وأشارت الهيئة إلى أنه من المتوقع الانتهاء من أعمال التأهيل وإعادة تشغيل المنفذ مع بداية شهر أيار المقبل، في خطوة من شأنها دعم حركة التجارة وتعزيز الترابط الاقتصادي، إلى جانب تسهيل تنقل المواطنين عبر هذا المعبر الحيوي مع العراق. وتندرج هذه الجهود ضمن خطة الهيئة لإعا Source: https://alikhbariah.com/%d8%a7%d9%84%d9%85%d9%86%d8%a7%d9%81%d8%b0-%d9%88%d8%a7%d9%84%d8%ac%d9%85%d8%a7%d8%b1%d9%83-%d8%aa%d8%ac%d8%b1%d9%8a-%d8%ac%d9%88%d9%84%d8%a9-%d8%aa%d9%81%d9%82%d8%af%d9%8a%d8%a9-%d9%81%d9%8a-%d9%85/', 'On Tuesday, March 31, Assistant to the President of the General Authority of Ports and Customs, Khaled Al-Barrad, accompanied by a delegation of directors of the central directorates, conducted an inspection tour to the Al-Yarubiyah border crossing in Al-Hasakah Governorate, as part of following up on rehabilitation work and raising readiness. Operating the port in preparation for its opening. During the tour, the delegation was briefed on the infrastructure maintenance work carried out by the Directorate of Facilities and Maintenance, which includes rehabilitating service facilities, improving the readiness of squares, internal roads, and passenger lounges. and customs, in addition to raising the efficiency of technical and logistical equipment, to ensure that transit movement is organized safely and effectively, according to what the General Authority published through its official accounts. The Authority indicated that it is expected to complete the rehabilitation and restoration work The port will be operational at the beginning of next May, in a step that will support trade movement and enhance economic interconnection, in addition to facilitating the movement of citizens through this vital crossing with Iraq. These efforts fall within the Authority’s plan to revive Source: https://alikhbariah.com/%d8%a7%d9%84%d9%85%d9%86%d8%a7%d9%81%d8%b0-%d9%88%d8%a7%d9%84%d8%ac%d9%85%d8%a7%d8%b1% d9%83-%d8%aa%d8%ac%d8%b1%d9%8a-%d8%ac%d9%88%d9%84%d8%a9-%d8%aa%d9%81%d9%82%d8%af%d9%8a%d8%a9-%d9%81%d9%8a-%d9% 85/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Al-Yarubiyah-border-crossing.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 0 limit 1), '2026-03-31T15:40:10+03:00'::timestamptz, false, false, false, 162),
  ('وزيرة الشؤون الاجتماعية تبحث مع محافظ الحسكة ملف دمج العاملين والتنسيق المؤسسي', 'The Minister of Social Affairs discusses with the Governor of Al-Hasakah the file of worker integration and institutional coordination', '‏‏بحثت وزيرة الشؤون الاجتماعية والعمل هند قبوات مع محافظ الحسكة نور الدين أحمد، الثلاثاء 31 آذار، سبل تعزيز التعاون بين الجهات المعنية في المحافظة. ‏ ‏وذكرت محافظة الحسكة عبر معرفاتها الرسمية أن اللقاء تناول أهمية تكثيف التنسيق بين المؤسسات المختلفة، مع التركيز على ملف دمج العاملين في المديريات، مشيرة إلى مناقشة عدد من القضايا التنظيمية […]', 'Minister of Social Affairs and Labor, Hend Qabwat, discussed with the Governor of Al-Hasakah, Nour al-Din Ahmed, on Tuesday, March 31, ways to enhance cooperation between the concerned authorities in the governorate. Al-Hasakah Governorate stated through its official sources that the meeting discussed the importance of intensifying... Coordination between different institutions, with a focus on the issue of integrating workers into the directorates, noting the discussion of a number of organizational issues [...]', '‏‏بحثت وزيرة الشؤون الاجتماعية والعمل هند قبوات مع محافظ الحسكة نور الدين أحمد، الثلاثاء 31 آذار، سبل تعزيز التعاون بين الجهات المعنية في المحافظة. ‏ ‏وذكرت محافظة الحسكة عبر معرفاتها الرسمية أن اللقاء تناول أهمية تكثيف التنسيق بين المؤسسات المختلفة، مع التركيز على ملف دمج العاملين في المديريات، مشيرة إلى مناقشة عدد من القضايا التنظيمية والإدارية المرتبطة بسير العمل. ‏ ‏وأكد الطرفان خلال اللقاء ضرورة تحسين كفاءة المؤسسات الحكومية وتطوير أدائها بما ينعكس إيجاباً على مستوى الخدمات المقدمة في المحافظة. وكانت الوزيرة قبوات، قد بحثت في 26 آذار مع مبعوث رئاسة الجمهورية لمتابعة تنفيذ اتفاق 29 كانون الثاني مع قسد العميد زياد العايش، سبل تعزيز التنسيق ودعم الجهود الرامية إلى تطوير واقع العمل والخدمات في محافظة الحسكة. وجرى خلال اللقاء حينها التأكيد على أهمية إعادة دمج العاملين في المنطقة بما يسهم في تعزيز الاستقرار المؤسسي، حسب ما نشرت وزارة الشؤو Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1%d8%a9-%d8%a7%d9%84%d8%b4%d8%a4%d9%88%d9%86-%d8%a7%d9%84%d8%a7%d8%ac%d8%aa%d9%85%d8%a7%d8%b9%d9%8a%d8%a9-%d8%aa%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d9%85%d8%ad%d8%a7%d9%81%d8%b8/', 'Minister of Social Affairs and Labor, Hend Qabwat, discussed with the Governor of Al-Hasakah, Nour al-Din Ahmed, on Tuesday, March 31, ways to enhance cooperation between the concerned authorities in the governorate. Al-Hasakah Governorate stated through its official sources that the meeting discussed the importance of intensifying... Coordination between different institutions, with a focus on the file of integrating workers into the directorates, noting the discussion of a number of organizational and administrative issues related to the workflow. During the meeting, the two parties stressed the need to improve the efficiency of government institutions And developing its performance in a way that reflects positively on the level of services provided in the governorate. On March 26, Minister Qabwat discussed with the envoy of the Presidency of the Republic to follow up on the implementation of the January 29 agreement with the SDF, Brigadier General Ziad Al-Ayesh, ways to enhance coordination. And supporting efforts aimed at developing the reality of work and services in Al-Hasakah Governorate. During the meeting, the importance of reintegrating workers in the region was emphasized, which would contribute to enhancing institutional stability, according to what the Ministry of Affairs published. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1%d8%a9-%d8%a7%d9%84%d8%b4%d8%a4%d9%88%d9%86-%d8%a7%d9%84%d8%a7 %d8%ac%d8%aa%d9%85%d8%a7%d8%b9%d9%8a%d8%a9-%d8%aa%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d9%85%d8%ad%d8%a7%d9%81%d8%b 8/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Hind-Qabawat-1.jpg', (select id from public.categories where slug = 'news-local' and type = 'news' limit 1), (select id from public.locations order by id offset 1 limit 1), '2026-03-31T14:30:35+03:00'::timestamptz, false, false, false, 161),
  ('البرلمان الإيراني: مضيق هرمز لن يفتح ولم نجرِ أي مفاوضات مع أميركا وإسرائيل', 'Iranian Parliament: The Strait of Hormuz will not open, and we have not conducted any negotiations with America and Israel', 'أكد نائب رئيس البرلمان الإيراني، الأربعاء 1 نيسان، أن “مضيق هرمز لن يفتح”، مشيراً إلى أن بلاده لم تجري أي مفاوضات مع أميركا وإسرائيل. وأشار إلى أن “التصريحات بأن رئيس البرلمان يتفاوض لا أساس لها وتطرح لإثارة الفتنة”. ولفت إلى أن “قرار الحرب والسلم والمفاوضات من صلاحيات المرشد، ولم يصدر أي إذن للتفاوض بعد”. في […]', 'The Deputy Speaker of the Iranian Parliament confirmed, on Wednesday, April 1, that “the Strait of Hormuz will not open,” noting that his country had not conducted any negotiations with America and Israel. He pointed out that “the statements that the Speaker of Parliament is negotiating are baseless and are being made to stir up strife.” He pointed out that “decisions on war, peace, and negotiations are within the powers of the Leader, and no permission for negotiation has been issued yet.” in […]', 'أكد نائب رئيس البرلمان الإيراني، الأربعاء 1 نيسان، أن “مضيق هرمز لن يفتح”، مشيراً إلى أن بلاده لم تجري أي مفاوضات مع أميركا وإسرائيل. وأشار إلى أن “التصريحات بأن رئيس البرلمان يتفاوض لا أساس لها وتطرح لإثارة الفتنة”. ولفت إلى أن “قرار الحرب والسلم والمفاوضات من صلاحيات المرشد، ولم يصدر أي إذن للتفاوض بعد”. في المقابل، قال الرئيس الأميركي دونالد ترامب، في 26 آذار الماضي: إن “الإيرانيين يتوسلون إلينا لعقد صفقة وهو ما ينبغي عليهم فعله بعد هزيمتهم العسكرية الساحقة، ومع ذلك يصرحون علناً بأنهم ينظرون فقط في مقترحنا“. وأكد ترامب عبر منصة تروث سوشيال أنه “على الإيرانيين أخذ الأمر بجدية قبل فوات الأوان، لأنه بمجرد حدوث ذلك لن يكون هناك رجوع ولن يكون الأمر سهلاً”. وهدد الرئيس الأمريكي في 22 آذار الفائت باستهداف منشآت الطاقة الإيرانية، ممهلاً طهران 48 ساعة لإعادة فتح المضيق بالكامل أمام حركة الملاحة الدولية. وأقدمت إيران على إغلاق المضيق بعد الضربات Source: https://alikhbariah.com/%d8%a7%d9%84%d8%a8%d8%b1%d9%84%d9%85%d8%a7%d9%86-%d8%a7%d9%84%d8%a5%d9%8a%d8%b1%d8%a7%d9%86%d9%8a-%d9%85%d8%b6%d9%8a%d9%82-%d9%87%d8%b1%d9%85%d8%b2-%d9%84%d9%86-%d9%8a%d9%81%d8%aa%d8%ad-%d9%88%d9%84/', 'The Deputy Speaker of the Iranian Parliament confirmed, on Wednesday, April 1, that “the Strait of Hormuz will not open,” noting that his country had not conducted any negotiations with America and Israel. He pointed out that “the statements that the Speaker of Parliament is negotiating are baseless and are being made to stir up strife.” He pointed out that “decisions on war, peace, and negotiations are within the powers of the Leader, and no permission for negotiation has been issued yet.” On the other hand, US President Donald Trump said on March 26: “The Iranians are begging us to make a deal, which is what they should do.” After their crushing military defeat, yet they publicly state that they are only considering our proposal.” Trump stressed on the Truth Social platform that “the Iranians must take the matter seriously before it is too late, because once this happens there will be no going back and it will not be On March 22nd, the US President threatened to target Iranian energy facilities, giving Tehran 48 hours to fully reopen the strait to international shipping traffic. Iran closed the strait after the strikes. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%a8%d8%b1%d9%84%d9%85%d8%a7%d9%86-%d8%a7%d9%84%d8%a5%d9%8a%d8%b1%d8%a7% d9%86%d9%8a-%d9%85%d8%b6%d9%8a%d9%82-%d9%87%d8%b1%d9%85%d8%b2-%d9%84%d9%86-%d9%8a%d9%81%d8%aa%d8%ad-%d9%88%d9% 84/', 'https://alikhbariah.com/wp-content/uploads/2026/04/Strait-of-Hormuz.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 2 limit 1), '2026-04-01T10:00:53+03:00'::timestamptz, false, true, false, 160),
  ('الأمم المتحدة: خسائر الشرق الأوسط قد تصل إلى 194 مليار دولار جراء التصعيد العسكري', 'United Nations: Losses in the Middle East may reach $194 billion as a result of the military escalation', 'كشف برنامج الأمم المتحدة الإنمائي أن التصعيد العسكري في منطقة الشرق الأوسط قد يُكبّد اقتصادات المنطقة العربية خسارة هائلة تتراوح قيمتها بين 120 و194 مليار دولار أمريكي. وأكد البرنامج في تقرير نشره موقع الأمم المتحدة، الثلاثاء 31 آذار، أن هذه الخسارة يصاحبها ارتفاع في معدلات البطالة يُقدّر بنحو 4 نقاط مئوية، بما يعادل فقدان 3.6 […]', 'The United Nations Development Program revealed that the military escalation in the Middle East could cause the economies of the Arab region a huge loss worth between 120 and 194 billion US dollars. The program confirmed in a report published by the United Nations website, Tuesday, March 31, that this loss is accompanied by an increase in unemployment rates estimated at about 4 percentage points, equivalent to a loss of 3.6 […]', 'كشف برنامج الأمم المتحدة الإنمائي أن التصعيد العسكري في منطقة الشرق الأوسط قد يُكبّد اقتصادات المنطقة العربية خسارة هائلة تتراوح قيمتها بين 120 و194 مليار دولار أمريكي. وأكد البرنامج في تقرير نشره موقع الأمم المتحدة، الثلاثاء 31 آذار، أن هذه الخسارة يصاحبها ارتفاع في معدلات البطالة يُقدّر بنحو 4 نقاط مئوية، بما يعادل فقدان 3.6 ملايين وظيفة وهو عدد يفوق إجمالي الوظائف التي استحدثتها المنطقة خلال عام 2025، موضحاً أن هذه التداعيات الاقتصادية ستدفع 4 ملايين من سكان المنطقة إلى الفقر. وفي تعليقه على التقرير، قال عبد الله الدردري، مدير المكتب الإقليمي للدول العربية في برنامج الأمم المتحدة الإنمائي: إن “هذه الأزمة تدق أجراس الإنذار لدول المنطقة كي تعيد تقييم خياراتها الاستراتيجية المتعلقة بالسياسات المالية والاقتصادية والاجتماعية بشكل جذري، إذ تمثل هذه الأزمة نقطة تحول مهمة في المسار التنموي للمنطقة”. وأضاف الدردري أن الحاجة الملحة لتعزيز التعاو Source: https://alikhbariah.com/%d8%a7%d9%84%d8%a3%d9%85%d9%85-%d8%a7%d9%84%d9%85%d8%aa%d8%ad%d8%af%d8%a9-%d8%ae%d8%b3%d8%a7%d8%a6%d8%b1-%d8%a7%d9%84%d8%b4%d8%b1%d9%82-%d8%a7%d9%84%d8%a3%d9%88%d8%b3%d8%b7-%d9%82%d8%af-%d8%aa/', 'The United Nations Development Program revealed that the military escalation in the Middle East could cause the economies of the Arab region a huge loss worth between 120 and 194 billion US dollars. The program confirmed in a report published by the United Nations website, Tuesday, March 31, that this loss is accompanied by an increase in unemployment rates estimated at about 4 percentage points, equivalent to the loss of 3.6 million jobs, which is a number that exceeds the total jobs created by the region during the year 2025, explaining that these repercussions The economic crisis will push 4 million of the region''s residents into poverty. Commenting on the report, Abdullah Al-Dardari, Director of the Regional Office for Arab States at the United Nations Development Programme, said: “This crisis rings alarm bells for countries in the region to It is radically re-evaluating its strategic options related to financial, economic and social policies, as this crisis represents an important turning point in the region’s development path.” Al-Dardari added that there is an urgent need to enhance cooperation. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%a3%d9%85%d9%85-%d8%a7%d9%84%d9%85%d8%aa%d8%ad%d8%af%d8%a9-%d8%ae%d8% /', 'https://alikhbariah.com/wp-content/uploads/2026/04/Middle-East-losses.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 3 limit 1), '2026-04-01T08:30:01+03:00'::timestamptz, false, true, false, 159),
  ('ترامب: إيران ستحتاج إلى 20 عاماً لإعادة ما دمرناه', 'Trump: Iran will need 20 years to restore what we destroyed', 'قال الرئيس الأمريكي دونالد ترامب، إن “إيران ستحتاج 15 إلى 20 عاماً لإعادة بناء ما دمرناه في هذه العملية العسكرية”، مشيراً إلى أنه تم تغيير النظام في إيران، وفق ما نقلت شبكة أي بي سي، الثلاثاء 31 آذار. وأضاف ترامب، أن واشنطن باتت تتعامل مع مجموعة جديدة من النظام الإيراني أكثر عقلانية، لافتاً إلى أنه […]', 'US President Donald Trump said, “Iran will need 15 to 20 years to rebuild what we destroyed in this military operation,” noting that the regime has been changed in Iran, according to what ABC reported, Tuesday, March 31. Trump added, Washington is now dealing with a new group of the Iranian regime that is more rational, pointing out that […]', 'قال الرئيس الأمريكي دونالد ترامب، إن “إيران ستحتاج 15 إلى 20 عاماً لإعادة بناء ما دمرناه في هذه العملية العسكرية”، مشيراً إلى أنه تم تغيير النظام في إيران، وفق ما نقلت شبكة أي بي سي، الثلاثاء 31 آذار. وأضاف ترامب، أن واشنطن باتت تتعامل مع مجموعة جديدة من النظام الإيراني أكثر عقلانية، لافتاً إلى أنه ليس من الضروري إبرام طهران الاتفاق من أجل إنهاء هذه العملية العسكرية. وبيّن الرئيس الأمريكي، أن بلاده ستغادر إيران في غضون أسبوعين إلى ثلاثة، مضيفاً أنه “ما من سبب يستدعي بقاءنا”. وكان ترامب قد طالب حلفاءه بتحمل دور أكبر في السيطرة على مضيق هرمز، موجهاً انتقادات لاذعة للدول المتضررة من ارتفاع أسعار الوقود. كما طالت ضغوط الرئيس الأمريكي الحلفاء الأوروبيين، إذ انتقد بشدة فرنسا لمنعها تحليق طائرات الإمداد العسكري، مشيراً إلى أن الولايات المتحدة “ستتذكر ذلك”، كما انتقد كذلك إسبانيا وإيطاليا لتقييدهما حركة الطائرات الأميركية المتجهة للمنطقة. Source: https://alikhbariah.com/%d8%aa%d8%b1%d8%a7%d9%85%d8%a8-%d8%a5%d9%8a%d8%b1%d8%a7%d9%86-%d8%b3%d8%aa%d8%ad%d8%aa%d8%a7%d8%ac-%d8%a5%d9%84%d9%89-20-%d8%b9%d8%a7%d9%85%d8%a7%d9%8b-%d9%84%d8%a5%d8%b9%d8%a7%d8%af%d8%a9-%d9%85/', 'US President Donald Trump said, “Iran will need 15 to 20 years to rebuild what we destroyed in this military operation,” noting that the regime has been changed in Iran, according to what ABC reported, Tuesday, March 31. Trump added, Washington is now dealing with a new group of the Iranian regime that is more rational, pointing out that it is not necessary for Tehran to conclude the agreement in order to end this military operation. The American President stated that his country will leave Iran within two weeks Three, adding that “there is no reason for us to stay.” Trump had called on his allies to play a greater role in controlling the Strait of Hormuz, directing harsh criticism at countries affected by high fuel prices. The US President''s pressure also affected the allies The Europeans, as he strongly criticized France for preventing the flights of military supply planes, indicating that the United States “will remember that.” He also criticized Spain and Italy for restricting the movement of American aircraft heading to the region. Source: https://alikhbariah.com/%d8%aa%d8%b1%d8%a7%d9%85%d8%a8-%d8%a5%d9%8a%d8%b1%d8%a7%d9%86-%d8%b3%d8%aa%d8%ad%d8%aa /', 'https://alikhbariah.com/wp-content/uploads/2026/04/f7b58f2d39e56fe5e8082f1bab87a9c8-1_edit_40643050982880.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 4 limit 1), '2026-03-31T23:57:07+03:00'::timestamptz, false, false, false, 158),
  ('ترامب يهاجم فرنسا ويدعو للسيطرة على مضيق هرمز', 'Trump attacks France and calls for control of the Strait of Hormuz', 'أطلق الرئيس الأمريكي دونالد ترامب، الثلاثاء 31 آذار، سلسلة تصريحات عبر منصة “تروث سوشيال”، تناولت إمدادات الوقود والتوترات المرتبطة بمضيق هرمز، إلى جانب انتقادات مباشرة لفرنسا على خلفية مواقفها الأخيرة. حيث دعا ترامب الدول التي تواجه صعوبات في الحصول على وقود الطائرات بسبب إغلاق مضيق هرمز، ومن بينها بريطانيا، إلى شراء الوقود من الولايات المتحدة، […]', 'On Tuesday, March 31, US President Donald Trump launched a series of statements on the “Truth Social” platform, addressing fuel supplies and tensions related to the Strait of Hormuz, in addition to direct criticism of France against the backdrop of its recent positions. Where Trump called Countries facing difficulties in obtaining aviation fuel due to the closure of the Strait of Hormuz, including Britain, have decided to purchase fuel from the United States, […]', 'أطلق الرئيس الأمريكي دونالد ترامب، الثلاثاء 31 آذار، سلسلة تصريحات عبر منصة “تروث سوشيال”، تناولت إمدادات الوقود والتوترات المرتبطة بمضيق هرمز، إلى جانب انتقادات مباشرة لفرنسا على خلفية مواقفها الأخيرة. حيث دعا ترامب الدول التي تواجه صعوبات في الحصول على وقود الطائرات بسبب إغلاق مضيق هرمز، ومن بينها بريطانيا، إلى شراء الوقود من الولايات المتحدة، معتبراً أن على الدول غير القادرة على تأمين احتياجاتها “التحلي بالشجاعة” والتوجه إلى المضيق والسيطرة عليه. وأشار إلى أن إيران تعرضت لتدمير كبير، لافتاً إلى أن المرحلة الأصعب قد انتهت، في سياق حديثه عن التطورات الجارية في المنطقة. وفي سياق متصل، وجّه الرئيس الأمريكي انتقادات لاذعة إلى فرنسا، قائلاً إنها لم تسمح بمرور طائرات متجهة إلى إسرائيل ومحملة بإمدادات عسكرية عبر أجوائها، مضيفاً أنها لم تكن متعاونة على الإطلاق فيما يتعلق بما وصفه بجزار إيران، ومؤكداً أن الولايات المتحدة لن تنسى ذلك. وكان الرئيس Source: https://alikhbariah.com/%d8%aa%d8%b1%d8%a7%d9%85%d8%a8-%d9%8a%d9%87%d8%a7%d8%ac%d9%85-%d9%81%d8%b1%d9%86%d8%b3%d8%a7-%d9%88%d9%8a%d8%af%d8%b9%d9%88-%d9%84%d9%84%d8%b3%d9%8a%d8%b7%d8%b1%d8%a9-%d8%b9%d9%84%d9%89-%d9%85%d8%b6/', 'On Tuesday, March 31, US President Donald Trump launched a series of statements on the “Truth Social” platform, addressing fuel supplies and tensions related to the Strait of Hormuz, in addition to direct criticism of France against the backdrop of its recent positions. Where Trump called Countries that face difficulties in obtaining aviation fuel due to the closure of the Strait of Hormuz, including Britain, have decided to purchase fuel from the United States, considering that countries that are unable to secure their needs must “be brave” and go to... The strait and its control. He pointed out that Iran had been subjected to great destruction, pointing out that the most difficult stage had ended, in the context of his talk about the current developments in the region. In a related context, the American President directed harsh criticism at France, saying: It did not allow planes bound for Israel and loaded with military supplies to pass through its airspace, adding that it was not cooperative at all regarding what he described as the butchering of Iran, stressing that the United States would not forget that. The president was Source: https://alikhbariah.com/%d8%aa%d8%b1%d8%a7%d9%85%d8%a8-%d9%8a%d9%87%d8%a7%d8%ac%d9%85-%d9%81%d8%b1%d9%86%d8%b3 %d8%a7-%d9%88%d9%8a%d8%af%d8%b9%d9%88-%d9%84%d9%84%d8%b3%d9%8a%d8%b7%d8%b1%d8%a9-%d8%b9%d9%84%d9%89-%d9%85%d8% b6/', 'https://alikhbariah.com/wp-content/uploads/2026/03/US-President-3.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 5 limit 1), '2026-03-31T14:49:22+03:00'::timestamptz, false, false, false, 157),
  ('إيران تستهدف ناقلة نفط كويتية في ميناء دبي', 'Iran targets a Kuwaiti oil tanker in Dubai Port', 'تعرضت ناقلة النفط الخام العملاقة “السالمي” لاستهداف إيراني مباشر أثناء وجودها في منطقة المخطاف بميناء دبي في الإمارات. وقالت مؤسسة البترول الكويتية، الثلاثاء 31 آذار، إن “الناقلة كانت بكامل حمولتها”، مضيفة أن الاستهداف أسفر عن أضرار مادية في بدن السفينة واندلاع حريق على متنها، مع وجود احتمالية لتسرب نفطي في المياه المحيطة، وفق ما أوردت […]', 'The giant crude oil tanker “Al-Salmi” was subjected to direct Iranian targeting while it was in the anchorage area of ​​Dubai Port in the Emirates. The Kuwait Petroleum Corporation said, on Tuesday, March 31, that “the tanker was fully loaded,” adding that the targeting It resulted in material damage to the ship’s hull and a fire broke out on board, with the possibility of an oil leak in the surrounding waters, according to what was reported […]', 'تعرضت ناقلة النفط الخام العملاقة “السالمي” لاستهداف إيراني مباشر أثناء وجودها في منطقة المخطاف بميناء دبي في الإمارات. وقالت مؤسسة البترول الكويتية، الثلاثاء 31 آذار، إن “الناقلة كانت بكامل حمولتها”، مضيفة أن الاستهداف أسفر عن أضرار مادية في بدن السفينة واندلاع حريق على متنها، مع وجود احتمالية لتسرب نفطي في المياه المحيطة، وفق ما أوردت وكالة الأنباء الكويتية (كونا). وأكدت المؤسسة على عدم وقوع إصابات بشرية، مشيرة إلى أن العمل جار على تقييم الأضرار بشكل دقيق. وسبق أن أعلنت دولة الكويت، في 28 آذار الجاري، عن تعرض مطارها الدولي ل هجمات بطائرات مسيرة إيرانية، أسفرت عن أضرار في نظام الرادار الخاص بالمطار. وقال المتحدث الرسمي باسم الطيران المدني عبدالله الراجحي لوكالة الأنباء الكويتية “كونا” حينها، إن مطار الكويت الدولي تعرض لعدة هجمات بطائرات مسيرة دون تسجيل إصابات بشرية، مضيفاً أن الهجوم أسفر عن أضرار كبيرة في نظام الرادار الخاص بالمطار، مؤكدا Source: https://alikhbariah.com/%d8%a5%d9%8a%d8%b1%d8%a7%d9%86-%d8%aa%d8%b3%d8%aa%d9%87%d8%af%d9%81-%d9%86%d8%a7%d9%82%d9%84%d8%a9-%d9%86%d9%81%d8%b7-%d9%83%d9%88%d9%8a%d8%aa%d9%8a%d8%a9-%d9%81%d9%8a-%d9%85%d9%8a%d9%86%d8%a7%d8%a1/', 'The giant crude oil tanker “Al-Salmi” was subjected to direct Iranian targeting while it was in the anchorage area of ​​Dubai Port in the Emirates. The Kuwait Petroleum Corporation said, on Tuesday, March 31, that “the tanker was fully loaded,” adding that the targeting It resulted in material damage to the ship''s hull and a fire broke out on board, with the possibility of an oil leak in the surrounding waters, according to what Kuwait News Agency (KUNA) reported. The organization confirmed that there were no human casualties, noting that work is underway Accurately assess damages. The State of Kuwait previously announced, on March 28, that its international airport was subjected to attacks by Iranian drones, which resulted in damage to the airport’s radar system. The official spokesman for civil aviation, Abdullah, said Al-Rajhi told Kuwait News Agency (KUNA) at the time that Kuwait International Airport was subjected to several attacks by drones without recording human casualties, adding that the attack resulted in major damage to the airport’s radar system, confirming Source: https://alikhbariah.com/%d8%a5%d9%8a%d8%b1%d8%a7%d9%86-%d8%aa%d8%b3%d8%aa%d9%87%d8%af%d9%81-%d9%86%d8%a7%d9%82 %d9%84%d8%a9-%d9%86%d9%81%d8%b7-%d9%83%d9%88%d9%8a%d8%aa%d9%8a%d8%a9-%d9%81%d9%8a-%d9%85%d9%8a%d9%86%d8%a7%d8% a1/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Al-Salmi-oil-tanker.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 6 limit 1), '2026-03-30T23:56:53+03:00'::timestamptz, false, false, false, 156),
  ('غوتيريش يدين مقتل جندي أممي في جنوب لبنان ويطالب بمحاسبة المسؤولين', 'Guterres condemns the killing of a UN soldier in southern Lebanon and demands that those responsible be held accountable', 'أدان الأمين العام للأمم المتحدة أنطونيو غوتيريش، الإثنين 30 آذار، مقتل جندي من قوات حفظ السلام التابعة لـ”اليونيفيل” وإصابة آخر بجروح خطيرة، جراء حادث وقع داخل موقع القوة في بلدة الطيبة جنوب لبنان، في ظل تصاعد الأعمال العدائية بين إسرائيل و”حزب الله”. وفي بيان منسوب إلى المتحدث باسمه، أعرب غوتيريش عن تعازيه لجمهورية إندونيسيا وأسرة […]', 'On Monday, March 30, the Secretary-General of the United Nations, António Guterres, condemned the killing of a UNIFIL peacekeeping soldier and the serious injury of another, as a result of an incident that occurred inside the force’s site in the town of Taybeh, south of Lebanon, in light of the escalation of actions. Hostility between Israel and Hezbollah. In a statement attributed to his spokesman, Guterres expressed his condolences to the Republic of Indonesia and the family […]', 'أدان الأمين العام للأمم المتحدة أنطونيو غوتيريش، الإثنين 30 آذار، مقتل جندي من قوات حفظ السلام التابعة لـ”اليونيفيل” وإصابة آخر بجروح خطيرة، جراء حادث وقع داخل موقع القوة في بلدة الطيبة جنوب لبنان، في ظل تصاعد الأعمال العدائية بين إسرائيل و”حزب الله”. وفي بيان منسوب إلى المتحدث باسمه، أعرب غوتيريش عن تعازيه لجمهورية إندونيسيا وأسرة الجندي القتيل وزملائه، متمنياً الشفاء العاجل للمصاب. وأشار إلى أن الحادث يأتي ضمن سلسلة وقائع خطيرة طالت أمن وسلامة عناصر حفظ السلام خلال الـ48 ساعة الماضية. وجدد الأمين العام دعوته لجميع الأطراف إلى الالتزام بالقانون الدولي وضمان حماية موظفي الأمم المتحدة وممتلكاتها، مؤكداً أن استهداف قوات حفظ السلام يعد انتهاكاً جسيماً قد يرقى إلى جرائم حرب، ما يستوجب تحقيق المساءلة، وشدد على ضرورة خفض التصعيد والالتزام الكامل بقرار مجلس الأمن رقم 1701. من جانبها، أعلنت قوة “اليونيفيل” فتح تحقيق لتحديد ملابسات الحادث، موضحة أ Source: https://alikhbariah.com/%d8%ba%d9%88%d8%aa%d9%8a%d8%b1%d9%8a%d8%b4-%d9%8a%d8%af%d9%8a%d9%86-%d9%85%d9%82%d8%aa%d9%84-%d8%ac%d9%86%d8%af%d9%8a-%d8%a3%d9%85%d9%85%d9%8a-%d9%81%d9%8a-%d8%ac%d9%86%d9%88%d8%a8-%d9%84%d8%a8%d9%86/', 'On Monday, March 30, the Secretary-General of the United Nations, António Guterres, condemned the killing of a UNIFIL peacekeeping soldier and the serious injury of another, as a result of an incident that occurred inside the force’s site in the town of Taybeh, south of Lebanon, in light of the escalation of actions. Hostility between Israel and Hezbollah. In a statement attributed to his spokesman, Guterres expressed his condolences to the Republic of Indonesia, the family of the slain soldier and his colleagues, wishing the injured a speedy recovery. He pointed out that the incident is part of a series of serious incidents The security and safety of peacekeepers was affected during the past 48 hours. The Secretary-General renewed his call on all parties to abide by international law and ensure the protection of United Nations personnel and property, stressing that targeting peacekeeping forces is a violation. A serious matter that may amount to war crimes, which requires accountability. He stressed the need to reduce the escalation and fully adhere to Security Council Resolution No. 1701. For its part, UNIFIL announced the opening of an investigation to determine the circumstances of the incident, explaining a Source: https://alikhbariah.com/%d8%ba%d9%88%d8%aa%d9%8a%d8%b1%d9%8a%d8%b4-%d9%8a%d8%af%d9%8a%d9%86-%d9%85%d9%82%d8%aa %d9%84-%d8%ac%d9%86%d8%af%d9%8a-%d8%a3%d9%85%d9%85%d9%8a-%d9%81%d9%8a-%d8%ac%d9%86%d9%88%d8%a8-%d9%84%d8%a8%d9 %86/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Guterres-condemns-the-killing-of-a-UN-soldier-in-southern-Lebanon-and-demands-accountability-for-those-responsible.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 7 limit 1), '2026-03-30T16:36:02+03:00'::timestamptz, false, false, false, 155),
  ('مقتل 4 أشخاص في غارة إسرائيلية على بلدة شقرا جنوب لبنان', '4 people were killed in an Israeli raid on the town of Shaqra, south of Lebanon', 'قتل 4 أشخاص، الأحد 29 آذار، غارة جوية إسرائيلية استهدفت بلدة شقرا في الجنوب اللبناني. وبحسب وكالة الأنباء اللبنانية، فقد قصفت طائرات إسرائيلية البلدة بغارة جوية، أسفرت عن مقتل 4 أشخاص، بالإضافة إلى قصف مدفعي إسرائيلي طال البلدة ذاتها بالإضافة إلى بلدة طيرحرفا في قضاء صور. واستهدفت غارة إسرائيلية، في وقت سابق من اليوم، بلدة […]', 'Four people were killed on Sunday, March 29, by an Israeli air strike targeting the town of Shaqra in southern Lebanon. According to the Lebanese News Agency, Israeli aircraft bombed the town with an air strike, killing 4 people, in addition to Israeli artillery shelling. It affected the town itself, in addition to the town of Tair Harfa in the Tyre district. Earlier today, an Israeli raid targeted the town of […]', 'قتل 4 أشخاص، الأحد 29 آذار، غارة جوية إسرائيلية استهدفت بلدة شقرا في الجنوب اللبناني. وبحسب وكالة الأنباء اللبنانية، فقد قصفت طائرات إسرائيلية البلدة بغارة جوية، أسفرت عن مقتل 4 أشخاص، بالإضافة إلى قصف مدفعي إسرائيلي طال البلدة ذاتها بالإضافة إلى بلدة طيرحرفا في قضاء صور. واستهدفت غارة إسرائيلية، في وقت سابق من اليوم، بلدة الحنية جنوب لبنان ما أدى إلى سقوط 7 قتلى وعدد من الجرحى، في حين سقط قتيلان وثلاثة جرحى في أخرى على بلدة جويا. وقالت وكالة الأنباء اللبنانية إن الطيران الإسرائيلي أغار على منزل في بلدة دبعال وعلى أطراف باتوليه ودير قانون رأس العين، كما تعرضت بلدة البياضة ومدينة بنت جبيل لقصف مدفعي عنيف. وشنّ الطيران الإسرائيلي غارة على منزل في بلدة برج قلاويه، واستهدفت غارات أخرى بلدة الخيام وبلدة الجمالية شمال بعلبك. وتواصل إسرائيل حربها ضد “حزب الله” في لبنان، حيث تشن غارات يومية على الضاحية الجنوبية لبيروت ومناطق واسعة في الجنوب والبق Source: https://alikhbariah.com/%d9%85%d9%82%d8%aa%d9%84-4-%d8%a3%d8%b4%d8%ae%d8%a7%d8%b5-%d9%81%d9%8a-%d8%ba%d8%a7%d8%b1%d8%a9-%d8%a5%d8%b3%d8%b1%d8%a7%d8%a6%d9%8a%d9%84%d9%8a%d8%a9-%d8%b9%d9%84%d9%89-%d8%a8%d9%84%d8%af%d8%a9/', 'Four people were killed on Sunday, March 29, by an Israeli air strike targeting the town of Shaqra in southern Lebanon. According to the Lebanese News Agency, Israeli aircraft bombed the town with an air strike, killing 4 people, in addition to Israeli artillery shelling. It affected the town itself, in addition to the town of Tair Harfa in the Tyre district. Earlier today, an Israeli raid targeted the town of Al-Haniya, south of Lebanon, resulting in seven deaths and a number of injuries, while two deaths and three wounded occurred in another in the town of Joya. The Lebanese News Agency said that Israeli aircraft raided a house in the town of Debaal and on the outskirts of Batouleh and Deir Qanun Ras al-Ain, and the town of Bayyada and the city of Bint Jbeil were subjected to violent artillery shelling. Israeli aircraft launched a raid on a house in The town of Burj Qalawayh, and other raids targeted the town of Al-Khiyam and the town of Al-Jamaliyya, north of Baalbek. Israel continues its war against Hezbollah in Lebanon, launching daily raids on the southern suburbs of Beirut and large areas in the south and Al-Baq Source: https://alikhbariah.com/%d9%85%d9%82%d8%aa%d9%84-4-%d8%a3%d8%b4%d8%ae%d8%a7%d8%b5-%d9%81%d9%8a-%d8%ba%d8%a7%d /', 'https://alikhbariah.com/wp-content/uploads/2026/03/Four-people-killed-in-an-Israeli-airstrike-on-the-town-of-Shaqra-in-southern-Lebanon.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 8 limit 1), '2026-03-29T17:13:56+03:00'::timestamptz, false, false, false, 154),
  ('مقتل 10 أشخاص وإصابة 18 جراء غارات إسرائيلية على قطاع غزة', '10 people were killed and 18 injured as a result of Israeli raids on the Gaza Strip', 'أعلنت وزارة الصحة في غزة مقتل 10 أشخاص وإصابة 18 آخرين خلال 24 ساعة الماضية، جراء غارات جوية إسرائيلية على مناطق مختلفة من القطاع. ونقلت وكالة الأنباء الفلسطينية “وفا” عن مصادر طبية في قطاع غزة، الأحد 29 آذار، أن حصيلة عدوان الاحتلال الإسرائيلي على القطاع ارتفعت إلى 72 ألف و278 قتيلاً و172 ألف و013 مصاباً […]', 'The Ministry of Health in Gaza announced that 10 people were killed and 18 others were injured during the past 24 hours, as a result of Israeli air strikes on various areas of the Strip. The Palestinian News Agency “Wafa” quoted medical sources in the Gaza Strip, on Sunday, March 29, as saying that the death toll The Israeli occupation’s aggression against the Gaza Strip rose to 72,278 dead and 172,013 injured […]', 'أعلنت وزارة الصحة في غزة مقتل 10 أشخاص وإصابة 18 آخرين خلال 24 ساعة الماضية، جراء غارات جوية إسرائيلية على مناطق مختلفة من القطاع. ونقلت وكالة الأنباء الفلسطينية “وفا” عن مصادر طبية في قطاع غزة، الأحد 29 آذار، أن حصيلة عدوان الاحتلال الإسرائيلي على القطاع ارتفعت إلى 72 ألف و278 قتيلاً و172 ألف و013 مصاباً منذ بدء العدوان في السابع من تشرين الأول 2023. وأشارت إلى أن إجمالي القتلى منذ وقف إطلاق النار في 11 تشرين الأول الماضي ارتفع إلى 702، وإجمالي الإصابات إلى 1,913، فيما جرى انتشال 756 جثماناً. وأوضحت المصادر ذاتها أنه لا يزال عدد من الضحايا تحت الركام وفي الطرقات، في ظل عجز طواقم الإسعاف و الدفاع المدني عن الوصول إليهم حتى هذه اللحظة. Source: https://alikhbariah.com/%d9%85%d9%82%d8%aa%d9%84-10-%d8%a3%d8%b4%d8%ae%d8%a7%d8%b5-%d9%88%d8%a5%d8%b5%d8%a7%d8%a8%d8%a9-18-%d8%ac%d8%b1%d8%a7%d8%a1-%d8%ba%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a5%d8%b3%d8%b1%d8%a7%d8%a6%d9%8a%d9%84/', 'The Ministry of Health in Gaza announced that 10 people were killed and 18 others were injured during the past 24 hours, as a result of Israeli air strikes on various areas of the Strip. The Palestinian News Agency “Wafa” quoted medical sources in the Gaza Strip, on Sunday, March 29, as saying that the death toll The Israeli occupation’s aggression against the Gaza Strip has risen to 72,278 dead and 172,013 injured since the start of the aggression on October 7, 2023. It indicated that the total number of deaths since the ceasefire on October 11 last rose to 702, and the total number of injuries reached 1,913, while 756 bodies were recovered. The same sources explained that a number of victims are still under the rubble and on the roads, in light of the inability of ambulance and civil defense crews to reach them until this moment. Source: https://alikhbariah.com/%d9%85%d9%82%d8%aa%d9%84-10-%d8%a3%d8%b4%d8%ae%d8%a7%d8%b5-%d9%88%d8%a5%d8%b5%d8%a7%d8 %a8%d8%a9-18-%d8%ac%d8%b1%d8%a7%d8%a1-%d8%ba%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a5%d8%b3%d8%b1%d8%a7%d8%a6%d9%8a%d9%8 4/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Gaza.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 9 limit 1), '2026-03-29T10:52:39+03:00'::timestamptz, false, false, false, 153),
  ('قتلى وجرحى في غارات إسرائيلية متفرقة على لبنان', 'Dead and wounded in separate Israeli raids on Lebanon', 'استهدفت غارة إسرائيلية بلدة الحنية جنوب لبنان ما أدى إلى سقوط 7 قتلى وعدد من الجرحى، في حين سقط قتيلان وثلاثة جرحى في أخرى على بلدة جويا. وقالت وكالة الأنباء اللبنانية، الأحد 29 آذار، إن الطيران الإسرائيلي أغار على منزل في بلدة دبعال وعلى أطراف باتوليه ودير قانون رأس العين، كما تعرضت بلدة البياضة ومدينة […]', 'An Israeli raid targeted the town of Al-Haniya, south of Lebanon, resulting in seven deaths and a number of injuries, while two deaths and three injuries occurred in another in the town of Joya. The Lebanese News Agency said, on Sunday, March 29, that Israeli aircraft raided a house In the town of Debaal and on the outskirts of Batouleh and the Monastery of Qanun Ras al-Ain, the town of Al-Bayada and the city of […]', 'استهدفت غارة إسرائيلية بلدة الحنية جنوب لبنان ما أدى إلى سقوط 7 قتلى وعدد من الجرحى، في حين سقط قتيلان وثلاثة جرحى في أخرى على بلدة جويا. وقالت وكالة الأنباء اللبنانية، الأحد 29 آذار، إن الطيران الإسرائيلي أغار على منزل في بلدة دبعال وعلى أطراف باتوليه ودير قانون رأس العين، كما تعرضت بلدة البياضة ومدينة بنت جبيل لقصف مدفعي عنيف. وشنّ الطيران الإسرائيلي غارة على منزل في بلدة برج قلاويه، واستهدفت غارات أخرى بلدة الخيام وبلدة الجمالية شمال بعلبك. وأعلن الجيش الإسرائيلي، أمس، استهداف عشرات البنى التحتية التابعة لـ”حزب الله”، مشيراً إلى مقتل عنصرين بارزين في وحدة الاتصالات التابعة لـ”حزب الله”. من جهته، أعلن “حزب الله” في بيان نشرته وكالة الأنباء اللبنانية أنه استهدف ليل أمس السبت قاعدة عين شيمر التابعة للدفاع الجويّ الصاروخيّ وقاعدة رغفيم العسكرية بصواريخ نوعية، كما استهدف قاعدة بيريا التابعة لقيادة المنطقة الشمالية. وتواصل إسرائيل حربها ضد “ Source: https://alikhbariah.com/%d9%82%d8%aa%d9%84%d9%89-%d9%88%d8%ac%d8%b1%d8%ad%d9%89-%d9%81%d9%8a-%d8%ba%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a5%d8%b3%d8%b1%d8%a7%d8%a6%d9%8a%d9%84%d9%8a%d8%a9-%d9%85%d8%aa%d9%81%d8%b1%d9%82%d8%a9-%d8%b9/', 'An Israeli raid targeted the town of Al-Haniya, south of Lebanon, resulting in seven deaths and a number of injuries, while two deaths and three injuries occurred in another in the town of Joya. The Lebanese News Agency said, on Sunday, March 29, that Israeli aircraft raided a house In the town of Debaal and on the outskirts of Batouleh and Deir Qanun Ras al-Ain, the town of Bayada and the city of Bint Jbeil were also subjected to violent artillery shelling. Israeli aircraft launched a raid on a house in the town of Burj Qalawayh, and other raids targeted the town of Khiam and the town of Al-Jamaliyya. North of Baalbek. Yesterday, the Israeli army announced the targeting of dozens of Hezbollah infrastructure, noting the killing of two prominent members of Hezbollah’s communications unit. For its part, Hezbollah announced in a statement published by the news agency The Lebanese army said that last night, Saturday, it targeted the Ein Shemer base of the missile air defense and the Regvim military base with specific missiles, and it also targeted the Berea base of the Northern Command. Israel continues its war against “Source: https://alikhbariah.com/%d9%82%d8%aa%d9%84%d9%89-%d9%88%d8%ac%d8%b1%d8%ad%d9%89-%d9%81%d9%8a-%d8%ba%d8%a7%d8%b 1%d8%a7%d8%aa-%d8%a5%d8%b3%d8%b1%d8%a7%d8%a6%d9%8a%d9%84%d9%8a%d8%a9-%d9%85%d8%aa%d9%81%d8%b1%d9%82%d8%a9-%d8% b9/', 'https://alikhbariah.com/wp-content/uploads/2026/03/South-Lebanon-2.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 10 limit 1), '2026-03-29T08:00:51+03:00'::timestamptz, false, false, false, 152),
  ('القيادة المركزية الأمريكية: ضربنا أكثر من 11 ألف هدف في إيران', 'US Central Command: We struck more than 11,000 targets in Iran', 'أعلنت القيادة المركزية الأمريكية (سنتكوم)، السبت 28 آذار، أن قواتها ضربت أهدافاً تابعة للنظام الإيراني بهدف تفكيك جهازه الأمني، مع إعطاء الأولوية للمواقع التي تشكل تهديداً وشيكاً. وأوضحت القيادة المركزية في منشور لها على منصة “إكس” أن عدد الأهداف التي تم ضربها تجاوز 11 ألف هدف، مشيرة إلى أن الطلعات الجوية القتالية المنفذة بلغت هي […]', 'The US Central Command (Centcom) announced on Saturday, March 28, that its forces struck targets belonging to the Iranian regime with the aim of dismantling its security apparatus, giving priority to sites that pose an imminent threat. Central Command explained in its publication On the “X” platform, the number of targets that were struck exceeded 11 thousand targets, indicating that the combat sorties carried out amounted to […]', 'أعلنت القيادة المركزية الأمريكية (سنتكوم)، السبت 28 آذار، أن قواتها ضربت أهدافاً تابعة للنظام الإيراني بهدف تفكيك جهازه الأمني، مع إعطاء الأولوية للمواقع التي تشكل تهديداً وشيكاً. وأوضحت القيادة المركزية في منشور لها على منصة “إكس” أن عدد الأهداف التي تم ضربها تجاوز 11 ألف هدف، مشيرة إلى أن الطلعات الجوية القتالية المنفذة بلغت هي الأخرى أكثر من 11 ألف طلعة. وأكدت القيادة المركزية أن العمليات أسفرت عن تضرر أو تدمير أكثر من 150 سفينة إيرانية. وقال الرئيس الأمريكي دونالد ترامب، في وقت سابق السبت، إن القوات المسلحة الأمريكية سحقت المواقع النووية الإيرانية في عملية أطلقت عليها تسمية “مطرقة منتصف الليل”. وأضاف ترامب في كلمة له خلال منتدى استثماري في ميامي بولاية فلوريدا، أن الولايات المتحدة باتت قريبة من جعل منطقة الشرق الأوسط حرة من إرهاب وابتزاز إيران. وأشار إلى أن طهران لم يعد لديها سلاح جو أو دفاعات جوية، كما أعلن عن غرق البحرية الإيرانية ب Source: https://alikhbariah.com/%d8%a7%d9%84%d9%82%d9%8a%d8%a7%d8%af%d8%a9-%d8%a7%d9%84%d9%85%d8%b1%d9%83%d8%b2%d9%8a%d8%a9-%d8%a7%d9%84%d8%a3%d9%85%d8%b1%d9%8a%d9%83%d9%8a%d8%a9-%d8%b6%d8%b1%d8%a8%d9%86%d8%a7-%d8%a3%d9%83%d8%ab/', 'The US Central Command (Centcom) announced on Saturday, March 28, that its forces struck targets belonging to the Iranian regime with the aim of dismantling its security apparatus, giving priority to sites that pose an imminent threat. Central Command explained in its publication On the “X” platform, the number of targets that were struck exceeded 11,000 targets, indicating that the combat sorties carried out also amounted to more than 11,000 sorties. The Central Command confirmed that the operations resulted in the damage or destruction of more than 150 ships Iranian. US President Donald Trump said earlier on Saturday that the US armed forces had crushed Iranian nuclear sites in an operation dubbed “Midnight Hammer.” Trump added in his speech during an investment forum in: Miami, Florida, that the United States is close to making the Middle East region free from Iranian terrorism and blackmail. He pointed out that Tehran no longer has an air force or air defenses, and he also announced the sinking of the Iranian Navy. Source: https://alikhbariah.com/%d8%a7%d9%84%d9%82%d9%8a%d8%a7%d8%af%d8%a9-%d8%a7%d9%84%d9%85%d8%b1%d9%83%d8%b2%d9%8a% d8%a9-%d8%a7%d9%84%d8%a3%d9%85%d8%b1%d9%8a%d9%83%d9%8a%d8%a9-%d8%b6%d8%b1%d8%a8%d9%86%d8%a7-%d8%a3%d9%83%d8%ab /', 'https://alikhbariah.com/wp-content/uploads/2026/03/US-Central-Command-We-struck-more-than-11000-targets-in-Iran.jpg', (select id from public.categories where slug = 'news-arab-international' and type = 'news' limit 1), (select id from public.locations order by id offset 11 limit 1), '2026-03-28T20:04:58+03:00'::timestamptz, false, false, false, 151),
  ('سوريا تكتسح أفغانستان بخماسية وتتأهل إلى نهائيات كأس آسيا متصدرة بالعلامة الكاملة', 'Syria sweeps Afghanistan by five and qualifies for the Asian Cup finals with a perfect score', 'اختتم منتخبنا الوطني لكرة القدم مشواره في التصفيات الآسيوية المؤهلة إلى النهائيات بنتيجة كبيرة، بعدما حقق فوزاً عريضاً على منتخب أفغانستان بنتيجة خمسة أهداف مقابل هدف واحد، في المباراة التي جمعتهما على ملعب الأمير عبد الله الفيصل في مدينة جدة السعودية. وسجل اللاعب محمد الصلخدي هدف المنتخب الأول في الدقيقة الخامسة، وواصل المنتخب سيطرته، لكنه […]', 'Our national football team concluded its campaign in the Asian qualifiers for the finals with a great result, after achieving a broad victory over the Afghanistan national team with a score of five goals to one, in the match that brought them together at Prince Abdul Stadium. God Almighty in Jeddah, Saudi Arabia. Player Mohamed Al-Salkhadi scored the first team’s goal in the fifth minute, and the team continued its control, but […]', 'اختتم منتخبنا الوطني لكرة القدم مشواره في التصفيات الآسيوية المؤهلة إلى النهائيات بنتيجة كبيرة، بعدما حقق فوزاً عريضاً على منتخب أفغانستان بنتيجة خمسة أهداف مقابل هدف واحد، في المباراة التي جمعتهما على ملعب الأمير عبد الله الفيصل في مدينة جدة السعودية. وسجل اللاعب محمد الصلخدي هدف المنتخب الأول في الدقيقة الخامسة، وواصل المنتخب سيطرته، لكنه أهدر فرصة تعزيز النتيجة عندما أضاع محمود الأسود ركلة جزاء. ورغم الاستحواذ، نجح منتخب أفغانستان في مفاجأة أصحاب الأرض بهجمة وحيدة انتهت بتسجيل كابتن الفريق علي رضا هدف التعادل في الدقيقة 21 لينتهي الشوط الأول بالتعادل هدف لهدف. وفي الشوط الثاني، ظهر المنتخب الوطني بشكل مغاير، وتمكن كابتن الفريق محمد الحلاق من كسر التعادل بهدف في الدقيقة 53. وبعد دقيقة واحدة فقط من نزوله بديلاً لأنس دهان، عزز البديل محمد مصطفى النتيجة بهدف ثالث في الدقيقة 58. ونجح اللاعب محمد مصطفى في تسجيل هدفه الشخصي الثاني والرابع للم Source: https://alikhbariah.com/%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d8%aa%d9%83%d8%aa%d8%b3%d8%ad-%d8%a3%d9%81%d8%ba%d8%a7%d9%86%d8%b3%d8%aa%d8%a7%d9%86-%d8%a8%d8%ae%d9%85%d8%a7%d8%b3%d9%8a%d8%a9-%d9%88%d8%aa%d8%aa%d8%a3%d9%87%d9%84/', 'Our national football team concluded its campaign in the Asian qualifiers for the finals with a great result, after achieving a broad victory over the Afghanistan national team with a score of five goals to one, in the match that brought them together at Prince Abdul Stadium. God Almighty in Jeddah, Saudi Arabia. Player Mohamed Al-Salkhadi scored the first team''s goal in the fifth minute, and the team continued its control, but wasted the opportunity to increase the score when Mahmoud Al-Aswad missed a penalty kick. Despite the possession, the Afghanistan team succeeded The home team surprised the hosts with a single attack that ended with team captain Ali Reda scoring the equalizer in the 21st minute, ending the first half in a goal-to-goal draw. In the second half, the national team appeared in a different way, and the team captain, Mohamed Al-Hallaq, was able to break the score The equalizer was tied with a goal in the 53rd minute. Only one minute after coming on as a substitute for Anas Dahan, substitute Mohamed Mostafa increased the score with a third goal in the 58th minute. The player, Mohamed Mostafa, succeeded in scoring his second and fourth personal goal for the team. Source: https://alikhbariah.com/%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d8%aa%d9%83%d8%aa%d8%b3%d8%ad-%d8%a3%d9%81%d8%ba%d8%a7 %d9%86%d8%b3%d8%aa%d8%a7%d9%86-%d8%a8%d8%ae%d9%85%d8%a7%d8%b3%d9%8a%d8%a9-%d9%88%d8%aa%d8%aa%d8%a3%d9%87%d9%84 /', 'https://alikhbariah.com/wp-content/uploads/2026/03/Syrian-national-team-3.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 12 limit 1), '2026-03-31T19:28:48+03:00'::timestamptz, false, true, false, 150),
  ('فضية لسوريا في بطولة أنطاليا الدولية للمواي تاي', 'Silver for Syria in the Antalya International Muay Thai Championship', '​حقق لاعب منتخب سوريا لرياضة المواي تاي البطل سميان علي، الميدالية الفضية بوزن 71 كيلوغراماً، الأحد 29 آذار، في بطولة أنطاليا الدولية المفتوحة التي اختتمت منافساتها في تركيا بمشاركة واسعة من أبطال اللعبة على المستوى العربي والإقليمي والدولي. ​وأوضح رئيس اتحاد اللعبة حسان العلي، أن هذه الميدالية هي ثمرة أول مشاركة لرياضة المواي تاي السورية […]', '​Syrian Muay Thai national team player, champion Sumian Ali, won the silver medal with a weight of 71 kilograms, Sunday, March 29, in the Antalya International Open Championship, which concluded its competitions in Turkey with wide participation from the champions of the game at the level. Arab, regional and international. The head of the Federation, Hassan Al-Ali, explained that this medal is the result of the first participation in the sport of Syrian Muay Thai […]', '​حقق لاعب منتخب سوريا لرياضة المواي تاي البطل سميان علي، الميدالية الفضية بوزن 71 كيلوغراماً، الأحد 29 آذار، في بطولة أنطاليا الدولية المفتوحة التي اختتمت منافساتها في تركيا بمشاركة واسعة من أبطال اللعبة على المستوى العربي والإقليمي والدولي. ​وأوضح رئيس ا تحاد اللعبة حسان العلي، أن هذه الميدالية هي ثمرة أول مشاركة لرياضة المواي تاي السورية على الصعيد الخارجي لعام 2026، وجاء إنجاز البطل سميان ليؤكد التطور الواضح للمستوى الفني للاعبين بحسب ما نشرت جريدة الاتحاد الرياضي العام. ​وأشار العلي إلى أن هذه البطولة تعد من أهم البطولات التحضيرية قبل الاستحقاقات التي سيقيمها الاتحاد الدولي خلال هذا العام، حيث تندرج المشاركة ضمن خططه التحضيرية لتطوير أداء المنتخبات الوطنية. ​وأضاف أن خطة الاتحاد على الصعيد الخارجي تتضمن الكثير من المشاركات، متمنياً تحقيق ميداليات ومراكز أولى لأبطال وبطلات اللعبة في حال توفرت الظروف المناسبة للمشاركة للمنتخبات الوطنية  Source: https://alikhbariah.com/%d9%81%d8%b6%d9%8a%d8%a9-%d9%84%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d9%81%d9%8a-%d8%a8%d8%b7%d9%88%d9%84%d8%a9-%d8%a3%d9%86%d8%b7%d8%a7%d9%84%d9%8a%d8%a7-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a%d8%a9-%d9%84/', '​Syrian Muay Thai national team player, champion Sumian Ali, won the silver medal with a weight of 71 kilograms, Sunday, March 29, in the Antalya International Open Championship, which concluded its competitions in Turkey with wide participation from the champions of the game at the level. Arab, regional and international. ​The President of the Federation, Hassan Al-Ali, explained that this medal is the result of the first participation of the Syrian Muay Thai sport on the foreign level in the year 2026, and the achievement of the champion Samian came to confirm the clear development of the technical level. For players, according to what was published in the General Sports Federation newspaper. Al-Ali pointed out that this tournament is one of the most important preparatory tournaments before the competitions that the International Federation will hold during this year, as participation falls within its preparatory plans to develop Performance of national teams. He added that the Federation’s plan at the external level includes many participations, hoping to achieve medals and first places for the champions and heroines of the game if the appropriate conditions are available for the national teams to participate. Source: https://alikhbariah.com/%d9%81%d8%b6%d9%8a%d8%a9-%d9%84%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d9%81%d9%8a-%d8%a8%d8%b 7%d9%88%d9%84%d8%a9-%d8%a3%d9%86%d8%b7%d8%a7%d9%84%d9%8a%d8%a7-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a%d8%a9-%d9% 84/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Antalya-International-Open-Championship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 13 limit 1), '2026-03-30T02:44:01+03:00'::timestamptz, false, true, false, 149),
  ('حمص.. خطة خمسية لتأهيل المدينة الرياضية وإنشاء منشآت جديدة', 'Homs.. A five-year plan to rehabilitate the sports city and establish new facilities', 'أكد وزير الرياضة والشباب محمد سامح الحامض أن الوزارة تعمل على تأهيل المدينة الرياضية في حمص ضمن خطة تمتد لخمس سنوات. وتشمل الخطة إنشاء صالات متعددة الاستخدامات وملعباً رئيسياً ومرافق رياضية متكاملة، بالتوازي مع إطلاق أعمال صيانة في عدد من الملاعب، حسب وكالة سانا. وأوضح الحامض خلال جولة ميدانية في المحافظة برفقة محافظ حمص عبد […]', 'Minister of Sports and Youth, Muhammad Sameh Al-Hamid, confirmed that the ministry is working to rehabilitate the sports city in Homs within a five-year plan. The plan includes constructing multi-use halls, a main stadium, and integrated sports facilities, in parallel with the launch Maintenance work in a number of stadiums, according to SANA. Al-Hamid explained during a field tour in the governorate, accompanied by the Governor of Homs, Abdel […]', 'أكد وزير الرياضة والشباب محمد سامح الحامض أن الوزارة تعمل على تأهيل المدينة الرياضية في حمص ضمن خطة تمتد لخمس سنوات. وتشمل الخطة إنشاء صالات متعددة الاستخدامات وملعباً رئيسياً ومرافق رياضية متكاملة، بالتوازي مع إطلاق أعمال صيانة في عدد من الملاعب، حسب وكالة سانا . وأوضح الحامض خلال جولة ميدانية في المحافظة برفقة محافظ حمص عبد الرحمن الأعمى، أن المشروع يتضمن إنشاء ثلاث صالات لألعاب كرة اليد والطائرة والسلة، إضافة إلى ملاعب تدريبية ومسبح دولي وملاعب تنس. وأشار إلى أن التنفيذ سيبدأ وفق أولويات مدروسة عبر إنشاء صالتين وملعب تدريبي لكرة القدم، مع إعداد الدراسات اللازمة بالتنسيق مع المحافظة. وأضاف أن أعمال صيانة وترميم ملعب الساروت انطلقت بشكل كامل على نفقة الوزارة، إلى جانب تنفيذ أعمال صيانة لمرافق ومدرجات ملعب خالد بن الوليد. ولفت الحامض إلى أن سياسة الوزارة تركز على دعم الأندية وتخفيف الأعباء المالية عنها، من خلال إلغاء تكاليف التحكيم، وتخصي Source: https://alikhbariah.com/%d8%ad%d9%85%d8%b5-%d8%ae%d8%b7%d8%a9-%d8%ae%d9%85%d8%b3%d9%8a%d8%a9-%d9%84%d8%aa%d8%a3%d9%87%d9%8a%d9%84-%d8%a7%d9%84%d9%85%d8%af%d9%8a%d9%86%d8%a9-%d8%a7%d9%84%d8%b1%d9%8a%d8%a7%d8%b6%d9%8a%d8%a9/', 'Minister of Sports and Youth, Muhammad Sameh Al-Hamid, confirmed that the ministry is working to rehabilitate the sports city in Homs within a five-year plan. The plan includes constructing multi-use halls, a main stadium, and integrated sports facilities, in parallel with the launch Maintenance work in a number of stadiums, according to SANA. Al-Hamid explained during a field tour in the governorate, accompanied by the Governor of Homs, Abdul Rahman Al-Ama, that the project includes the establishment of three halls for handball, volleyball, and basketball, in addition to training fields. An international swimming pool and tennis courts. He pointed out that implementation will begin according to well-studied priorities by establishing two halls and a football training field, while preparing the necessary studies in coordination with the governorate. He added that the maintenance and restoration work on Al-Sarout Stadium has fully begun At the Ministry’s expense, in addition to carrying out maintenance work for the facilities and stands of Khaled Bin Al Waleed Stadium. Al-Hamed pointed out that the ministry’s policy focuses on supporting clubs and reducing their financial burdens, by eliminating arbitration costs, and singling out Source: https://alikhbariah.com/%d8%ad%d9%85%d8%b5-%d8%ae%d8%b7%d8%a9-%d8%ae%d9%85%d8%b3%d9%8a%d8%a9-%d9%84%d8%aa%d8%a 3%d9%87%d9%8a%d9%84-%d8%a7%d9%84%d9%85%d8%af%d9%8a%d9%86%d8%a9-%d8%a7%d9%84%d8%b1%d9%8a%d8%a7%d8%b6%d9%8a%d8%a 9/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Sports-visit-to-Homs.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 0 limit 1), '2026-03-29T22:00:38+03:00'::timestamptz, false, false, false, 148),
  ('اختتام بطولة دمشق الدولية الأولى لفروسية قفز الحواجز بتأهل ثلاثة فرسان إلى قطر', 'The first Damascus International Show Jumping Equestrian Championship concluded with three riders qualifying for Qatar', 'اختتمت بطولة دمشق الدولية التأهيلية الأولى لفروسية قفز الحواجز، وذلك بعد منافسات استمرت يومين في نادي الفروسية المركزي بالديماس بريف دمشق. وبحسب ما نشرت وكالة “سانا“، الأحد 1 آذار، أسفرت النتائج النهائية عن تأهل ثلاثة فرسان إلى بطولة قطر الدولية المقررة في نيسان القادم بعد تحقيقهم النقاط التأهيلية المطلوبة. وذكرت الوكالة أن الفرسان المتأهلين هم […]', 'The first Damascus International Equestrian Qualifying Championship for show jumping was concluded after two days of competitions at the Central Equestrian Club in Dimas in the Damascus countryside. According to what was published by “SANA” agency, on Sunday, March 1, the final results resulted in three qualifications Knights will advance to the Qatar International Championship scheduled for next April after achieving the required qualifying points. The agency stated that the qualified riders are […]', 'اختتمت بطولة دمشق الدولية التأهيلية الأولى لفروسية قفز الحواجز، وذلك بعد منافسات استمرت يومين في نادي الفروسية المركزي بالديماس بريف دمشق. وبحسب ما نشرت وكالة “ سانا “، الأحد 1 آذار، أسفرت النتائج النهائية عن تأهل ثلاثة فرسان إلى بطولة قطر الدولية المقررة في نيسان القادم بعد تحقيقهم النقاط التأهيلية المطلوبة. وذكرت الوكالة أن الفرسان المتأهلين هم زيد أكريم بفئة الأطفال وجوري بحبوح بفئة جونيور ومحمد أبو زيد بفئة يونغ، حيث حصل كل منهم على 11 نقطة في ختام منافسات هذه البطولة. وأقيمت منافسات اليوم الثاني والختامي لبطولة دمشق الدولية التأهيلية الأولى على شوطين، الأول أصلي والثاني جولة للتمايز لكل فئة من الفئات الثلاث على حدة، علماً أن ارتفاع الحواجز في الجولة النهائية بلغ 115 سم لفئة الأطفال و125 سم لفئة جونيور و135 سم لفئة يونغ. وتنظم منافسات بطولة دمشق الدولية التأهيلية الثانية يومي الجمعة والسبت القادمين، على أرض نادي الفروسية المركزي بالدي Source: https://alikhbariah.com/%d8%a7%d8%ae%d8%aa%d8%aa%d8%a7%d9%85-%d8%a8%d8%b7%d9%88%d9%84%d8%a9-%d8%af%d9%85%d8%b4%d9%82-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a%d8%a9-%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%89-%d9%84%d9%81%d8%b1%d9%88/', 'The first Damascus International Equestrian Qualifying Championship for show jumping was concluded after two days of competitions at the Central Equestrian Club in Dimas in the Damascus countryside. According to what was published by “SANA” agency, on Sunday, March 1, the final results resulted in three qualifications Knights will advance to the Qatar International Championship scheduled for next April after achieving the required qualifying points. The agency stated that the qualified riders were Zaid Akram in the children’s category, Juri Bahbouh in the junior category, and Muhammad Abu Zaid in the young category, where each of them won 11 points at the end of this tournament. The competitions of the second and final day of the first Damascus International Qualifying Championship were held in two rounds, the first an original round and the second a differentiation round for each of the three categories separately, noting that the height of the barriers in The final round reached 115 cm for the children''s category, 125 cm for the junior category, and 135 cm for the young category. The second Damascus International Qualifying Championship competitions will be held next Friday and Saturday, on the grounds of the Central Equestrian Club in Baldi. Source: https://alikhbariah.com/%d8%a7%d8%ae%d8%aa%d8%aa%d8%a7%d9%85-%d8%a8%d8%b7%d9%88%d9%84%d8%a9-%d8%af%d9%85%d8%b4 %d9%82-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a%d8%a9-%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%89-%d9%84%d9%81%d8%b1%d9%8 8/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Damascus-Equestrian-Championship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 1 limit 1), '2026-03-01T10:35:34+03:00'::timestamptz, false, false, false, 147),
  ('تأجيل مباراة منتخبنا الوطني وإيران في تصفيات كأس العالم لكرة السلة', 'The match between our national team and Iran in the Basketball World Cup qualifiers was postponed', 'أعلن الاتحاد العربي السوري لكرة السلة تأجيل مباراة منتخبنا الوطني أمام نظيره الإيراني والتي كانت مقررة في 2 آذار المقبل في العاصمة اللبنانية بيروت، ضمن منافسات التصفيات الآسيوية المؤهلة لكأس العالم 2027. وأوضح الاتحاد في بيان نشره عبر معرفاته الرسمية السبت 28 شباط، أن تأجيل المباراة يأتي بناءً على قرار الاتحاد الدولي لكرة السلة لأسباب […]', 'The Syrian Arab Basketball Federation announced the postponement of our national team’s match against its Iranian counterpart, which was scheduled for next March 2 in the Lebanese capital, Beirut, as part of the Asian qualifiers for the 2027 World Cup. The Federation explained In a statement published through its official handles on Saturday, February 28, the postponement of the match comes based on the decision of the International Basketball Federation for reasons […]', 'أعلن الاتحاد العربي السوري لكرة السلة تأجيل مباراة منتخبنا الوطني أمام نظيره الإيراني والتي كانت مقررة في 2 آذار المقبل في العاصمة اللبنانية بيروت، ضمن منافسات التصفيات الآسيوية المؤهلة لكأس العالم 2027. وأوضح الاتحاد في بيان نشره عبر معرفاته الرسمية السبت 28 شباط، أن تأجيل المباراة يأتي بناءً على قرار الاتحاد الدولي لكرة السلة لأسباب تتعلق بسلامة وأمن المنتخبات المشاركة وضمان سلامة المنافسات. وذكر أن المباراة ستقام في نافذة التصفيات القادمة (Window 3) على أن يتم الإعلان عن الموعد الجديد بشكل رسمي لاحقاً من قبل الاتحاد الدولي لكرة السلة. وأكد الاتحاد استمرار المنتخب الوطني في استعداداته بأفضل شكل مع الجاهزية لتمثيل سوريا بأفضل صورة في الاستحقاقات القادمة. وكان منتخبنا الوطني قد فاز أمس الجمعة على نظيره العراقي بنتيجة 78/70، ضمن منافسات النافذة الثانية. Source: https://alikhbariah.com/%d8%aa%d8%a3%d8%ac%d9%8a%d9%84-%d9%85%d8%a8%d8%a7%d8%b1%d8%a7%d8%a9-%d9%85%d9%86%d8%aa%d8%ae%d8%a8%d9%86%d8%a7-%d8%a7%d9%84%d9%88%d8%b7%d9%86%d9%8a-%d9%88%d8%a5%d9%8a%d8%b1%d8%a7%d9%86-%d9%81%d9%8a/', 'The Syrian Arab Basketball Federation announced the postponement of our national team’s match against its Iranian counterpart, which was scheduled for next March 2 in the Lebanese capital, Beirut, as part of the Asian qualifiers for the 2027 World Cup. The Federation explained In a statement published on its official handles on Saturday, February 28, the postponement of the match comes based on the decision of the International Basketball Federation for reasons related to the safety and security of the participating teams and ensuring the integrity of the competitions. He stated that the match will be held during the qualifying window Next (Window 3) the new date will be officially announced later by the International Basketball Federation. The Federation confirmed that the national team will continue its preparations in the best possible way, with its readiness to represent Syria in the best way in the competitions Coming. Our national team won yesterday, Friday, over its Iraqi counterpart, with a score of 78/70, in the second window competitions. Source: https://alikhbariah.com/%d8%aa%d8%a3%d8%ac%d9%8a%d9%84-%d9%85%d8%a8%d8%a7%d8%b1%d8%a7%d8%a9-%d9%85%d9%86%d8%aa %d8%ae%d8%a8%d9%86%d8%a7-%d8%a7%d9%84%d9%88%d8%b7%d9%86%d9%8a-%d9%88%d8%a5%d9%8a%d8%b1%d8%a7%d9%86-%d9%81%d9%8 a/', 'https://alikhbariah.com/wp-content/uploads/2026/02/The-match-between-our-national-team-and-Iran-in-the-Basketball-World-Cup-qualifiers-has-been-postponed.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 2 limit 1), '2026-02-28T19:53:47+03:00'::timestamptz, false, false, false, 146),
  ('الاتحاد السوري لكرة القدم يصدر حزمة عقوبات بحق عدد من أندية الدوري الممتاز', 'The Syrian Football Association issues a package of sanctions against a number of Premier League clubs', 'أصدرت لجنة الانضباط والأخلاق في الاتحاد السوري لكرة القدم، الإثنين 23 شباط، حزمة من العقوبات والغرامات المالية بحق عدد من الأندية والإداريين عقب انتهاء الأسبوع التاسع من الدوري الممتاز. وشملت القرارات تغريم نادي حطين مبلغ 3 ملايين ليرة سورية لقيام جمهوره بشتم فريق تشرين ومدرب وحارس نادي الفتوة، إضافة إلى تغريمه مليوني ليرة لإشعال الشماريخ […]', 'On Monday, February 23, the Disciplinary and Ethics Committee of the Syrian Football Association issued a package of penalties and financial fines against a number of clubs and administrators following the end of the ninth week of the Premier League. The decisions included fining Hattin Club An amount of 3 million Syrian pounds for his fans insulting the Tishreen team and the coach and goalkeeper of Al-Fatwa Club, in addition to a fine of two million Syrian pounds for lighting the candles […]', 'أصدرت لجنة الانضباط والأخلاق في الاتحاد السوري لكرة القدم، الإثنين 23 شباط، حزمة من العقوبات والغرامات المالية بحق عدد من الأندية والإداريين عقب انتهاء الأسبوع التاسع من الدوري الممتاز. وشملت القرارات تغريم نادي حطين مبلغ 3 ملايين ليرة سورية لقيام جمهوره بشتم فريق تشرين ومدرب وحارس نادي الفتوة، إضافة إلى تغريمه مليوني ليرة لإشعال الشماريخ ورميها داخل أرض الملعب. وغرمت اللجنة نادي الفتوة مليوني ليرة لاستنكافه عن إكمال مباراته مع حطين لمدة 14 دقيقة، وقررت إيقاف مساعد مدرب الرجال مرهف دحبور ثلاث مباريات رسمية مع غرامة مليون ليرة، بعد ثبوت تحريضه فريقه على الاستنكاف. وغرمت اللجنة نادي جبلة 6 ملايين ليرة لشتم جمهوره الحكام، مع مضاعفة العقوبة لتكرار المخالفة، إضافة إلى غرامة قدرها مليون وخمسمائة ألف ليرة لرمي العبوات الفارغة على الحكام. وفي السياق، أقرت اللجنة توقيف رئيس نادي أمية الرياضي سامر عادل طرشة كردي عن مرافقة فريقه ثلاث مباريات متتالية Source: https://alikhbariah.com/%d8%a7%d9%84%d8%a7%d8%aa%d8%ad%d8%a7%d8%af-%d8%a7%d9%84%d8%b3%d9%88%d8%b1%d9%8a-%d9%84%d9%83%d8%b1%d8%a9-%d8%a7%d9%84%d9%82%d8%af%d9%85-%d9%8a%d8%b5%d8%af%d8%b1-%d8%ad%d8%b2%d9%85%d8%a9-%d8%b9%d9%82/', 'On Monday, February 23, the Disciplinary and Ethics Committee of the Syrian Football Association issued a package of penalties and financial fines against a number of clubs and administrators following the end of the ninth week of the Premier League. The decisions included fining Hattin Club An amount of 3 million Syrian pounds for his fans insulting the Tishreen team and the coach and goalkeeper of Al-Fatwa Club, in addition to a fine of 2 million Syrian pounds for lighting candles and throwing them on the field. The committee fined Al-Fatwa Club two million liras for refusing to complete its match with Hattin For 14 minutes, it was decided to suspend the men’s assistant coach, Murhaf Dahbour, for three official matches and fine him one million liras, after it was proven that he incited his team to protest. The committee fined the Jableh Club 6 million liras for insulting its fans and the referees, with the penalty doubled for repetition The violation is in addition to a fine of one million five hundred thousand liras for throwing empty containers at the referees. In this context, the committee approved the arrest of the president of the Umayyad Sports Club, Samer Adel Tarsha Kurdi, for accompanying his team to three consecutive matches. Source: https://alikhbariah.com/%d8%a7%d9%84%d8%a7%d8%aa%d8%ad%d8%a7%d8%af-%d8%a7%d9%84%d8%b3%d9%88%d8%b1%d9%8a-%d9%84 %d9%83%d8%b1%d8%a9-%d8%a7%d9%84%d9%82%d8%af%d9%85-%d9%8a%d8%b5%d8%af%d8%b1-%d8%ad%d8%b2%d9%85%d8%a9-%d8%b9%d9% 82/', 'https://alikhbariah.com/wp-content/uploads/2026/02/Syrian-Football-Federation.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 3 limit 1), '2026-02-23T15:05:39+03:00'::timestamptz, false, false, false, 145),
  ('وزير الرياضة يخصص مكافأة 6 ملايين ليرة للجمهور الأكثر التزاماً بالروح الرياضية', 'The Minister of Sports allocates a reward of 6 million liras to the audience most committed to sportsmanship', 'أعلن وزير الرياضة والشباب محمد سامح حامض، الأحد 22 شباط، عن تخصيص مكافأة أسبوعية بقيمة 6 ملايين ليرة سورية تحت عنوان “أفضل جمهور”، تمنح للجماهير الأكثر التزاماً بالروح الرياضية والتشجيع الحضاري في مباريات الدوري المحلي لكرة القدم وكرة السلة. ويأتي هذا القرار في إطار سعي الوزارة لتعزيز ثقافة التشجيع الإيجابي، والحد من المظاهر السلبية في […]', 'On Sunday, February 22, the Minister of Sports and Youth, Muhammad Sameh Hamid, announced the allocation of a weekly reward worth 6 million Syrian pounds under the title “Best Fans,” given to the fans most committed to the spirit of sportsmanship and civilized encouragement in local league matches. For football and basketball. This decision comes within the framework of the Ministry’s endeavor to promote a culture of positive encouragement and reduce negative aspects in [...]', 'أعلن وزير الرياضة والشباب محمد سامح حامض، الأحد 22 شباط، عن تخصيص مكافأة أسبوعية بقيمة 6 ملايين ليرة سورية تحت عنوان “أفضل جمهور”، تمنح للجماهير الأكثر التزاماً بالروح الرياضية والتشجيع الحضاري في مباريات الدوري المحلي لكرة القدم وكرة السلة. ويأتي هذا القرار في إطار سعي الوزارة لتعزيز ثقافة التشجيع الإيجابي، والحد من المظاهر السلبية في المدرّجات، وتحفيز الجماهير على خلق أجواء رياضية داعمة للعبة واللاعبين، والمساهمة في إنجاح مسابقات الدوري. وأوضحت الوزارة، في بيان لها، أن عملية اختيار الجمهور الفائز ستتم بشكل أسبوعي من قبل الاتحادين السوري لكرة القدم وكرة السلة، وفق معايير محددة ترتكز على الالتزام بالسلوك الحضاري، والانضباط العام، وعدم ارتكاب المخالفات داخل الملاعب والصالات الرياضية. وأكدت الوزارة أن هذه الخطوة تهدف إلى ترسيخ قيم المسؤولية المجتمعية لدى الجماهير، والارتقاء بالمشهد الرياضي بما يعكس الصورة الحضارية للرياضة في سوريا. وجاء قرا Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%b1%d9%8a%d8%a7%d8%b6%d8%a9-%d9%8a%d8%ae%d8%b5%d8%b5-%d9%85%d9%83%d8%a7%d9%81%d8%a3%d8%a9-6-%d9%85%d9%84%d8%a7%d9%8a%d9%8a%d9%86-%d9%84%d9%8a%d8%b1%d8%a9-%d9%84/', 'On Sunday, February 22, the Minister of Sports and Youth, Muhammad Sameh Hamid, announced the allocation of a weekly reward worth 6 million Syrian pounds under the title “Best Fans,” given to the fans most committed to the spirit of sportsmanship and civilized encouragement in local league matches. For football and basketball. This decision comes within the framework of the Ministry’s endeavor to promote a culture of positive encouragement, reduce negative aspects in the stands, motivate fans to create a sports atmosphere supportive of the game and the players, and contribute to the success of competitions. League. The Ministry explained, in a statement, that the process of selecting the winning audience will take place on a weekly basis by the Syrian Football and Basketball Federations, according to specific criteria based on commitment to civilized behavior, public discipline, and not committing crimes. Violations inside stadiums and gyms. The Ministry confirmed that this step aims to consolidate the values ​​of social responsibility among the masses and improve the sports scene in a way that reflects the civilized image of sports in Syria. He came and read Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%b1%d9%8a%d8%a7%d8%b6%d8%a9-%d9%8a%d8%ae%d8%b5 %d8%b5-%d9%85%d9%83%d8%a7%d9%81%d8%a3%d8%a9-6-%d9%85%d9%84%d8%a7%d9%8a%d9%8a%d9%86-%d9%84%d9%8a%d8%b1%d8%a9-%d 9%84/', 'https://alikhbariah.com/wp-content/uploads/2026/02/The-Minister-of-Sports-allocates-a-reward-of-6-million-lira-for-the-fans-most-committed-to-sportsmanship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 4 limit 1), '2026-02-22T17:35:59+03:00'::timestamptz, false, false, false, 144),
  ('نادي محافظة دمشق يحقق إنجازاً رياضياً جديداً في بطولة الجمهورية للكاراتيه', 'Damascus Governorate Club achieves a new sporting achievement in the Republic Karate Championship', 'تمكن لاعبو نادي محافظة دمشق من حصد 18 ميدالية ملونة، خلال مشاركتهم في بطولة الجمهورية للأندية والبيوتات الرياضية للكاراتيه، التي أقيمت منافساتها في العاصمة دمشق بمشاركة واسعة ضمت 600 لاعب ولاعبة يمثلون 35 نادياً من مختلف المحافظات. وتشير النتائج التي أعلنتها مديرية الأنشطة الرياضية، إلى تتويج أبطال النادي بـ7 ميداليات ذهبية، وميدالية فضية واحدة، و10 […]', 'Damascus Governorate Club players were able to win 18 colored medals, during their participation in the Republic Championship for Karate Clubs and Houses, whose competitions were held in the capital, Damascus, with wide participation that included 600 male and female players representing 35 clubs from Various governorates. The results announced by the Sports Activities Directorate indicate that the club’s champions were crowned with 7 gold medals, one silver medal, and 10 […]', 'تمكن لاعبو نادي محافظة دمشق من حصد 18 ميدالية ملونة، خلال مشاركتهم في بطولة الجمهورية للأندية والبيوتات الرياضية للكاراتيه، التي أقيمت منافساتها في العاصمة دمشق بمشاركة واسعة ضمت 600 لاعب ولاعبة يمثلون 35 نادياً من مختلف المحافظات. وتشير النتائج التي أعلنتها مديرية الأنشطة الرياضية، إلى تتويج أبطال النادي بـ7 ميداليات ذهبية، وميدالية فضية واحدة، و10 ميداليات برونزية، ضمن الفئات العمرية (-14 / -16 / -18 / -21 / +18)، ليحقق بذلك المركز الثاني في الترتيب العام للبطولة. وفي أجواء احتفالية تعبيراً عن تقدير هذا الإنجاز، جرى تتويج اللاعبين بجوائز عينية ومادية برعاية محافظ دمشق ماهر مروان أدلبي، دعماً للمواهب الرياضية وتحفيزاً لمزيد من التألق والنجاح. Source: https://alikhbariah.com/%d9%86%d8%a7%d8%af%d9%8a-%d9%85%d8%ad%d8%a7%d9%81%d8%b8%d8%a9-%d8%af%d9%85%d8%b4%d9%82-%d9%8a%d8%ad%d9%82%d9%82-%d8%a5%d9%86%d8%ac%d8%a7%d8%b2%d8%a7%d9%8b-%d8%b1%d9%8a%d8%a7%d8%b6%d9%8a%d8%a7%d9%8b/', 'Damascus Governorate Club players were able to win 18 colored medals, during their participation in the Republic Championship for Karate Clubs and Houses, whose competitions were held in the capital, Damascus, with wide participation that included 600 male and female players representing 35 clubs from Various governorates. The results announced by the Sports Activities Directorate indicate that the club’s champions were crowned with 7 gold medals, one silver medal, and 10 bronze medals, within the age groups (-14 / -16 / -18 / -21 / +18), thus achieving Second place in the overall championship standings. In a festive atmosphere to express appreciation for this achievement, the players were crowned with in-kind and material prizes under the patronage of the Governor of Damascus, Maher Marwan Adlabi, to support sports talent and encourage more brilliance. And success. Source: https://alikhbariah.com/%d9%86%d8%a7%d8%af%d9%8a-%d9%85%d8%ad%d8%a7%d9%81%d8%b8%d8%a9-%d8%af%d9%85%d8 %b4%d9%82-%d9%8a%d8%ad%d9%82%d9%82-%d8%a5%d9%86%d8%ac%d8%a7%d8%b2%d8%a7%d9%8b-%d8%b1%d9%8a%d8%a7%d8%b6 %d9%8a%d8%a7%d9%8b/', 'https://alikhbariah.com/wp-content/uploads/2026/02/Damascus-Governorate-Karate-Club.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 5 limit 1), '2026-02-21T12:30:34+03:00'::timestamptz, false, false, false, 143),
  ('منتخب حلب بطلاً لبطولة سوريا الأولى لكرة القدم المصغرة', 'The Aleppo national team is champion of the first Syrian mini-football championship', 'توج منتخب حلب بطلاً لبطولة سوريا الأولى لكرة القدم المصغرة بعد فوزه على منتخب درعا بركلات الترجيح بنتيجة 3–2، في المباراة النهائية التي أقيمت الإثنين 16 شباط، عقب انتهاء الوقت الأصلي بالتعادل 3–3. وشهدت المباراة تنافساً قوياً وتبادلاً في تسجيل الأهداف بين المنتخبين خلال الوقت الأصلي، قبل أن تتجه إلى ركلات الترجيح لحسم النتيجة، حسب […]', 'The Aleppo national team was crowned champion of the first Syrian mini-football championship after defeating the Daraa national team on penalties, 3-2, in the final match that was held on Monday, February 16, after regular time ended in a 3-3 draw. The match witnessed competition There was a strong exchange of goals between the two teams during regular time, before heading to penalty kicks to settle the result, according to […]', 'توج منتخب حلب بطلاً لبطولة سوريا الأولى لكرة القدم المصغرة بعد فوزه على منتخب درعا بركلات الترجيح بنتيجة 3–2، في المباراة النهائية التي أقيمت الإثنين 16 شباط، عقب انتهاء الوقت الأصلي بالتعادل 3–3. وشهدت المباراة تنافساً قوياً وتبادلاً في تسجيل الأهداف بين المنتخبين خلال الوقت الأصلي، قبل أن تتجه إلى ركلات الترجيح لحسم النتيجة، حسب ما نشرته وزارة الرياضة والشباب عبر معرفاتها الرسمية. وبدأ منتخب حلب اللقاء بالتقدم بثلاثة أهداف مقابل هدف، قبل أن تتعدل الموازين إثر طرد حارس مرماه في الدقيقة 70 من مجريات المباراة. واستغل منتخب درعا النقص العددي وقلص الفارق، قبل أن يدرك التعادل في الثواني الأخيرة من الوقت بدل الضائع، ليلجأ الفريقان إلى ركلات الترجيح التي حسمها منتخب حلب لصالحه بنتيجة (3-2). وأضاف منتخب حلب إلى الإنجاز الجماعي جوائز فردية، حيث حصل مهاجمه محمد درويش على لقب هداف البطولة بعدما سجل 8 أهداف، فيما نال حارس المرمى محمد معياري جائزة أف Source: https://alikhbariah.com/%d9%85%d9%86%d8%aa%d8%ae%d8%a8-%d8%ad%d9%84%d8%a8-%d8%a8%d8%b7%d9%84%d8%a7%d9%8b-%d9%84%d8%a8%d8%b7%d9%88%d9%84%d8%a9-%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%89-%d9%84%d9%83/', 'The Aleppo national team was crowned champion of the first Syrian mini-football championship after defeating the Daraa national team on penalties, 3-2, in the final match that was held on Monday, February 16, after regular time ended in a 3-3 draw. The match witnessed competition There was a strong exchange of goals between the two teams during regular time, before heading to penalty kicks to decide the result, according to what the Ministry of Sports and Youth published through its official accounts. The Aleppo national team started the match by leading by three goals to one. Before the balance changed after his goalkeeper was sent off in the 70th minute of the match. The Daraa team took advantage of the numerical deficiency and reduced the gap, before achieving an equalizer in the last seconds of stoppage time, so the two teams resorted to penalty kicks, which The Aleppo national team won it in its favor with a score of (3-2). The Aleppo national team added individual awards to the collective achievement, as its striker Mohamed Darwish won the title of top scorer in the tournament after scoring 8 goals, while goalkeeper Mohamed Mairi won the F-Award. Source: https://alikhbariah.com/%d9%85%d9%86%d8%aa%d8%ae%d8%a8-%d8%ad%d9%84%d8%a8-%d8%a8%d8%b7%d9%84%d8%a7%d9%8b-%d9%8 4%d8%a8%d8%b7%d9%88%d9%84%d8%a9-%d8%b3%d9%88%d8%b1%d9%8a%d8%a7-%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%89-%d9%84%d9% 83/', 'https://alikhbariah.com/wp-content/uploads/2026/02/Aleppo-team-wins-the-first-Syrian-Mini-Football-Championship.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 6 limit 1), '2026-02-16T22:30:30+03:00'::timestamptz, false, false, false, 142),
  ('انطلاق البطولة الرمضانية الأولى لكرة القدم داخل الصالات في دمشق', 'The first Ramadan futsal tournament begins in Damascus', 'انطلقت فعاليات البطولة الرمضانية الأولى لكرة القدم داخل الصالات، التي تُنظَّمها وزارة الرياضة والشباب بالتعاون مع سفارة مملكة البحرين في دمشق. ويشرف على البطولة الاتحاد السوري لكرة القدم، برعاية المؤسسة الملكية للأعمال الإنسانية في مملكة البحرين وشركة طموح البحرينية للإدارة الرياضية، إضافة إلى مجموعة ديونز، حسب ما نشرت وزارة الرياضة والشباب على معرفاتها الرسمية الخميس […]', 'The first Ramadan futsal tournament, organized by the Ministry of Sports and Youth in cooperation with the Embassy of the Kingdom of Bahrain in Damascus, was launched. The tournament is supervised by the Syrian Football Federation, sponsored by the Royal Business Corporation Humanitarian Affairs in the Kingdom of Bahrain and the Bahraini Tamouh Sports Management Company, in addition to the Dunes Group, according to what the Ministry of Sports and Youth published on its official websites on Thursday […]', 'انطلقت فعاليات البطولة الرمضانية الأولى لكرة القدم داخل الصالات، التي تُنظَّمها وزارة الرياضة والشباب بالتعاون مع سفارة مملكة البحرين في دمشق. ويشرف على البطولة الاتحاد السوري لكرة القدم، برعاية المؤسسة الملكية للأعمال الإنسانية في مملكة البحرين وشركة طموح البحرينية للإدارة الرياضية، إضافة إلى مجموعة ديونز، حسب ما نشرت وزارة الرياضة والشباب على معرفاتها الرسمية الخميس 12 شباط. وتضمن حفل الافتتاح فقرات فنية مستوحاة من التراث السوري، إلى جانب عروض رياضية أضفت أجواء حماسية عكست أهداف البطولة في تعزيز التواصل والتلاقي بين الشعوب. وأكد سفير مملكة البحرين في دمشق وحيد مبارك سيار، أن تنظيم البطولة يهدف إلى تنمية العلاقات الاجتماعية والإنسانية بين أعضاء السلك الدبلوماسي والشباب السوري. كما أشار إلى أن تنظيم البطولة يمهّد لإقامة فعاليات رياضية مشتركة مستقبلاً بمشاركة البعثات الدبلوماسية المعتمدة في سوريا. ولفت السفير البحريني إلى أن الرياضة لغة عا Source: https://alikhbariah.com/%d8%a7%d9%86%d8%b7%d9%84%d8%a7%d9%82-%d8%a7%d9%84%d8%a8%d8%b7%d9%88%d9%84%d8%a9-%d8%a7%d9%84%d8%b1%d9%85%d8%b6%d8%a7%d9%86%d9%8a%d8%a9-%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%89-%d9%84%d9%83%d8%b1%d8%a9/', 'The first Ramadan futsal tournament, organized by the Ministry of Sports and Youth in cooperation with the Embassy of the Kingdom of Bahrain in Damascus, was launched. The tournament is supervised by the Syrian Football Federation, sponsored by the Royal Business Corporation Humanitarian Affairs in the Kingdom of Bahrain and the Bahraini Tamouh Sports Management Company, in addition to the Dunes Group, according to what the Ministry of Sports and Youth published on its official websites on Thursday, February 12. The opening ceremony included artistic performances inspired by Syrian heritage. In addition to sports performances, they added an enthusiastic atmosphere that reflected the goals of the tournament in enhancing communication and rapprochement between peoples. The Ambassador of the Kingdom of Bahrain to Damascus, Wahid Mubarak Sayyar, confirmed that organizing the tournament aims to develop social and humanitarian relations between the members of the tournament. The diplomatic corps and Syrian youth. He also pointed out that organizing the tournament paves the way for holding joint sporting events in the future with the participation of diplomatic missions accredited in Syria. The Bahraini ambassador pointed out that sports is a universal language. Source: https://alikhbariah.com/%d8%a7%d9%86%d8%b7%d9%84%d8%a7%d9%82-%d8%a7%d9%84%d8%a8%d8%b7%d9%88%d9%84%d8%a9-%d8%a7 %d9%84%d8%b1%d9%85%d8%b6%d8%a7%d9%86%d9%8a%d8%a9-%d8%a7%d9%84%d8%a3%d9%88%d9%84%d9%89-%d9%84%d9%83%d8%b1%d8%a9 /', 'https://alikhbariah.com/wp-content/uploads/2026/02/The-first-Ramadan-indoor-football-tournament-kicks-off-in-Damascus.jpg', (select id from public.categories where slug = 'news-sports' and type = 'news' limit 1), (select id from public.locations order by id offset 7 limit 1), '2026-02-12T21:23:01+03:00'::timestamptz, false, false, false, 141),
  ('برعاية وزارة الثقافة.. انطلاق ملتقى رواق للتراث السوري في المكتبة الوطنية بدمشق', 'Under the sponsorship of the Ministry of Culture, the launch of the Rawaq Forum for Syrian Heritage at the National Library in Damascus', 'انطلقت أعمال ملتقى رواق للتراث السوري، اليوم الجمعة 27 آذار، تحت رعاية وزارة الثقافة في المكتبة الوطنية بدمشق، بهدف توثيق التراث السوري المادي واللامادي وإتاحته عبر منصات رقمية متخصصة. وأكد وزير الثقافة محمد ياسين الصالح، أن إطلاق الملتقى يعكس توجهاً استراتيجياً يعتمد على الشراكة مع المبادرات الثقافية وتمكينها لتكون رافداً أساسياً في صون الهوية الوطنية، […]', 'The work of the Rwaq Forum for Syrian Heritage was launched today, Friday, March 27, under the auspices of the Ministry of Culture at the National Library in Damascus, with the aim of documenting the tangible and intangible Syrian heritage and making it available through specialized digital platforms. The Minister of Culture, Muhammad Yassin, confirmed Al-Saleh said that launching the forum reflects a strategic direction that relies on partnership with cultural initiatives and enabling them to be an essential contributor to the preservation of national identity, […]', 'انطلقت أعمال ملتقى رواق للتراث السوري، اليوم الجمعة 27 آذار، تحت رعاية وزارة الثقافة في المكتبة الوطنية بدمشق، بهدف توثيق التراث السوري المادي واللامادي وإتاحته عبر منصات رقمية متخصصة. وأكد وزير الثقافة محمد ياسين الصالح، أن إطلاق الملتقى يعكس توجهاً استراتيجياً يعتمد على الشراكة مع المبادرات الثقافية وتمكينها لتكون رافداً أساسياً في صون الهوية الوطنية، مشدداً على أن التراث السوري أمانة مشتركة تتطلب تكامل جهود المؤسسات والباحثين والمجتمعات المحلية، بحسب ما نشرته وزارة الثقافة عبر معرفاتها الرسمية. وبين الوزير أن الملتقى يسهم في تعزيز الشراكات، وتطوير آليات التوثيق، وحماية الإرث السوري من التزييف والاستهلاك، مؤكداً دعم الوزارة لاستعادة السردية الوطنية وعرضها للعالم بصوت أهلها. ومن جانبها، استعرضت الدكتورة هلا قصقص، المشرفة على ملتقى رواق مع فريق العمل، أهمية التوثيق وآلياته وسبل البحث والتدقيق ومنصات التفاعل في مختلف الأروقة التي يتبناها ا Source: https://alikhbariah.com/%d8%a8%d8%b1%d8%b9%d8%a7%d9%8a%d8%a9-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d8%a7%d9%86%d8%b7%d9%84%d8%a7%d9%82-%d9%85%d9%84%d8%aa%d9%82%d9%89-%d8%b1%d9%88%d8%a7/', 'The work of the Rwaq Forum for Syrian Heritage was launched today, Friday, March 27, under the auspices of the Ministry of Culture at the National Library in Damascus, with the aim of documenting the tangible and intangible Syrian heritage and making it available through specialized digital platforms. The Minister of Culture, Muhammad Yassin, confirmed Al-Saleh said that launching the forum reflects a strategic direction that relies on partnership with cultural initiatives and enabling them to be an essential contributor to the preservation of national identity, stressing that Syrian heritage is a joint trust that requires the integrated efforts of institutions and researchers. And local communities, according to what the Ministry of Culture published through its official accounts. The Minister stated that the forum contributes to strengthening partnerships, developing documentation mechanisms, and protecting Syrian heritage from counterfeiting and consumption, stressing the Ministry’s support for restoring the narrative. Patriotism and presenting it to the world with the voice of its people. For her part, Dr. Hala Qasqas, supervisor of the RIWAQ Forum, reviewed with the work team the importance of documentation, its mechanisms, methods of research and auditing, and interaction platforms in the various corridors adopted by RIWAQ. Source: https://alikhbariah.com/%d8%a8%d8%b1%d8%b9%d8%a7%d9%8a%d8%a9-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab %d9%82%d8%a7%d9%81%d8%a9-%d8%a7%d9%86%d8%b7%d9%84%d8%a7%d9%82-%d9%85%d9%84%d8%aa%d9%82%d9%89-%d8%b1%d9%88%d8%a 7/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Ministry-of-Culture.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 8 limit 1), '2026-03-27T12:00:10+03:00'::timestamptz, false, true, false, 140),
  ('وزير الثقافة يثني على جهود وزارة الداخلية خلال معرض دمشق الدولي للكتاب', 'The Minister of Culture praises the efforts of the Ministry of Interior during the Damascus International Book Fair', 'أثنى وزير الثقافة محمد ياسين صالح، الثلاثاء 17 شباط، على جهود وزارة الداخلية وقيادة الأمن الداخلي ورجال الأمن عقب انتهاء معرض دمشق الدولي للكتاب. وأعرب صالح في تدوينة عبر منصة “إكس“، عن تقديره لجهودهم خلال أيام المعرض، مشيراً إلى سهرهم لضمان سلامة الزوار والناشرين. وأوضح أنهم قدموا صورة تليق بالمعرض الذي أعاد الاعتبار للثقافة السورية […]', 'On Tuesday, February 17, Minister of Culture Muhammad Yassin Saleh praised the efforts of the Ministry of Interior, the Internal Security Command, and security personnel following the end of the Damascus International Book Fair. In a blog post on the “X” platform, Saleh expressed his appreciation for their efforts during the exhibition days, Noting that they are staying up late to ensure the safety of visitors and publishers. He explained that they presented an image worthy of the exhibition, which restored respect for Syrian culture […]', 'أثنى وزير الثقافة محمد ياسين صالح، الثلاثاء 17 شباط، على جهود وزارة الداخلية وقيادة الأمن الداخلي ورجال الأمن عقب انتهاء معرض دمشق الدولي للكتاب. وأعرب صالح في تدوينة عبر منصة “إكس “، عن تقديره لجهودهم خلال أيام المعرض، مشيراً إلى سهرهم لضمان سلامة الزوار والناشرين. وأوضح أنهم قدموا صورة تليق بالمعرض الذي أعاد الاعتبار للثقافة السورية بعد أن صودرت أعواماً طوالاً. واختتمت فعاليات معرض دمشق الدولي للكتاب، أمس الإثنين، وسط حضور عربي ودولي واسع وتكريم عدد من دور النشر والكتاب بعد 11 يوماً من انطلاقته. وأكد وزير الثقافة، في كلمة خلال حفل الاختتام، أهمية المعرض في تعزيز الدبلوماسية الثقافية والسياسية وتقديم صورة مشرقة عن سوريا الجديدة وأن المعرض تجاوز توقعات الناشرين وعكس تفاؤلاً كبيراً بمستقبل البلاد الحضاري. وأشار إلى أن المشروع الثقافي الجديد يعيد سوريا إلى مكانتها الحضارية الأصيلة مع التركيز على فئتي الأطفال والشباب، موضحاً أن الفئات العمري Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d9%8a%d8%ab%d9%86%d9%8a-%d8%b9%d9%84%d9%89-%d8%ac%d9%87%d9%88%d8%af-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%af%d8%a7%d8%ae/', 'On Tuesday, February 17, Minister of Culture Muhammad Yassin Saleh praised the efforts of the Ministry of Interior, the Internal Security Command, and security personnel following the end of the Damascus International Book Fair. In a blog post on the “X” platform, Saleh expressed his appreciation for their efforts during the exhibition days, Noting that they are staying up late to ensure the safety of visitors and publishers. He explained that they presented an image worthy of the exhibition, which restored respect for Syrian culture after it had been confiscated for many years. The activities of the Damascus International Book Fair concluded yesterday, Monday, amid an Arab and international presence It was widely distributed and a number of publishing houses and writers were honored 11 days after its launch. In a speech during the closing ceremony, the Minister of Culture stressed the importance of the exhibition in strengthening cultural and political diplomacy and presenting a bright image of the new Syria, and that the exhibition went beyond Publishers'' expectations reflected great optimism about the country''s cultural future. He pointed out that the new cultural project restores Syria to its original cultural status, with a focus on the categories of children and youth, explaining that the age groups Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d9%8a%d8%ab%d9%86 %d9%8a-%d8%b9%d9%84%d9%89-%d8%ac%d9%87%d9%88%d8%af-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%af%d8%a7%d8% ae/', 'https://alikhbariah.com/wp-content/uploads/2026/02/Minister-of-Culture-Mohammed-Al-Saleh.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 9 limit 1), '2026-02-17T23:42:13+03:00'::timestamptz, false, true, false, 139),
  ('بتوجيه من الرئيس الشرع.. وزارة الثقافة تعفي الناشرين من رسوم معرض دمشق للكتاب', 'Under the direction of President Al-Sharaa, the Ministry of Culture exempts publishers from Damascus Book Fair fees', 'أعلنت وزارة الثقافة إعفاء جميع الناشرين من رسوم الاشتراك واستئجار الأجنحة في معرض دمشق الدولي للكتاب، لتكون هذه الخطوة هدية بمناسبة النسخة التاريخية للمعرض. وقال وزير الثقافة محمد ياسين الصالح في تصريح لوكالة سانا، السبت 14 شباط، إن الإعفاء جاء بتوجيهات من السيد الرئيس أحمد الشرع. وأضاف أنّ “البعد التجاري للمعرض يظل ثانوياً، فيما يتقدّم […]', 'The Ministry of Culture announced that all publishers will be exempted from subscription fees and renting pavilions at the Damascus International Book Fair, so that this step will be a gift on the occasion of the historic edition of the fair. Minister of Culture Muhammad Yassin Al-Saleh said in a statement to SANA: Saturday, February 14, the exemption came under the directives of President Ahmed Al-Sharaa. He added that “the commercial dimension of the exhibition remains secondary, while […]', 'أعلنت وزارة الثقافة إعفاء جميع الناشرين من رسوم الاشتراك واستئجار الأجنحة في معرض دمشق الدولي للكتاب، لتكون هذه الخطوة هدية بمناسبة النسخة التاريخية للمعرض. وقال وزير الثقافة محمد ياسين الصالح في تصريح لوكالة سانا ، السبت 14 شباط، إن الإعفاء جاء بتوجيهات من السيد الرئيس أحمد الشرع. وأضاف أنّ “البعد التجاري للمعرض يظل ثانوياً، فيما يتقدّم البعد الفكري في هذا المحفل الثقافي بامتياز، مؤكداً أن المعرض يعكس عودة سوريا بقوة واستعادة كلمتها وهويتها ووجهها المشرق”. وأشار الصالح إلى أن المعرض يمثل شمس الحرف والحضارة، ويبرز أهمية الثقافة والفكر في تعزيز حضور الجمهورية العربية السورية داخلياً وخارجياً. وأكد وزير الثقافة في الرابع من الشهر الجاري، أن معرض دمشق الدولي للكتاب يشكل هذا العام حدثاً استثنائياً يعكس مرحلة ما بعد التحرير، ويعبر عن هوية ثقافية سورية جديدة تقوم على حرية الفكر واتساع فضاء التعبير، بعد عقود كان فيها سقف الحرية منخفضاً وهيمنة ال Source: https://alikhbariah.com/%d8%a8%d8%aa%d9%88%d8%ac%d9%8a%d9%87-%d9%85%d9%86-%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d8%aa/', 'The Ministry of Culture announced that all publishers will be exempted from subscription fees and renting pavilions at the Damascus International Book Fair, so that this step will be a gift on the occasion of the historic edition of the fair. Minister of Culture Muhammad Yassin Al-Saleh said in a statement to SANA: Saturday, February 14, the exemption came under the directives of President Ahmed Al-Sharaa. He added, “The commercial dimension of the exhibition remains secondary, while the intellectual dimension in this cultural forum is par excellence, stressing that the exhibition reflects Syria’s strong return and restoration.” Its word, its identity, and its bright face.” Al-Saleh pointed out that the exhibition represents the sun of crafts and civilization, and highlights the importance of culture and thought in enhancing the presence of the Syrian Arab Republic internally and externally. The Minister of Culture confirmed on the fourth of this month that The Damascus International Book Fair this year constitutes an exceptional event that reflects the post-liberation era, and expresses a new Syrian cultural identity based on freedom of thought and a wide space for expression, after decades in which the ceiling for freedom was low and the dominance of the source: https://alikhbariah.com/%d8%a8%d8%aa%d9%88%d8%ac%d9%8a%d9%87-%d9%85%d9%86-%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3 -%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d8% aa/', 'https://alikhbariah.com/wp-content/uploads/2026/02/Book-Fair-1.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 10 limit 1), '2026-02-14T15:48:33+03:00'::timestamptz, false, false, false, 138),
  ('معرض دمشق الدولي للكتاب يستقطب 250 ألف زائر في يومه الأول', 'The Damascus International Book Fair attracts 250,000 visitors on its first day', 'استقبل معرض دمشق الدولي للكتاب في يومه الأول 250 ألف زائر، وفقاً لوزير الثقافة محمد ياسين صالح الذي اعتبر الإقبال على المعرض كمؤشر إيجابي في مسار التعافي واسترداد الهوية الوطنية. وأوضح الوزير في تصريح للإخبارية، السبت 7 شباط، أن الهدف الأساسي هو توثيق سوريا الحضاري ووضعه في الإطار الذي يليق بها وتستحقه، مشيراً إلى رفع […]', 'On its first day, the Damascus International Book Fair received 250,000 visitors, according to the Minister of Culture, Muhammad Yassin Saleh, who considered the turnout at the exhibition as a positive indicator in the path of recovery and recovery of national identity. The minister explained in a statement to Al-Ikhbariya, Saturday 7th February, said that the primary goal is to document Syria’s civilization and place it in the framework that befits and deserves it, pointing out […]', 'استقبل معرض دمشق الدولي للكتاب في يومه الأول 250 ألف زائر، وفقاً لوزير الثقافة محمد ياسين صالح الذي اعتبر الإقبال على المعرض كمؤشر إيجابي في مسار التعافي واسترداد الهوية الوطنية. وأوضح الوزير في تصريح ل لإخبارية ، السبت 7 شباط، أن الهدف الأساسي هو توثيق سوريا الحضاري ووضعه في الإطار الذي يليق بها وتستحقه، مشيراً إلى رفع سقف التحدي والجمال والإبداع بتنظيم معرض دولي بهذا الحجم في دمشق. وأضاف صالح أن الوزارة تجري تقييماً يومياً لفعاليات معرض دمشق الدولي للكتاب لتجنب أي أخطاء محتملة خلال سير المعرض، لافتاً إلى أنه في كل مكان بالمعرض هناك ما يلفت الانتباه ويجذب الزوار. وأشار الوزير إلى أن النظام البائد استهلك دور الكتب عبر فرض رقابة على نوعيتها وطريقة المشاركة، مؤكداً أن المعرض الحالي يعكس حرية الإبداع والتنوع الثقافي. وافتتح وزير الثقافة، يوم الخميس الماضي، حفل معرض دمشق الدولي للكتاب بدورته الاستثنائية في قصر المؤتمرات بدمشق، مؤكداً أن السور Source: https://alikhbariah.com/%d9%85%d8%b9%d8%b1%d8%b6-%d8%af%d9%85%d8%b4%d9%82-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a-%d9%84%d9%84%d9%83%d8%aa%d8%a7%d8%a8-%d9%8a%d8%b3%d8%aa%d9%82%d8%b7%d8%a8-250-%d8%a3%d9%84%d9%81-%d8%b2%d8%a7/', 'On its first day, the Damascus International Book Fair received 250,000 visitors, according to the Minister of Culture, Muhammad Yassin Saleh, who considered the turnout at the exhibition as a positive indicator in the path of recovery and recovery of national identity. The minister explained in a statement to Ikhbaria, on Saturday February 7, that the primary goal is to document Syria’s civilization and place it in the framework that befits and deserves it, pointing to raising the ceiling of challenge, beauty and creativity by organizing an international exhibition of this size in Damascus. Saleh added that the Ministry conducts a daily evaluation of activities Damascus International Book Fair to avoid any possible errors during the course of the exhibition, pointing out that everywhere in the exhibition there is something that attracts attention and attracts visitors. The minister pointed out that the former regime had exhausted the role of books by imposing censorship on their quality and method Participation, stressing that the current exhibition reflects freedom of creativity and cultural diversity. Last Thursday, the Minister of Culture opened the extraordinary session of the Damascus International Book Fair at the Conference Palace in Damascus, stressing that the fence Source: https://alikhbariah.com/%d9%85%d8%b9%d8%b1%d8%b6-%d8%af%d9%85%d8%b4%d9%82-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a -%d9%84%d9%84%d9%83%d8%aa%d8%a7%d8%a8-%d9%8a%d8%b3%d8%aa%d9%82%d8%b7%d8%a8-250-%d8%a3%d9%84%d9%81-%d8%b2%d8%a7 /', 'https://alikhbariah.com/wp-content/uploads/2026/02/Damascus-International-Book-Fair.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 11 limit 1), '2026-02-07T15:21:26+03:00'::timestamptz, false, false, false, 137),
  ('الرئيس الشرع يصل إلى قصر المؤتمرات للمشاركة بافتتاح معرض دمشق الدولي للكتاب', 'President Al-Sharaa arrives at the Conference Palace to participate in the opening of the Damascus International Book Fair', 'وصل السيد الرئيس أحمد الشرع برفقة عقيلته، إلى قصر المؤتمرات في دمشق للمشاركة في حفل افتتاح معرض دمشق الدولي للكتاب. وبدأت الوفود المشاركة في معرض دمشق الدولي للكتاب بالوصول إلى قصر المؤتمرات في دمشق، الخميس 5 شباط، للمشاركة في حفل الافتتاح الرسمي للمعرض. وأفادت مراسلة “الإخبارية” بأن الفعالية انطلقت بحضور شخصيات رسمية محلية وعربية وأجنبية […]', 'Mr. President Ahmed Al-Sharaa, accompanied by his wife, arrived at the Conference Palace in Damascus to participate in the opening ceremony of the Damascus International Book Fair. Delegations participating in the Damascus International Book Fair began arriving at the Conference Palace in Damascus on Thursday, February 5. To participate in the official opening ceremony of the exhibition. Al-Ekhbariya correspondent reported that the event was launched in the presence of local, Arab and foreign official figures […]', 'وصل السيد الرئيس أحمد الشرع برفقة عقيلته، إلى قصر المؤتمرات في دمشق للمشاركة في حفل افتتاح معرض دمشق الدولي للكتاب. وبدأت الوفود المشاركة في معرض دمشق الدولي للكتاب بالوصول إلى قصر المؤتمرات في دمشق، الخميس 5 شباط، للمشاركة في حفل الافتتاح الرسمي للمعرض. وأفادت مراسلة “ الإخبارية ” بأن الفعالية انطلقت بحضور شخصيات رسمية محلية وعربية وأجنبية للمشاركة في هذا الحدث الثقافي. وأوضحت المراسلة أن المعرض يمثّل تظاهرة ثقافية وطنية كبرى، مؤكدة أن معرض دمشق الدولي للكتاب لا يقتصر على عرض الكتب فحسب، بل يؤسس لمرحلة جديدة يعاد فيها وصل المجتمع بالمعرفة. من جهتها، قالت وزارة الداخلية عبر معرّفاتها الرسمية إنه، وبتوجيهات من وزير الداخلية أنس خطاب، تفقد قائد الأمن الداخلي في محافظة ريف دمشق العميد أحمد الدالاتي مدينة المعارض في المحافظة قبيل افتتاح معرض دمشق الدولي للكتاب لعام 2026. وأضافت الوزارة أن العميد الدالاتي اطلع على سير عملية التأمين والحماية، و Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%b5%d9%84-%d8%a5%d9%84%d9%89-%d9%82%d8%b5%d8%b1-%d8%a7%d9%84%d9%85%d8%a4%d8%aa%d9%85%d8%b1%d8%a7%d8%aa-%d9%84%d9%84%d9%85/', 'Mr. President Ahmed Al-Sharaa, accompanied by his wife, arrived at the Conference Palace in Damascus to participate in the opening ceremony of the Damascus International Book Fair. Delegations participating in the Damascus International Book Fair began arriving at the Conference Palace in Damascus on Thursday, February 5. To participate in the official opening ceremony of the exhibition. The Al-Ekhbariya correspondent reported that the event was launched in the presence of local, Arab and foreign official figures to participate in this cultural event. The correspondent explained that the exhibition represents a major national cultural demonstration. Emphasizing that the Damascus International Book Fair is not limited to displaying books, but rather establishes a new phase in which society is reconnected with knowledge. For its part, the Ministry of Interior said through its official identifiers that, under the directives of Interior Minister Anas Khattab, the commander of the Internal Security in the Damascus Countryside Governorate, Brigadier General Ahmed Al-Dalati, exhibition city in the governorate, prior to the opening of the Damascus International Book Fair for the year 2026. The Ministry added that Brigadier General Al-Dalati was briefed on the progress of the insurance and protection process, and Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d8%a6%d9%8a%d8%b3-%d8%a7%d9%84%d8%b4%d8%b1%d8%b9-%d9%8a%d8%b5%d9%84 -%d8%a5%d9%84%d9%89-%d9%82%d8%b5%d8%b1-%d8%a7%d9%84%d9%85%d8%a4%d8%aa%d9%85%d8%b1%d8%a7%d8%aa-%d9%84%d9%84%d9% 85/', 'https://alikhbariah.com/wp-content/uploads/2026/02/President-Sharia-3.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 12 limit 1), '2026-02-05T16:53:46+03:00'::timestamptz, false, false, false, 136),
  ('وزير الثقافة: معرض دمشق الدولي للكتاب يرسخ هوية سوريا المتجددة', 'Minister of Culture: The Damascus International Book Fair consolidates Syria’s renewed identity', 'أكد وزير الثقافة محمد ياسين صالح، أن معرض دمشق الدولي للكتاب يشكل في دورته الحالية حدثاً استثنائياً يجسد مرحلة ما بعد التحرير ويعبر عن هوية ثقافية سورية جديدة ترتكز على حرية الفكر واتساع فضاء التعبير بعد عقود من هيمنة الفكر الواحد. وأوضح الصالح في لقاء خاص مع قناة “الإخبارية“، الأربعاء 4 شباط، أن المعرض يأتي […]', 'The Minister of Culture, Muhammad Yassin Saleh, confirmed that the Damascus International Book Fair, in its current session, constitutes an exceptional event that embodies the post-liberation era and expresses a new Syrian cultural identity based on freedom of thought and the expansion of the space of expression after decades of dominance. One thought. Al-Saleh explained in an exclusive interview with Al-Ekhbariya channel, on Wednesday, February 4, that the exhibition comes […]', 'أكد وزير الثقافة محمد ياسين صالح، أن معرض دمشق الدولي للكتاب يشكل في دورته الحالية حدثاً استثنائياً يجسد مرحلة ما بعد التحرير ويعبر عن هوية ثقافية سورية جديدة ترتكز على حرية الفكر واتساع فضاء التعبير بعد عقود من هيمنة الفكر الواحد. وأوضح الصالح في لقاء خاص مع قناة “ الإخبارية “، الأربعاء 4 شباط، أن المعرض يأتي ليجسد صورة سوريا المتجددة التي تستعيد دورها الحضاري وتعيد الاعتبار للكتاب بوصفه ركناً أساسياً في بناء الوعي. وأشار إلى أن هذه الدورة هي الأكبر من حيث حجم المشاركة بتجاوز عدد دور النشر المشاركة 500 دار من سوريا ودول عربية وأجنبية، مع حلول المملكة العربية السعودية ودولة قطر ضيفتي شرف عبر أجنحة وفعاليات واسعة. وبيّن صالح أن الوزارة قدمت تسهيلات كبيرة شملت الإعفاء من رسوم الإيجار وتحمل تكاليف الشحن لتشجيع العودة إلى سوريا. ولفت إلى أن المعرض يتضمن باقة واسعة من المسابقات والجوائز في الرواية والشعر وجائزة أجمل جناح، بالإضافة إلى الكشف عن Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d9%85%d8%b9%d8%b1%d8%b6-%d8%af%d9%85%d8%b4%d9%82-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a-%d9%84%d9%84%d9%83%d8%aa%d8%a7%d8%a8-%d9%8a/', 'The Minister of Culture, Muhammad Yassin Saleh, confirmed that the Damascus International Book Fair, in its current session, constitutes an exceptional event that embodies the post-liberation era and expresses a new Syrian cultural identity based on freedom of thought and the expansion of the space of expression after decades of dominance. One thought. Al-Saleh explained in an exclusive interview with Al-Ekhbariya channel, on Wednesday, February 4, that the exhibition comes to embody the renewed image of Syria, which is regaining its civilizational role and restoring the book’s respectability as an essential pillar in building awareness. He pointed out that this The tournament is the largest in terms of the size of participation, with the number of participating publishing houses exceeding 500 from Syria and Arab and foreign countries, with the Kingdom of Saudi Arabia and the State of Qatar being guests of honor through wide pavilions and events. Saleh stated that the ministry provided facilities It included exemption from rental fees and bearing shipping costs to encourage return to Syria. He pointed out that the exhibition includes a wide range of competitions and prizes in novels and poetry and an award for the most beautiful pavilion, in addition to revealing the source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d9%85%d8%b9%d8%b1 %d8%b6-%d8%af%d9%85%d8%b4%d9%82-%d8%a7%d9%84%d8%af%d9%88%d9%84%d9%8a-%d9%84%d9%84%d9%83%d8%aa%d8%a7%d8%a8-%d9% 8a/', 'https://alikhbariah.com/wp-content/uploads/2025/11/Minister-of-Culture-The-battle-to-deter-aggression-restored-the-dignity-of-a-nation-and-the-indomitable-spirit-of-a-people.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 13 limit 1), '2026-02-04T22:04:41+03:00'::timestamptz, false, false, false, 135),
  ('خلال زيارتهم حاضنة دمر.. دبلوماسيون يحثون على صون الحرف التقليدية', 'During their visit to the Dummar Incubator, diplomats urge the preservation of traditional crafts', 'أكد سفراء أبخازيا والأردن والقائم بأعمال سفارة ليبيا في دمشق، الثلاثاء 3 شباط، خلال زيارتهم إلى حاضنة دمر للفنون الحرفية بدمشق، على ضرورة الحفاظ على الحرف التراثية والإبداع الحرفي السوري. وأعرب السفراء عن أهمية نقل فكرة هذا التجمع الذي يضم أهم الحرف التراثية إلى بلدانهم، مع الإشارة إلى دور الحرف اليدوية في إبراز الثقافة السورية […]', 'On Tuesday, February 3, during their visit to the Dummar Incubator for Craft Arts in Damascus, the Ambassadors of Abkhazia and Jordan and the Chargé d''Affairs of the Libyan Embassy in Damascus stressed the necessity of preserving Syrian heritage crafts and artisanal creativity. The ambassadors expressed the importance of conveying an idea This gathering, which includes the most important heritage crafts from their countries, with reference to the role of handicrafts in highlighting Syrian culture […]', 'أكد سفراء أبخازيا والأردن والقائم بأعمال سفارة ليبيا في دمشق، الثلاثاء 3 شباط، خلال زيارتهم إلى حاضنة دمر للفنون الحرفية بدمشق، على ضرورة الحفاظ على الحرف التراثية والإبداع الحرفي السوري. وأعرب السفراء عن أهمية نقل فكرة هذا التجمع الذي يضم أهم الحرف التراثية إلى بلدانهم، مع الإشارة إلى دور الحرف اليدوية في إبراز الثقافة السورية بحسب ما نشرت وكالة سانا . واطلع السفراء خلال زيارتهم على عدد من الحرف التقليدية الموجودة في الحاضنة مثل: الصدف، والموزاييك، والنقش على النحاس، والحفر على والخشب، وتركيب العطور وتصميم الأزياء والأغباني، إضافة إلى الحصر، واللباس العربي والبروكار والجلديات والخيط العربي والعجمي، والحلاقة والتزيين. بدوره أكد سفير أبخازيا محمد علي أن الحفاظ على الصناعات الحرفية التقليدية في سوريا أمر بالغ الأهمية، كونها تمثل جزءاً من الهوية الثقافية والحضارية العريقة للشعب السوري. وأوضح أن هذه الصناعات تساهم في نقل الثقافة السورية إلى د Source: https://alikhbariah.com/%d8%ae%d9%84%d8%a7%d9%84-%d8%b2%d9%8a%d8%a7%d8%b1%d8%aa%d9%87%d9%85-%d8%ad%d8%a7%d8%b6%d9%86%d8%a9-%d8%af%d9%85%d8%b1-%d8%af%d8%a8%d9%84%d9%88%d9%85%d8%a7%d8%b3%d9%8a%d9%88%d9%86-%d9%8a%d8%ad%d8%ab/', 'On Tuesday, February 3, during their visit to the Dummar Incubator for Craft Arts in Damascus, the Ambassadors of Abkhazia and Jordan and the Chargé d''Affairs of the Libyan Embassy in Damascus stressed the necessity of preserving Syrian heritage crafts and artisanal creativity. The ambassadors expressed the importance of conveying an idea This gathering includes the most important traditional crafts from their countries, with reference to the role of handicrafts in highlighting Syrian culture, according to what was published by SANA. During their visit, the ambassadors were briefed on a number of traditional crafts present in the incubator, such as: Seashells, mosaics, engraving on copper, engraving on wood, installing perfumes, fashion design and garments, in addition to mats, Arabic dress, brocade, leather, Arab and Persian thread, shaving and decoration. In turn, the Ambassador of Abkhazia, Mohammed, confirmed Preserving traditional craft industries in Syria is extremely important, as they represent part of the ancient cultural and civilizational identity of the Syrian people. He explained that these industries contribute to transferring Syrian culture to... https://alikhbariah.com/%d8%ae%d9%84%d8%a7%d9%84-%d8%b2%d9%8a%d8%a7%d8%b1%d8%aa%d9%87%d9%85-%d8%ad%d8%a7%d8%b6 %d9%86%d8%a9-%d8%af%d9%85%d8%b1-%d8%af%d8%a8%d9%84%d9%88%d9%85%d8%a7%d8%b3%d9%8a%d9%88%d9%86-%d9%8a%d8%ad%d8%a b/', 'https://alikhbariah.com/wp-content/uploads/2026/02/Syrian-traditional-crafts.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 0 limit 1), '2026-02-03T22:00:54+03:00'::timestamptz, false, false, false, 134),
  ('هيئة التميز والإبداع تطلق التصفيات النهائية للأولمبياد العلمي السوري 2026', 'The Excellence and Creativity Authority launches the final qualifiers for the Syrian Scientific Olympiad 2026', 'أعلنت هيئة التميز والإبداع، برعاية الأمانة العامة لرئاسة الجمهورية العربية السورية، عن انطلاق التصفيات النهائية للأولمبياد العلمي السوري لموسم 2026، بمشاركة نخبة من الطلاب المتفوقين من مختلف المحافظات السورية. وستجري التصفيات النهائية في فندق السبع بوابات بدمشق، بين 16-19 كانون الثاني الجاري في اختصاصات، الرياضيات والفيزياء والكيمياء وعلم الأحياء والمعلوماتية، قبل أن يجري اختيار الفرق […]', 'The Authority for Excellence and Creativity, under the auspices of the General Secretariat of the Presidency of the Syrian Arab Republic, announced the launch of the final qualifiers for the Syrian Scientific Olympiad for the 2026 season, with the participation of an elite group of outstanding students from various Syrian governorates. And you will run The final qualifiers will be held at the Seven Gates Hotel in Damascus, between January 16-19, in the specializations of mathematics, physics, chemistry, biology and informatics, before the teams are selected […]', 'أعلنت هيئة التميز والإبداع، برعاية الأمانة العامة لرئاسة الجمهورية العربية السورية، عن انطلاق التصفيات النهائية للأولمبياد العلمي السوري لموسم 2026، بمشاركة نخبة من الطلاب المتفوقين من مختلف المحافظات السورية. وستجري التصفيات النهائية في فندق السبع بوابات بدمشق، بين 16-19 كانون الثاني الجاري في اختصاصات، الرياضيات والفيزياء والكيمياء وعلم الأحياء والمعلوماتية، قبل أن يجري اختيار الفرق الوطنية التي ستمثل سورية في المحافل العلمية الإقليمية والدولية، بحسب ما نشرت الهيئة عبر صفحتها الرسمية على فيسبوك . وأضافت الهيئة أنه من المقرر أن تختتم الفعالية بحفل إعلان النتائج وتتويج الفرق الوطنية يوم 19 كانون الثاني 2026 في دار الأوبرا بدمشق، حيث سيتم الإعلان عن أسماء الطلاب الفائزين. ويعرف الأولمبياد العلمي السوري بأنه مسابقات في اختصاصات الرياضيات والفيزياء والكيمياء وعلم الأحياء والمعلوماتية والروبوتيك والمناظرات والنمذجة الرياضية. و تتنافس فيها الد Source: https://alikhbariah.com/%d9%87%d9%8a%d8%a6%d8%a9-%d8%a7%d9%84%d8%aa%d9%85%d9%8a%d8%b2-%d9%88%d8%a7%d9%84%d8%a5%d8%a8%d8%af%d8%a7%d8%b9-%d8%aa%d8%b7%d9%84%d9%82-%d8%a7%d9%84%d8%aa%d8%b5%d9%81%d9%8a%d8%a7%d8%aa-%d8%a7%d9%84/', 'The Authority for Excellence and Creativity, under the auspices of the General Secretariat of the Presidency of the Syrian Arab Republic, announced the launch of the final qualifiers for the Syrian Scientific Olympiad for the 2026 season, with the participation of an elite group of outstanding students from various Syrian governorates. And you will run The final qualifiers will be held at the Seven Gates Hotel in Damascus, between January 16-19, in the specializations of mathematics, physics, chemistry, biology and informatics, before the national teams that will represent Syria in scientific forums are selected. Regional and international, according to what the authority published on its official Facebook page. The authority added that the event is scheduled to conclude with a ceremony announcing the results and crowning the national teams on January 19, 2026 at the Opera House in Damascus, where it will be held. Announcing the names of the winning students. The Syrian Scientific Olympiad is known as competitions in the disciplines of mathematics, physics, chemistry, biology, informatics, robotics, debates, and mathematical modeling. Source: https://alikhbariah.com/%d9%87%d9%8a%d8%a6%d8%a9-%d8%a7%d9%84%d8%aa%d9%85%d9%8a%d8%b2-%d9%88%d8%a7%d9%84%d8%a5 %d8%a8%d8%af%d8%a7%d8%b9-%d8%aa%d8%b7%d9%84%d9%82-%d8%a7%d9%84%d8%aa%d8%b5%d9%81%d9%8a%d8%a7%d8%aa-%d8%a7%d9%8 4/', 'https://alikhbariah.com/wp-content/uploads/2026/01/Excellence-and-Creativity-Authority.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 1 limit 1), '2026-01-14T01:11:43+03:00'::timestamptz, false, false, false, 133),
  ('وزارة الثقافة تنعى الباحث عماد الأرمشي أحد أبرز مؤرخين تاريخ دمشق العمراني', 'The Ministry of Culture mourns the researcher Imad Al-Armashi, one of the most prominent historians of Damascus’ urban history', 'نعت وزارة الثقافة، الثلاثاء 30 كانون الأول، المؤرخ والباحث عماد الأرمشي، أحد أبرز المتخصصين في توثيق التاريخ العمراني لمدينة دمشق، والذي شكل برحيله خسارة كبيرة للمشهد الثقافي والبحثي المعني بذاكرة العاصمة. وعن حياته، ولد الأرمشي في مدينة دمشق عام 1951، ونشأ في حي سوق ساروجة، ما عزز ارتباطه المبكر بالمدينة وأحيائها ومعالمها التاريخية. ونال شهادة […]', 'On Tuesday, December 30, the Ministry of Culture mourned the historian and researcher Imad Al-Armashi, one of the most prominent specialists in documenting the urban history of the city of Damascus, whose passing represented a great loss to the cultural and research scene concerned with the memory of the capital. And about his life, Al-Armashi was born in Damascus in 1951, and grew up in the Souq Sarouja neighborhood, which strengthened his early connection with the city, its neighborhoods, and its historical landmarks. He received a certificate [...]', 'نعت وزارة الثقافة، الثلاثاء 30 كانون الأول، المؤرخ والباحث عماد الأرمشي، أحد أبرز المتخصصين في توثيق التاريخ العمراني لمدينة دمشق، والذي شكل برحيله خسارة كبيرة للمشهد الثقافي والبحثي المعني بذاكرة العاصمة. وعن حياته، ولد الأرمشي في مدينة دمشق عام 1951، ونشأ في حي سوق ساروجة، ما عزز ارتباطه المبكر بالمدينة وأحيائها ومعالمها التاريخية. ونال شهادة الإجازة في التاريخ من جامعة دمشق عام 1977، ليبدأ بعدها مسيرته البحثية التي اتسمت بالدقة والمنهجية في التوثيق. وكرس المؤرخ منذ عام 2003 جهوده لجمع وأرشفة كم واسع من الوثائق والصور والمراجع المتعلقة بأحياء دمشق وأسواقها وجوامعها ومدارسها وتكاياها وخاناتها، إلى جانب توثيق تاريخ أسرها العريقة. ورصد التحولات العمرانية التي شهدتها المدينة على مدى عقود، وسعى إلى حفظ معالمها من الاندثار عبر أرشيف بصري ومعرفي غني. وخلّف عماد الأرمشي إرثاً توثيقياً ثميناً سيبقى مرجعاً للأجيال القادمة، وشاهداً على إسهامه العم Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d8%aa%d9%86%d8%b9%d9%89-%d8%a7%d9%84%d8%a8%d8%a7%d8%ad%d8%ab-%d8%b9%d9%85%d8%a7%d8%af-%d8%a7%d9%84%d8%a3%d8%b1%d9%85%d8%b4/', 'On Tuesday, December 30, the Ministry of Culture mourned the historian and researcher Imad Al-Armashi, one of the most prominent specialists in documenting the urban history of the city of Damascus, whose passing represented a great loss to the cultural and research scene concerned with the memory of the capital. And about his life, Al-Armashi was born in Damascus in 1951, and grew up in the Souq Sarouja neighborhood, which strengthened his early connection with the city, its neighborhoods, and its historical landmarks. He obtained a bachelor''s degree in history from the University of Damascus in 1977, after which he began his research career, which was characterized by precision. And methodology in documentation. Since 2003, the historian has devoted his efforts to collecting and archiving a wide range of documents, photos, and references related to Damascus’ neighborhoods, markets, mosques, schools, hospices, and inns, in addition to documenting the history of its ancient families. And monitor transformations The urban development that the city witnessed over the decades, and sought to preserve its landmarks from extinction through a rich visual and cognitive archive. Imad Al-Armashi left behind a valuable documentary legacy that will remain a reference for future generations, and a testimony to his great contribution. Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d8%aa%d9%86 %d8%b9%d9%89-%d8%a7%d9%84%d8%a8%d8%a7%d8%ad%d8%ab-%d8%b9%d9%85%d8%a7%d8%af-%d8%a7%d9%84%d8%a3%d8%b1%d9%85%d8%b 4/', 'https://alikhbariah.com/wp-content/uploads/2025/12/Emad-Al-Armashi-1.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 2 limit 1), '2025-12-30T16:58:08+03:00'::timestamptz, false, false, false, 132),
  ('وزارة الثقافة تحتفي باليوم العالمي للغة العربية في كلية الآداب بدمشق', 'The Ministry of Culture celebrates International Arabic Language Day at the College of Arts in Damascus', 'نظمت وزارة الثقافة بالتعاون مع كلية الآداب والعلوم الإنسانية في جامعة دمشق، يوم أمس الخميس، فعالية ثقافية احتفاءً باليوم العالمي للغة العربية، وذلك في مدرج الكلية. وشدد مدير مديرية المراكز الثقافية أنس الدغيم في كلمة له، على حرص الوزارة على الاهتمام بلغة القرآن الكريم، مؤكداً أنها “مداد وفكر للجميع لا ينضب”. وتضمنت الفعالية ندوة علمية […]', 'Yesterday, Thursday, the Ministry of Culture, in cooperation with the Faculty of Arts and Human Sciences at Damascus University, organized a cultural event to celebrate International Arabic Language Day, in the college’s auditorium. Director of the Cultural Centers Directorate, Anas Al-Daghim, stressed in a speech He praised the Ministry’s keenness to pay attention to the language of the Holy Qur’an, stressing that it is “an inexhaustible resource and thought for all.” The event included a scientific symposium [...]', 'نظمت وزارة الثقافة بالتعاون مع كلية الآداب والعلوم الإنسانية في جامعة دمشق، يوم أمس الخميس، فعالية ثقافية احتفاءً باليوم العالمي للغة العربية، وذلك في مدرج الكلية. وشدد مدير مديرية المراكز الثقافية أنس الدغيم في كلمة له، على حرص الوزارة على الاهتمام بلغة القرآن الكريم، مؤكداً أنها “مداد وفكر للجميع لا ينضب”. وتضمنت الفعالية ندوة علمية قدم خلالها عضو الهيئة التدريسية في جامعة دمشق أيمن الشوّا مداخلة بعنوان “الغيرة على اللغة العربية”، سلط فيها الضوء على جهود علماء اللغة الأوائل كالفراهيدي وسيبويه والنسائي والفرّاء، وأثرهم الباقي حتى اليوم، مشيراً إلى أن المستشرقين والمؤرخين المنصفين حثوا العرب على الغيرة على لغتهم. ومن جانبها، قدمت رئيسة قسم اللغة العربية وآدابها في الجامعة الدكتورة منى طعمة، خلال مداخلتها بعنوان “اللغة العربية بين الواقع والمأمول”، تحليلاً واقعياً لواقع القسم والتحديات التي يواجهها كتضخم أعداد الطلاب، مؤكدة ضرورة تعاون كاف Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d8%aa%d8%ad%d8%aa%d9%81%d9%8a-%d8%a8%d8%a7%d9%84%d9%8a%d9%88%d9%85-%d8%a7%d9%84%d8%b9%d8%a7%d9%84%d9%85%d9%8a-%d9%84%d9%84/', 'Yesterday, Thursday, the Ministry of Culture, in cooperation with the Faculty of Arts and Human Sciences at Damascus University, organized a cultural event to celebrate International Arabic Language Day, in the college’s auditorium. Director of the Cultural Centers Directorate, Anas Al-Daghim, stressed in a speech He praised the Ministry’s keenness to pay attention to the language of the Holy Qur’an, stressing that it is “an inexhaustible resource and thought for all.” The event included a scientific symposium during which Damascus University faculty member Ayman Al-Shawa presented an intervention entitled “Jealousy for the Arabic Language.” In it, he shed light on the efforts of early linguists such as Al-Farahidi, Sibawayh, Al-Nasa’i, and Al-Farra’, and their impact that remains until today, pointing out that orientalists and fair-minded historians urged the Arabs to be jealous of their language. For her part, the Head of the Language Department presented Arabic and its literature at the university, Dr. Mona Tohme, during her intervention entitled “The Arabic Language between Reality and Aspirations,” provided a realistic analysis of the reality of the department and the challenges it faces, such as the swelling numbers of students, stressing the necessity of sufficient cooperation. Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%ab%d9%82%d8%a7%d9%81%d8%a9-%d8%aa%d8%ad %d8%aa%d9%81%d9%8a-%d8%a8%d8%a7%d9%84%d9%8a%d9%88%d9%85-%d8%a7%d9%84%d8%b9%d8%a7%d9%84%d9%85%d9%8a-%d9%84%d9%8 4/', 'https://alikhbariah.com/wp-content/uploads/2025/12/Ministry-of-Culture.jpg', (select id from public.categories where slug = 'news-culture' and type = 'news' limit 1), (select id from public.locations order by id offset 3 limit 1), '2025-12-19T13:40:41+03:00'::timestamptz, false, false, false, 131),
  ('معاون محافظ حماة يبحث مع مديري المشافي الخاصة تطوير الخدمات الطبية', 'Assistant Governor of Hama discusses with private hospital directors the development of medical services', 'بحث معاون محافظ حماة لقطاع الصحة محمد الشريف، مع مديري المشافي الخاصة سبل تحسين الخدمات الطبية ورفع كفاءة العمل في القطاع الصحي. وتطرق الاجتماع إلى التركيز على تقديم خدمات طبية عالية الجودة وضمان سلامة المرضى والكادر الطبي، إلى جانب تناول أبرز التحديات والاستماع إلى مقترحات المعنيين. بحسب ما نشرت المحافظة عبر معرفاتها الرسمية الثلاثاء 31 […]', 'The Assistant Governor of Hama for the health sector, Muhammad Al-Sharif, discussed with the directors of private hospitals ways to improve medical services and raise the efficiency of work in the health sector. The meeting focused on providing high-quality medical services and ensuring the safety of patients and staff Medical, in addition to addressing the most prominent challenges and listening to the suggestions of those concerned. According to what the governorate published through its official accounts on Tuesday, 31 […]', 'بحث معاون محافظ حماة لقطاع الصحة محمد الشريف، مع مديري المشافي الخاصة سبل تحسين الخدمات الطبية ورفع كفاءة العمل في القطاع الصحي. وتطرق الاجتماع إلى التركيز على تقديم خدمات طبية عالية الجودة وضمان سلامة المرضى والكادر الطبي، إلى جانب تناول أبرز التحديات والاستماع إلى مقترحات المعنيين. بحسب ما نشرت المحافظة عبر معرفاتها الرسمية الثلاثاء 31 آذار. وأكد المشاركون على ضرورة الالتزام المهني والتقيد بمعايير النظافة والتعقيم لضمان جودة الخدمات وحماية صحة المواطنين. وأواخر تشرين الأول الفائت، افتتح وزير الصحة مصعب العلي، قسم غسيل الكلى في مشفى حماة الوطني، وذلك بعد تأهيله وتجهيزه، بهدف تطوير مراكز الغسيل الكلوي وتحسين جودة الخدمات الطبية في مختلف المحافظات. وقال وزير الصحة حينها، إنه “تم تزويد القسم بـ30 جهازاً حديثاً مقدمة من وزارة الصحة بالتعاون مع منظمة “ميدغلوبل” و”منظمة الإغاثة الإسلامية” ، وفقاً لما نقلت معرفات الوزارة الرسمية. وأكد الوزير أن Source: https://alikhbariah.com/%d9%85%d8%b9%d8%a7%d9%88%d9%86-%d9%85%d8%ad%d8%a7%d9%81%d8%b8-%d8%ad%d9%85%d8%a7%d8%a9-%d9%8a%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d9%85%d8%af%d9%8a%d8%b1%d9%8a-%d8%a7%d9%84%d9%85%d8%b4%d8%a7%d9%81%d9%8a/', 'The Assistant Governor of Hama for the health sector, Muhammad Al-Sharif, discussed with the directors of private hospitals ways to improve medical services and raise the efficiency of work in the health sector. The meeting focused on providing high-quality medical services and ensuring the safety of patients and staff Medical, in addition to addressing the most prominent challenges and listening to the suggestions of those concerned. According to what the governorate published through its official accounts on Tuesday, March 31. Participants stressed the need for professional commitment and adherence to hygiene and sterilization standards to ensure quality Services and protecting citizens'' health. In late October, the Minister of Health, Musab Al-Ali, opened the dialysis department at the Hama National Hospital, after rehabilitating and equipping it, with the aim of developing dialysis centers and improving the quality of medical services in various areas. Governorates. The Minister of Health said at the time, “The department was provided with 30 modern devices provided by the Ministry of Health in cooperation with the “MedGlobal” organization and the “Islamic Relief Organization,” according to what was reported by the official Ministry sources. The Minister confirmed that Source: https://alikhbariah.com/%d9%85%d8%b9%d8%a7%d9%88%d9%86-%d9%85%d8%ad%d8%a7%d9%81%d8%b8-%d8%ad%d9%85%d8%a7%d8%a9 -%d9%8a%d8%a8%d8%ad%d8%ab-%d9%85%d8%b9-%d9%85%d8%af%d9%8a%d8%b1%d9%8a-%d8%a7%d9%84%d9%85%d8%b4%d8%a7%d9%81%d9% 8a/', 'https://alikhbariah.com/wp-content/uploads/2026/04/Medical-services-in-Hama.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 4 limit 1), '2026-04-01T01:00:43+03:00'::timestamptz, false, true, false, 130),
  ('توقيع اتفاقية تأمين صحي لأكثر من 11 ألف عامل في الشركة السورية للاتصالات', 'Signing a health insurance agreement for more than 11,000 workers in the Syrian Telecommunications Company', 'وقعت المؤسسة العامة السورية للتأمين، الإثنين 30 آذار، عقد تأمين صحي شامل مع الشركة السورية للاتصالات، لتغطية نحو 11,500 عامل وموظف، وذلك بحضور وزير المالية محمد يسر برنية ووزير الاتصالات وتقانة المعلومات عبد السلام هيكل. ويهدف العقد إلى تعزيز مظلة الرعاية الصحية والاجتماعية للعاملين، بما يسهم في تعزيز الاستقرار الوظيفي وتحسين بيئة العمل، إضافة إلى […]', 'On Monday, March 30, the Syrian General Insurance Corporation signed a comprehensive health insurance contract with the Syrian Telecommunications Company, to cover about 11,500 workers and employees, in the presence of the Minister of Finance, Muhammad Yusser Barneyah, and the Minister of Communications and Information Technology, Abdul Salam. structure. The contract aims to strengthen the health and social care umbrella for workers, which contributes to enhancing job stability and improving the work environment, in addition to [...]', 'وقعت المؤسسة العامة السورية للتأمين، الإثنين 30 آذار، عقد تأمين صحي شامل مع الشركة السورية للاتصالات، لتغطية نحو 11,500 عامل وموظف، وذلك بحضور وزير المالية محمد يسر برنية ووزير الاتصالات وتقانة المعلومات عبد السلام هيكل. ويهدف العقد إلى تعزيز مظلة الرعاية الصحية والاجتماعية للعاملين، بما يسهم في تعزيز الاستقرار الوظيفي وتحسين بيئة العمل، إضافة إلى رفع مستوى الخدمات المقدمة ضمن المؤسسات العامة، بحسب ما نشرت وزارة المالية عبر منصاتها ا لرسمية. من جانبه، أكد وزير المالية أن توقيع العقد جاء بعد عملية تنافسية شفافة، مشيراً إلى الحرص على تقوية حوكمة الشركات والمؤسسات الاقتصادية المملوكة للدولة، وتعزيز تنافسيتها. ولفت إلى أن المرحلة المقبلة ستشهد اهتماماً أكبر بتطوير الضمان الصحي للعاملين، والذي ينعكس بدوره إيجاباً على الأداء وجودة الخدمات المقدمة. وكان الوزير برنية ووزير الصحة مصعب العلي، قد عقدا في 30 كانون الأول، مؤتمراً صحفياً مشتركاً حول خط Source: https://alikhbariah.com/%d8%aa%d9%88%d9%82%d9%8a%d8%b9-%d8%a7%d8%aa%d9%81%d8%a7%d9%82%d9%8a%d8%a9-%d8%aa%d8%a3%d9%85%d9%8a%d9%86-%d8%b5%d8%ad%d9%8a-%d9%84%d8%a3%d9%83%d8%ab%d8%b1-%d9%85%d9%86-11-%d8%a3%d9%84%d9%81-%d8%b9/', 'On Monday, March 30, the Syrian General Insurance Corporation signed a comprehensive health insurance contract with the Syrian Telecommunications Company, to cover about 11,500 workers and employees, in the presence of the Minister of Finance, Muhammad Yusser Barneyah, and the Minister of Communications and Information Technology, Abdul Salam. structure. The contract aims to strengthen the umbrella of health and social care for workers, which contributes to enhancing job stability and improving the work environment, in addition to raising the level of services provided within public institutions, according to what the Ministry of Finance published via Its official platforms. For his part, the Minister of Finance confirmed that the signing of the contract came after a transparent competitive process, indicating the keenness to strengthen the governance of state-owned companies and economic institutions, and enhance their competitiveness. He pointed out that the next stage will witness Greater interest in developing health insurance for workers, which in turn reflects positively on the performance and quality of services provided. On December 30, Minister Bernieh and Minister of Health Musab Al-Ali held a joint press conference about the line Source: https://alikhbariah.com/%d8%aa%d9%88%d9%82%d9%8a%d8%b9-%d8%a7%d8%aa%d9%81%d8%a7%d9%82%d9%8a%d8%a9-%d8%aa%d8%a3 %d9%85%d9%8a%d9%86-%d8%b5%d8%ad%d9%8a-%d9%84%d8%a3%d9%83%d8%ab%d8%b1-%d9%85%d9%86-11-%d8%a3%d9%84%d9%81-%d8%b9 /', 'https://alikhbariah.com/wp-content/uploads/2026/03/agreement.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 5 limit 1), '2026-03-30T19:07:18+03:00'::timestamptz, false, true, false, 129),
  ('وزير الصحة: المرسوم 68 رسالة تقدير للكوادر الطبية', 'Minister of Health: Decree 68 is a letter of appreciation to medical personnel', 'أكد وزير الصحة الدكتور مصعب العلي، أن صدور المرسوم رقم 68 لعام 2026 القاضي بزيادة الرواتب والأجور، يشكل رسالة تقدير ووفاء حقيقية للعاملين، ولا سيما الكوادر الطبية، ويعكس التوجه نحو تحسين واقع القطاع الصحي. وأوضح العلي أن هذه الخطوة تؤكد أن الاستثمار في الإنسان هو المدخل الحقيقي لتطوير الخدمات الصحية ورفع جودتها، حسب ما نشرته […]', 'The Minister of Health, Dr. Musab Al-Ali, confirmed that the issuance of Decree No. 68 of 2026 stipulating increasing salaries and wages constitutes a true message of appreciation and loyalty to workers, especially medical personnel, and reflects the trend towards improving the reality of the health sector. Al-Ali explained This step confirms that investing in people is the real gateway to developing health services and raising their quality, according to what was published […]', 'أكد وزير الصحة الدكتور مصعب العلي، أن صدور المرسوم رقم 68 لعام 2026 القاضي بزيادة الرواتب والأجور، يشكل رسالة تقدير ووفاء حقيقية للعاملين، ولا سيما الكوادر الطبية، ويعكس التوجه نحو تحسين واقع القطاع الصحي. وأوضح العلي أن هذه الخطوة تؤكد أن الاستثمار في الإنسان هو المدخل الحقيقي لتطوير الخدمات الصحية ورفع جودتها، حسب ما نشرته وزارة الصحة عبر معرفاتها الرسمية السبت 21 آذار. وأشار إلى أن وزارة الصحة تؤمن بأن استقرار الكوادر مهنياً ومعيشياً يمثل الضامن الأهم لجودة الرعاية الصحية، وحجر الأساس في تعزيز الأمان الصحي للمجتمع. وأضاف العلي أن الوزارة تبارك لكوادرها هذا التقدير، معربة عن تطلعها إلى انتظام أكبر في تقديم الخدمات الصحية لكل من يحتاجها. وأصدر السيد الرئيس أحمد الشرع المرسوم رقم (68) لعام 2026 القاضي بتطبيق لائحة زيادة نوعية على رواتب وأجور العاملين في سبع جهات عامة، متضمنة علاوة الترفيع المستحقة بموجب القانون رقم /50/ لعام 2004. وجاء ال Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%a7%d9%84%d9%85%d8%b1%d8%b3%d9%88%d9%85-68-%d8%b1%d8%b3%d8%a7%d9%84%d8%a9-%d8%aa%d9%82%d8%af%d9%8a%d8%b1-%d9%84%d9%84%d9%83%d9%88%d8%a7/', 'The Minister of Health, Dr. Musab Al-Ali, confirmed that the issuance of Decree No. 68 of 2026 stipulating increasing salaries and wages constitutes a true message of appreciation and loyalty to workers, especially medical personnel, and reflects the trend towards improving the reality of the health sector. Al-Ali explained This step confirms that investing in people is the real gateway to developing health services and raising their quality, according to what the Ministry of Health published through its official websites on Saturday, March 21. He pointed out that the Ministry of Health believes in the professional stability of cadres Living is the most important guarantee of quality health care, and the cornerstone of enhancing community health security. Al-Ali added that the Ministry congratulates its staff on this appreciation, expressing its aspiration for greater regularity in providing health services to everyone who needs them. Mr. President Ahmed Al-Sharaa issued Decree No. (68) of 2026 implementing a regulation for a qualitative increase in the salaries and wages of workers in seven public agencies, including the promotion bonus due under Law No. /50/ of 2004. The source came: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%a7%d9%84%d9%85%d8%b1%d8%b 3%d9%88%d9%85-68-%d8%b1%d8%b3%d8%a7%d9%84%d8%a9-%d8%aa%d9%82%d8%af%d9%8a%d8%b1-%d9%84%d9%84%d9%83%d9%88%d8%a7/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Minister-of-Health-Decree-68-is-a-message-of-appreciation-to-medical-staff.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 6 limit 1), '2026-03-21T20:41:31+03:00'::timestamptz, false, false, false, 128),
  ('الرقابة والتفتيش تكشف مخالفات إدارية وفنية في أحد مشافي ريف دمشق', 'Oversight and inspection reveal administrative and technical violations in a hospital in the Damascus countryside', 'كشفت الهيئة المركزية للرقابة والتفتيش، الإثنين 16 آذار، عن مخالفات إدارية وفنية في أحد مشافي محافظة ريف دمشق، وذلك في إطار متابعة أداء المؤسسات الصحية والتحقق من الالتزام بالأنظمة والقوانين الناظمة للعمل الطبي. ورصدت الفرق الرقابية التابعة للهيئة خلال جولة رقابية غياب آليات واضحة لتوثيق المواد الطبية المستخدمة داخل المشفى، وعدم حفظ الأضابير الخاصة بملفات […]', 'On Monday, March 16, the Central Authority for Control and Inspection revealed administrative and technical violations in a hospital in the Damascus countryside governorate, within the framework of monitoring the performance of health institutions and verifying compliance with the regulations and laws regulating medical work. And spotted The Authority’s oversight teams during an oversight tour. The absence of clear mechanisms for documenting medical materials used inside the hospital, and the failure to save files related to […]', 'كشفت الهيئة المركزية للرقابة والتفتيش، الإثنين 16 آذار، عن مخالفات إدارية وفنية في أحد مشافي محافظة ريف دمشق، وذلك في إطار متابعة أداء المؤسسات الصحية والتحقق من الالتزام بالأنظمة والقوانين الناظمة للعمل الطبي. ورصدت الفرق الرقابية التابعة للهيئة خلال جولة رقابية غياب آليات واضحة لتوثيق المواد الطبية المستخدمة داخل المشفى، وعدم حفظ الأضابير الخاصة بملفات المرضى وفق الأصول القانونية، إضافة إلى إهمال متابعة الإجراءات الفنية اللازمة لصيانة الأجهزة الطبية المتوقفة عن العمل، وغياب عدد من العاملين أثناء تنفيذ الجولة. وأوضحت الهيئة أنه وبناءً على نتائج التفتيش فقد تم اتخاذ إجراءات تصحيحية وعقابية شملت توجيه عقوبة التنبيه لعدد من العاملين المقصرين، واحتساب غياب الموظفين غير المتواجدين كإجازة بلا أجر، إلى جانب الإيعاز بإصلاح الأجهزة الطبية المعطلة ورفد المشفى بالكوادر اللازمة، مع اعتماد سجلات لتوثيق الإجراءات والخدمات المقدمة. وأشارت إلى أن هذه ال Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d9%82%d8%a7%d8%a8%d8%a9-%d9%88%d8%a7%d9%84%d8%aa%d9%81%d8%aa%d9%8a%d8%b4-%d8%aa%d9%83%d8%b4%d9%81-%d9%85%d8%ae%d8%a7%d9%84%d9%81%d8%a7%d8%aa-%d8%a5%d8%af%d8%a7%d8%b1%d9%8a%d8%a9-2/', 'On Monday, March 16, the Central Authority for Control and Inspection revealed administrative and technical violations in a hospital in the Damascus countryside governorate, within the framework of monitoring the performance of health institutions and verifying compliance with the regulations and laws regulating medical work. And spotted The Authority’s oversight teams during a monitoring tour. The absence of clear mechanisms for documenting the medical materials used inside the hospital, and the failure to keep files related to patient files in accordance with legal procedures, in addition to neglecting to follow up on the necessary technical procedures. To maintain medical equipment that has stopped working, and the absence of a number of workers during the tour. The authority explained that, based on the results of the inspection, corrective and punitive measures were taken, including directing warning penalties to a number of negligent employees. The absence of employees who are not present is counted as unpaid leave, in addition to instructions to repair broken medical equipment and provide the hospital with the necessary personnel, while adopting records to document the procedures and services provided. She indicated that this Source: https://alikhbariah.com/%d8%a7%d9%84%d8%b1%d9%82%d8%a7%d8%a8%d8%a9-%d9%88%d8%a7%d9%84%d8%aa%d9%81%d8%aa%d9%8a% d8%b4-%d8%aa%d9%83%d8%b4%d9%81-%d9%85%d8%ae%d8%a7%d9%84%d9%81%d8%a7%d8%aa-%d8%a5%d8%af%d8%a7%d8%b1%d9%8a%d8%a9 -2/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Oversight-and-inspection-uncovers-administrative-and-technical-violations-in-a-hospital-in-rural-Damascus.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 7 limit 1), '2026-03-16T17:50:26+03:00'::timestamptz, false, false, false, 127),
  ('وزير الدفاع يتفقد مستشفى دمشق العسكري استعداداً لافتتاحه', 'The Minister of Defense inspects Damascus Military Hospital in preparation for its opening', 'أجرى وزير الدفاع مرهف أبو قصرة جولة تفقدية في مستشفى دمشق العسكري، رفقة مدير المستشفى سالم عبدان، للاطلاع على التحضيرات النهائية قبيل افتتاح المستشفى من قبل إدارة الخدمات الطبية العسكرية. وأشارت الوزارة عبر معرفاتها الرسمية الخميس 12 آذار، إلى أن المستشفى سيبدأ قريباً بتقديم خدماته الطبية للعسكريين، إضافة إلى الأهالي وفق الخطة الموضوعة. وفي 23 […]', 'Defense Minister Murhaf Abu Qasra conducted an inspection tour of Damascus Military Hospital, accompanied by the hospital director, Salem Abdan, to see the final preparations ahead of the opening of the hospital by the Military Medical Services Administration. The Ministry indicated through its identifiers Official announcement Thursday, March 12, that the hospital will soon begin providing medical services to soldiers, in addition to families, according to the established plan. On the 23rd […]', 'أجرى وزير الدفاع مرهف أبو قصرة جولة تفقدية في مستشفى دمشق العسكري، رفقة مدير المستشفى سالم عبدان، للاطلاع على التحضيرات النهائية قبيل افتتاح المستشفى من قبل إدارة الخدمات الطبية العسكرية. وأشارت الوزارة عبر معرفاتها الرسمية الخميس 12 آذار، إلى أن المستشفى سيبدأ قريباً بتقديم خدماته الطبية للعسكريين، إضافة إلى الأهالي وفق الخطة الموضوعة. وفي 23 تشرين الأول، أعلنت إدارة الخدمات الطبية العسكرية في وزارة الدفاع عن رغبتها ب التعاقد مع عدد من خريجي الكليات والمعاهد في مختلف الاختصاصات، ضمن مشفى دمشق العسكري، وذلك لرفده بالكادر الطبي المناسب. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%af%d9%81%d8%a7%d8%b9-%d9%8a%d8%aa%d9%81%d9%82%d8%af-%d9%85%d8%b3%d8%aa%d8%b4%d9%81%d9%89-%d8%af%d9%85%d8%b4%d9%82-%d8%a7%d9%84%d8%b9%d8%b3%d9%83%d8%b1%d9%8a/', 'Defense Minister Murhaf Abu Qasra conducted an inspection tour of Damascus Military Hospital, accompanied by the hospital director, Salem Abdan, to see the final preparations ahead of the opening of the hospital by the Military Medical Services Administration. The Ministry indicated through its identifiers Official announcement Thursday, March 12, that the hospital will soon begin providing medical services to soldiers, in addition to families, according to the established plan. On October 23, the Department of Military Medical Services at the Ministry of Defense announced its desire to contract with A number of graduates of colleges and institutes in various specialties, within the Damascus Military Hospital, in order to provide it with the appropriate medical staff. Source: https://alikhbariah.com/%d9%88%d8%b2%d9%8a%d8%b1-%d8%a7%d9%84%d8%af%d9%81%d8%a7%d8%b9-%d9%8a%d8%aa%d9%81%d9%82 %d8%af-%d9%85%d8%b3%d8%aa%d8%b4%d9%81%d9%89-%d8%af%d9%85%d8%b4%d9%82-%d8%a7%d9%84%d8%b9%d8%b3%d9%83%d8%b1%d9%8 a/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Defense-Minister-Marhaf-Abu-Qasra-5.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 8 limit 1), '2026-03-12T10:13:50+03:00'::timestamptz, false, false, false, 126),
  ('افتتاح أول مركز تخصصي لغسيل الكلى جنوب إدلب', 'Opening of the first specialized dialysis center in southern Idlib', 'افتتح وزير الصحة مصعب العلي، الأربعاء 11 آذار، مركز الرعاية الثالثة المتخصص بغسيل الكلى، والذي يعد المركز الوحيد من نوعه في ريف إدلب الجنوبي. ويهدف المركز الذي جهز بـ27 سريراً، إلى تعزيز الرعاية الصحية في المنطقة وتخفيف معاناة المرضى عبر توفير العلاج اللازم بالقرب من مناطق سكنهم، وفق ما أوردت وزارة الصحة عبر معرفاتها الرسمية. […]', 'On Wednesday, March 11, Minister of Health Musab Al-Ali opened the tertiary care center specializing in dialysis, which is the only center of its kind in the southern countryside of Idlib. The center, which is equipped with 27 beds, aims to enhance health care in the region and reduce... The suffering of patients through the provision of necessary treatment near their areas of residence, according to what the Ministry of Health reported through its official accounts. […]', 'افتتح وزير الصحة مصعب العلي، الأربعاء 11 آذار، مركز الرعاية الثالثة المتخصص بغسيل الكلى، والذي يعد المركز الوحيد من نوعه في ريف إدلب الجنوبي. ويهدف المركز الذي جهز بـ27 سريراً، إلى تعزيز الرعاية الصحية في المنطقة وتخفيف معاناة المرضى عبر توفير العلاج اللازم بالقرب من مناطق سكنهم، وفق ما أوردت وزارة الصحة عبر معرفاتها الرسمية. وأواخر تشرين الأول الفائت، افتتح العلي، قسم غسيل الكلى في مشفى حماة الوطني، وذلك بعد تأهيله وتجهيزه، بهدف تطوير مراكز الغسيل الكلوي وتحسين جودة الخدمات الطبية في مختلف المحافظات. وقال وزير الصحة حينها، إنه “تم تزويد القسم بـ30 جهازاً حديثاً مقدمة من وزارة الصحة بالتعاون مع منظمة “ميدغلوبل” و”منظمة الإغاثة الإسلامية” ، وفق ما نقلت معرفات الوزارة الرسمية. وأكد الوزير أن افتتاح قسم غسيل الكلى يشكل خطوة نوعية لتحسين الخدمات لمرضى الكلى، ويخدم القسم نحو 300 مريض من محافظة حماة. Source: https://alikhbariah.com/%d8%a7%d9%81%d8%aa%d8%aa%d8%a7%d8%ad-%d8%a3%d9%88%d9%84-%d9%85%d8%b1%d9%83%d8%b2-%d8%aa%d8%ae%d8%b5%d8%b5%d9%8a-%d9%84%d8%ba%d8%b3%d9%8a%d9%84-%d8%a7%d9%84%d9%83%d9%84%d9%89-%d8%ac%d9%86%d9%88%d8%a8/', 'On Wednesday, March 11, Minister of Health Musab Al-Ali opened the tertiary care center specializing in dialysis, which is the only center of its kind in the southern countryside of Idlib. The center, which is equipped with 27 beds, aims to enhance health care in the region and reduce... The suffering of patients through the provision of necessary treatment near their areas of residence, according to what the Ministry of Health reported through its official accounts. In late October, Al-Ali opened the dialysis department at Hama National Hospital, after rehabilitating and equipping it, with the aim of developing Dialysis centers and improving the quality of medical services in various governorates. The Minister of Health said at the time, “The department was provided with 30 modern devices provided by the Ministry of Health in cooperation with the MedGlobal Organization and the Islamic Relief Organization,” according to what was reported. Official Ministry IDs. The Minister stressed that the opening of the dialysis department constitutes a qualitative step to improve services for kidney patients, and the department serves about 300 patients from Hama Governorate. Source: https://alikhbariah.com/%d8%a7%d9%81%d8%aa%d8%aa%d8%a7%d8%ad-%d8%a3%d9%88%d9%84-%d9%85%d8%b1%d9%83%d8%b2-%d8%a a%d8%ae%d8%b5%d8%b5%d9%8a-%d9%84%d8%ba%d8%b3%d9%8a%d9%84-%d8%a7%d9%84%d9%83%d9%84%d9%89-%d8%ac%d9%86%d9%88%d8% a8/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Kidney-Dialysis-Center.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 9 limit 1), '2026-03-11T21:10:43+03:00'::timestamptz, false, false, false, 125),
  ('وزارة الصحة تزود مستشفى الرقة للأطفال بمعدات طبية حديثة', 'The Ministry of Health provides Al-Raqqa Children''s Hospital with modern medical equipment', 'زوّدت وزارة الصحة مديرية صحة الرقة بعدد من الأجهزة والمعدّات الطبية الحديثة، بهدف تعزيز قدراتها على تلبية الاحتياجات المتزايدة للسكان. وقالت وزارة الصحة عبر معرفاتها الرسمية، الأربعاء 11 آذار، إنه تم تزويد مشفى الأطفال التخصصي في الرقة بتجهيزات نوعية شملت ثلاث حواضن للعناية بالوليد وثلاث حواضن عادية، إضافة إلى ثلاث حواضن أوتوماتيكية، مما يسهم في […]', 'The Ministry of Health provided the Raqqa Health Directorate with a number of modern medical devices and equipment, with the aim of enhancing its capabilities to meet the growing needs of the population. The Ministry of Health said through its official accounts, on Wednesday, March 11, that the Children’s Hospital had been provided The Specialist Specialist Hospital in Raqqa provided quality equipment that included three incubators for newborn care and three regular incubators, in addition to three automatic incubators, which contributes to [...]', 'زوّدت وزارة الصحة مديرية صحة الرقة بعدد من الأجهزة والمعدّات الطبية الحديثة، بهدف تعزيز قدراتها على تلبية الاحتياجات المتزايدة للسكان. وقالت وزارة الصحة عبر معرفاتها الرسمية، الأربعاء 11 آذار، إنه تم تزويد مشفى الأطفال التخصصي في الرقة بتجهيزات نوعية شملت ثلاث حواضن للعناية بالوليد وثلاث حواضن عادية، إضافة إلى ثلاث حواضن أوتوماتيكية، مما يسهم في رفع مستوى الرعاية الصحية المقدّمة للأطفال حديثي الولادة. وأكد مدير صحة الرقة عبدالله الحمود أن هذه التجهيزات ستسهم بشكل فاعل في تحسين جودة الخدمات الطبية وتخفيف الأعباء المادية عن الأهالي، مشيراً إلى استمرار جهود التحديث والتطوير لضمان كفاءة جميع المرافق الصحية في عموم المحافظة. وفي 24 كانون الثاني، سلّمت وزارة الصحة 20 جهازاً حديثاً لغسيل الكلى إلى مستشفى الرقة الوطني، ضمن جهود تطوير القطاع الصحي في المحافظة لخدمة ما يقارب 380 مريضاً بالقصور الكلوي. وتأتي هذه الخطوات استجابة مباشرة لاحتياجات المح Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%aa%d8%b2%d9%88%d8%af-%d9%85%d8%b3%d8%aa%d8%b4%d9%81%d9%89-%d8%a7%d9%84%d8%b1%d9%82%d8%a9-%d9%84%d9%84%d8%a3%d8%b7%d9%81%d8%a7%d9%84/', 'The Ministry of Health provided the Raqqa Health Directorate with a number of modern medical devices and equipment, with the aim of enhancing its capabilities to meet the growing needs of the population. The Ministry of Health said through its official accounts, on Wednesday, March 11, that the Children’s Hospital had been provided The specialist hospital in Raqqa has quality equipment that includes three neonatal care incubators and three regular incubators, in addition to three automatic incubators, which contributes to raising the level of health care provided to newborns. Raqqa Health Director Abdullah confirmed Al-Hamoud said that these equipment will contribute effectively to improving the quality of medical services and reducing the financial burdens on the people, indicating the continuation of modernization and development efforts to ensure the efficiency of all health facilities throughout the governorate. On January 24, The Ministry of Health delivered 20 modern dialysis machines to Raqqa National Hospital, as part of efforts to develop the health sector in the governorate to serve approximately 380 patients with renal failure. These steps come in direct response to the needs of the community. Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%aa%d8%b2%d9%88%d8%af -%d9%85%d8%b3%d8%aa%d8%b4%d9%81%d9%89-%d8%a7%d9%84%d8%b1%d9%82%d8%a9-%d9%84%d9%84%d8%a3%d8%b7%d9%81%d8%a7%d9%8 4/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Medical-equipment.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 10 limit 1), '2026-03-11T12:00:03+03:00'::timestamptz, false, false, false, 124),
  ('مديرية صحة دير الزور تطالب المشافي والمراكز الطبية باستكمال الترخيص', 'Deir ez-Zor Health Directorate requires hospitals and medical centers to complete licensing', 'أصدرت مديرية صحة دير الزور، الثلاثاء 10 آذار، تعميماً موجهاً إلى جميع المشافي والمراكز الطبية الخاصة والخيرية، دعت فيه أصحاب المنشآت إلى مراجعة المديرية خلال أسبوع عمل لاستكمال إجراءات الترخيص وتحديث بياناتهم. وذكرت المديرية عبر معرفاتها الرسمية أن التعميم يشمل جميع المنشآت الصحية — المرخصة والعاملة، أو المرخصة غير العاملة، أو غير المرخصة — بهدف […]', 'On Tuesday, March 10, the Deir ez-Zor Health Directorate issued a circular addressed to all hospitals and private and charitable medical centers, calling on facility owners to visit the directorate within a working week to complete licensing procedures and update their data. And I mentioned The Directorate, through its official information, stated that the circular includes all health facilities - licensed and operating, licensed but not operating, or unlicensed - with the aim of […]', 'أصدرت مديرية صحة دير الزور، الثلاثاء 10 آذار، تعميماً موجهاً إلى جميع المشافي والمراكز الطبية الخاصة والخيرية، دعت فيه أصحاب المنشآت إلى مراجعة المديرية خلال أسبوع عمل لاستكمال إجراءات الترخيص وتحديث بياناتهم. وذكرت المديرية عبر معرفاتها الرسمية أن التعميم يشمل جميع المنشآت الصحية — المرخصة والعاملة، أو المرخصة غير العاملة، أو غير المرخصة — بهدف تحديث البيانات لدى دائرة المنشآت الصحية، بما يحقق المصلحة العامة. ونوهت المديرية بأن عملية المراجعة ستعتمد لإعادة تقييم المنشآت ومنح التراخيص، مؤكدة أن عدم المراجعة يجعل الإجراءات غير قانونية، ويعرّض أصحاب المنشآت لعقوبات قد تصل إلى إغلاق المراكز غير المسجلة بعد انتهاء المهلة المحددة. وفي سياق آخر، عقدت مديرية صحة دير الزور اجتماعاً مع وفد من اللجنة الدولية للصليب الأحمر (ICRC) وبرنامج الأمم المتحدة الإنمائي (UNDP)، لبحث دعم مراكز العلاج الفيزيائي وتركيب الأطراف الصناعية، وتطوير آليات العمل في الم Source: https://alikhbariah.com/%d9%85%d8%af%d9%8a%d8%b1%d9%8a%d8%a9-%d8%b5%d8%ad%d8%a9-%d8%af%d9%8a%d8%b1-%d8%a7%d9%84%d8%b2%d9%88%d8%b1-%d8%aa%d8%b7%d8%a7%d9%84%d8%a8-%d8%a7%d9%84%d9%85%d8%b4%d8%a7%d9%81%d9%8a-%d9%88%d8%a7%d9%84/', 'On Tuesday, March 10, the Deir ez-Zor Health Directorate issued a circular addressed to all hospitals and private and charitable medical centers, calling on facility owners to visit the directorate within a working week to complete licensing procedures and update their data. And I mentioned The Directorate, through its official identifiers, stated that the circular includes all health facilities - licensed and operating, licensed but not operating, or unlicensed - with the aim of updating data with the Health Facilities Department, in a way that achieves the public interest. The Directorate noted that The review process will be adopted to re-evaluate the facilities and grant licenses, stressing that failure to review makes the procedures illegal, and exposes the owners of the facilities to penalties that may amount to the closure of unregistered centers after the specified deadline has expired. In another context, it was held Deir ez-Zor Health Directorate held a meeting with a delegation from the International Committee of the Red Cross (ICRC) and the United Nations Development Program (UNDP), to discuss support for physical therapy centers and the installation of prosthetic limbs, and developing work mechanisms in the areas. Source: https://alikhbariah.com/%d9%85%d8%af%d9%8a%d8%b1%d9%8a%d8%a9-%d8%b5%d8%ad%d8%a9-%d8%af%d9%8a%d8%b1-%d8%a7%d9%8 4%d8%b2%d9%88%d8%b1-%d8%aa%d8%b7%d8%a7%d9%84%d8%a8-%d8%a7%d9%84%d9%85%d8%b4%d8%a7%d9%81%d9%8a-%d9%88%d8%a7%d9% 84/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Deir-ez-Zor-Health-Directorate.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 11 limit 1), '2026-03-10T16:30:40+03:00'::timestamptz, false, false, false, 123),
  ('وزارة الصحة: استلمنا 10 شاحنات أدوية لمرضى التلاسيميا والكلى', 'Ministry of Health: We received 10 trucks of medicines for thalassemia and kidney patients', 'أعلنت وزارة الصحة الإثنين 9 آذار، استلام 10 شاحنات محملة بالأدوية والمستلزمات الطبية المخصصة لمرضى التلاسيميا وأمراض الكلى، بتمويل من مركز الملك سلمان للإغاثة وبالتعاون مع جمعية الأمين للمساندة الإنسانية. وأوضحت الوزارة في منشور لها على منصاتها في وسائل التواصل، أن هذه الأدوية ستوزع على مديريات الصحة في مختلف المحافظات، مشيرة إلى أن الكميات التي […]', 'The Ministry of Health announced on Monday, March 9, the receipt of 10 trucks loaded with medicines and medical supplies intended for patients with thalassemia and kidney disease, with funding from the King Salman Relief Center and in cooperation with the Al-Amin Society for Humanitarian Support. The ministry explained In a post on her social media platforms, she stated that these medicines will be distributed to health directorates in the various governorates, noting that the quantities […]', 'أعلنت وزارة الصحة الإثنين 9 آذار، استلام 10 شاحنات محملة بالأدوية والمستلزمات الطبية المخصصة لمرضى التلاسيميا وأمراض الكلى، بتمويل من مركز الملك سلمان للإغاثة وبالتعاون مع جمعية الأمين للمساندة الإنسانية. وأوضحت الوزارة في منشور لها على منصاتها في وسائل التواصل، أن هذه الأدوية ستوزع على مديريات الصحة في مختلف المحافظات، مشيرة إلى أن الكميات التي جرى تأمينها كافية لتغطية احتياجات مرضى التلاسيميا لمدة عام كامل. من جهته، أكد وزير الصحة الدكتور مصعب العلي أن الوزارة تعمل على استكمال تأمين بقية البرامج العلاجية والأدوية البيولوجية، بما في ذلك أدوية التصلب اللويحي وأدوية السرطان. وأوضح العلي أنه تم تأمين جزء من هذه الأدوية فيما تتواصل الجهود لتوفير الكميات المتبقية رغم التحديات القائمة، بهدف تخفيف معاناة المرضى وتحسين جودة الرعاية الصحية المقدمة لهم. وسبق أن وزعت مديرية صحة ريف دمشق بالتعاون مع الجمعية الطبية السورية الأمريكية (SAMS) 12 جهاز فح Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%a7%d8%b3%d8%aa%d9%84%d9%85%d9%86%d8%a7-10-%d8%b4%d8%a7%d8%ad%d9%86%d8%a7%d8%aa-%d8%a3%d8%af%d9%88%d9%8a%d8%a9-%d9%84%d9%85%d8%b1/', 'The Ministry of Health announced on Monday, March 9, the receipt of 10 trucks loaded with medicines and medical supplies intended for patients with thalassemia and kidney disease, with funding from the King Salman Relief Center and in cooperation with the Al-Amin Society for Humanitarian Support. The ministry explained In a post on her social media platforms, she stated that these medicines will be distributed to health directorates in various governorates, noting that the quantities secured are sufficient to cover the needs of thalassemia patients for an entire year. For his part, the Minister of Health confirmed Dr. Musab Al-Ali said that the Ministry is working to complete the provision of the rest of the therapeutic programs and biological medicines, including multiple sclerosis medicines and cancer medicines. Al-Ali explained that some of these medicines have been secured, while efforts are continuing to provide them The remaining quantities are available despite the existing challenges, with the aim of alleviating the suffering of patients and improving the quality of health care provided to them. The Damascus Countryside Health Directorate, in cooperation with the Syrian American Medical Society (SAMS), previously distributed 12 screening devices. Source: https://alikhbariah.com/%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%a7%d8%b3%d8%aa%d9%8 4%d9%85%d9%86%d8%a7-10-%d8%b4%d8%a7%d8%ad%d9%86%d8%a7%d8%aa-%d8%a3%d8%af%d9%88%d9%8a%d8%a9-%d9%84%d9%85%d8%b1/', 'https://alikhbariah.com/wp-content/uploads/2026/03/medical-supplies.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 12 limit 1), '2026-03-09T17:30:31+03:00'::timestamptz, false, false, false, 122),
  ('لتعزيز خدمات الرعاية.. وزارة الصحة تفتتح 5 مراكز صحية جديدة في ريف إدلب', 'To enhance care services...the Ministry of Health opens 5 new health centers in the Idlib countryside', 'افتتح وزير الصحة مصعب العلي خمسة مراكز صحية جديدة في ريف إدلب، الإثنين 9 آذار، في خطوة تهدف إلى تعزيز القطاع الصحي وتوسيع نطاق الخدمات الطبية وتحسين مستوى الرعاية الصحية المقدمة للأهالي. وأوضحت محافظة إدلب عبر معرفاتها الرسمية أن افتتاح المراكز الجديدة جرى برفقة محافظ إدلب محمد عبد الرحمن، وشمل مدن وبلدات آفس ومعردبسة ومعصران […]', 'The Minister of Health, Musab Al-Ali, opened five new health centers in the Idlib countryside, Monday, March 9, in a step aimed at strengthening the health sector, expanding the scope of medical services, and improving the level of health care provided to the people. Idlib Governorate was explained through its identifiers Officially, the opening of the new centers took place accompanied by the Governor of Idlib, Muhammad Abd al-Rahman, and included the cities and towns of Afes, Maardabsa, and Maasran […]', 'افتتح وزير الصحة مصعب العلي خمسة مراكز صحية جديدة في ريف إدلب، الإثنين 9 آذار، في خطوة تهدف إلى تعزيز القطاع الصحي وتوسيع نطاق الخدمات الطبية وتحسين مستوى الرعاية الصحية المقدمة للأهالي. وأوضحت محافظة إدلب عب ر معرفاتها الرسمية أن افتتاح المراكز الجديدة جرى برفقة محافظ إدلب محمد عبد الرحمن، وشمل مدن وبلدات آفس ومعردبسة ومعصران وناحية حيش وبلدة التح، وذلك بهدف تلبية احتياجات السكان الصحية في ريف المحافظة. وخلال جولته، تفقد وزير الصحة ومحافظ إدلب شحنات الأدوية المخصصة لمرضى القصور الكلوي والتلاسيميا، تمهيداً لتوزيعها على المراكز الطبية في مختلف المحافظات السورية. وكان وزير الصحة مصعب العلي، قد افتتح ب رفقة محافظ حلب عزام غريب ومدير صحة حلب محمد وجيه جمعة، أمس الأحد 8 آذار عدداً من المشاريع الصحية في محافظة حلب، بهدف رفع كفاءة الخدمات وتسهيل وصولها للأهالي. وأشارت وزارة الصحة إلى أن المشاريع شملت افتتاح مستشفى منبج الجديد في ريف حلب الشرقي،  Source: https://alikhbariah.com/%d9%84%d8%aa%d8%b9%d8%b2%d9%8a%d8%b2-%d8%ae%d8%af%d9%85%d8%a7%d8%aa-%d8%a7%d9%84%d8%b1%d8%b9%d8%a7%d9%8a%d8%a9-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%aa%d9%81%d8%aa%d8%aa/', 'The Minister of Health, Musab Al-Ali, opened five new health centers in the Idlib countryside, Monday, March 9, in a step aimed at strengthening the health sector, expanding the scope of medical services, and improving the level of health care provided to the people. Idlib Governorate was explained through its identifiers The official statement said that the opening of the new centers took place accompanied by the Governor of Idlib, Muhammad Abd al-Rahman, and included the cities and towns of Afes, Maardabsa, Maasran, the district of Haysh, and the town of al-Tah, with the aim of meeting the health needs of the population in the governorate’s countryside. During his tour, he visited the Minister of Health The Idlib Governorate delivers shipments of medicines intended for patients with renal failure and thalassemia, in preparation for distributing them to medical centers in various Syrian governorates. The Minister of Health, Musab Al-Ali, opened the ceremony, accompanied by the Governor of Aleppo, Azzam Gharib, and the Director of Aleppo Health, Muhammad Wajih Yesterday, Friday, Sunday, March 8, a number of health projects were launched in Aleppo Governorate, with the aim of raising the efficiency of services and facilitating their access to the people. The Ministry of Health indicated that the projects included the opening of the new Manbij Hospital in the eastern countryside of Aleppo, Source: https://alikhbariah.com/%d9%84%d8%aa%d8%b9%d8%b2%d9%8a%d8%b2-%d8%ae%d8%af%d9%85%d8%a7%d8%aa-%d8%a7%d9%84%d8%b1 %d8%b9%d8%a7%d9%8a%d8%a9-%d9%88%d8%b2%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d8%b5%d8%ad%d8%a9-%d8%aa%d9%81%d8%aa%d8%a a/', 'https://alikhbariah.com/wp-content/uploads/2026/03/Opening-of-a-medical-center.jpg', (select id from public.categories where slug = 'news-health' and type = 'news' limit 1), (select id from public.locations order by id offset 13 limit 1), '2026-03-09T16:45:18+03:00'::timestamptz, false, false, false, 121)
